BEGIN;
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '01d53658-4779-50d7-a6ae-c3b56c0ef963','Replay characteristic','The standardised playback equalisation curve applied when reproducing analogue tape, specified as a set of frequency time constants in microseconds that compensate for the deliberately non-flat record characteristic. Common standards include CCIR/IEC1, IEC2, NAB and DIN, chosen according to tape speed and format.','Tape is not recorded with an even tone balance. On playback the machine must add a matching curve so it sounds right. This playback curve is the replay characteristic. The right one depends on the tape''s speed and format.','It exists so recordings play back with flat, accurate frequency response; the wrong curve leaves the sound too bright or too dull and also corrupts noise-reduction decoding.','A transfer technician selects the replay characteristic, for example NAB or IEC, to match how the tape was recorded, guided by tape speed, box notes, line-up tones or the character of the hiss.','Replay Equalization',ARRAY['Reference transfer','Sliding-band companding','NAB equalization','Azimuth','Line-up tones']::text[],ARRAY['Playing a tape with the wrong curve, for example NAB instead of IEC/CCIR, giving a dull or overbright transfer.','Assuming one speed always uses one curve, when standards changed over time and overlap.','Setting equalisation without regard to the noise-reduction decoder, which the curve also affects.']::text[],ARRAY['Choosing NAB or IEC equalisation for a 15 ips studio master.','Matching the correct curve to a slow-speed logging tape with no documentation.','Setting replay equalisation before decoding a Dolby-encoded tape.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='01d53658-4779-50d7-a6ae-c3b56c0ef963' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Replay characteristic'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '01d53658-4779-50d7-a6ae-c3b56c0ef963','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='01d53658-4779-50d7-a6ae-c3b56c0ef963' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1b98c6b1-83b6-5da9-9c36-5b993bffadbe','Shell azimuth','In cassette and cartridge formats, the azimuth angle, the perpendicularity of the head gap to the direction of tape travel, as constrained by the tape''s path through its shell. A warped, low-quality or damaged shell can hold the tape at an azimuth error relative to the replay head, reducing high-frequency response and, on stereo, disturbing the phase relationship between channels.','Azimuth is the angle between the tape and the head''s reading slot. It must be square, or high notes fade. On a cassette, a cheap or bent case can hold the tape at a slight slant. That throws this angle off.','The idea stresses that on cassettes the shell itself, not just the machine, sets the head-to-tape angle, so a bad shell can cause azimuth error that no deck adjustment fully cures.','When a cassette plays dull or phasey, the technician adjusts the deck''s replay-head azimuth for the brightest, most in-phase sound, and if the shell is at fault rehouses the tape into a better shell.','Head Alignment',ARRAY['Azimuth','Shell warp','Replay characteristic','Rehousing for equalization','Slip sheet']::text[],ARRAY['Blaming the recording for lost treble when a shell-induced azimuth error is the real cause.','Adjusting deck azimuth for one cassette and forgetting to reset it for the next tape.','Assuming digital azimuth (phase) correction restores lost high frequencies, when that information is already gone.']::text[],ARRAY['Transferring a home-recorded cassette that sounds muffled.','Setting replay-head azimuth by ear on a mono cassette with no test tone.','Deciding whether a dull cassette needs azimuth adjustment or rehousing.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1b98c6b1-83b6-5da9-9c36-5b993bffadbe' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Shell azimuth'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '1b98c6b1-83b6-5da9-9c36-5b993bffadbe','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1b98c6b1-83b6-5da9-9c36-5b993bffadbe' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2e86a28c-4125-5961-9126-26c3f5b12205','Shell warp','Physical distortion of a cassette''s plastic shell, from heat, pressure, poor moulding or age, that disturbs the internal tape path. It can cause jamming, uneven tape tension, azimuth error and increased wow and flutter during replay.','A cassette''s plastic case can bend or twist from heat or rough storage. A warped case pinches or misguides the tape inside. That can jam the tape. It can also make the sound wobble and lose treble.','Recognising shell warp tells the technician the fault is in the housing, not the tape or the deck, pointing to rehousing rather than electronic correction.','If a cassette drags, jams or wobbles, the technician inspects the shell for warping and, when found, transfers the tape and its parts into a sound screw-together shell before digitising.','Carrier Degradation',ARRAY['Shell azimuth','Rehousing for equalization','Slip sheet','Slip-sheet buckling','Wow and flutter']::text[],ARRAY['Forcing a warped, jamming cassette to play instead of rehousing it, risking tape damage.','Mistaking wow and flutter from a warped shell for a fault in the deck''s capstan.','Storing cassettes in heat or direct sun, which encourages the shells to warp.']::text[],ARRAY['Assessing a heat-damaged cassette pulled from a car or attic.','Diagnosing repeated jams on an otherwise clean tape.','Rehousing a warped welded shell into a screwed shell for transfer.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2e86a28c-4125-5961-9126-26c3f5b12205' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Shell warp'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '2e86a28c-4125-5961-9126-26c3f5b12205','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='2e86a28c-4125-5961-9126-26c3f5b12205' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c8a3ff99-1621-5a41-a8f2-26ca08dc7027','Sinusoidal interpolation','A signal-reconstruction technique that fills a short gap or replaces damaged samples by modelling the surrounding audio as a sum of sinusoids, with estimated frequencies, amplitudes and phases, and extending or interpolating those components across the missing region. The frequency estimation typically uses spectral-peak interpolation of the short-time Fourier transform.','Steady sounds are made of smooth tones. This method looks at the tones just before and after a damaged spot. It then draws those tones smoothly across the gap. This rebuilds the missing sound, like continuing a wave that was cut.','It exists to repair clicks, dropouts and brief losses without an audible hole, by re-creating plausible signal that matches the tones on either side of the damage.','Using a spectral repair or de-click tool, a restorer selects a short damaged region and lets the software interpolate the sinusoidal content across it, blending the fix with the surrounding audio.','Digital Restoration',ARRAY['Spectral inpainting','Spectral repair','De-click','Interpolation','Short-time Fourier transform']::text[],ARRAY['Using it across gaps too long for the tones to be predicted, producing an obvious artificial patch.','Applying it to noisy or highly transient material where a sinusoidal model fits poorly.','Interpolating over a wanted transient, such as a drum hit, and smearing it.']::text[],ARRAY['Filling a brief dropout in a digitised tape.','Repairing a click that a de-click pass missed.','Rebuilding a few milliseconds lost to a splice or a damaged section.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c8a3ff99-1621-5a41-a8f2-26ca08dc7027' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Sinusoidal interpolation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c8a3ff99-1621-5a41-a8f2-26ca08dc7027','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c8a3ff99-1621-5a41-a8f2-26ca08dc7027' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '15d9ea52-beee-5fea-8efc-4b432dce6cee','Sliding-band companding','A noise-reduction method that compresses signal dynamics on encoding and expands them on decoding (companding) using a single band whose active frequency range slides with the signal, typically a high-frequency band whose lower corner frequency moves according to level. Domestic Dolby B and Dolby C use this sliding-band approach, in contrast to fixed multi-band systems such as Dolby A, hybrid fixed/sliding-band systems such as Dolby SR, and broadband systems such as dbx.','Tape hiss is worst in quiet, high sounds. This system boosts soft high notes while recording. On playback it turns them back down, pulling the hiss down too. A moving filter follows the music so it acts only where hiss would show.','It exists to hide tape hiss without audible pumping, by focusing noise reduction on the high frequencies and moments where hiss is most exposed.','When a tape was encoded with Dolby B or C, the technician plays it through a matching, correctly aligned decoder during transfer, because decoding later is far less reliable.','Noise Reduction',ARRAY['Companding','Dolby noise reduction','dbx','Replay characteristic','Reference transfer']::text[],ARRAY['Decoding with the wrong system, for example dbx instead of Dolby, which mistracks the sound.','Transferring encoded and decoding later, when alignment errors compound and make accurate decoding hard.','Ignoring that replay level and equalisation must be correct or the decoder mistracks.']::text[],ARRAY['Decoding a Dolby B cassette during a preservation transfer.','Identifying by ear whether a tape carries noise reduction.','Aligning replay level to line-up tones before decoding.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='15d9ea52-beee-5fea-8efc-4b432dce6cee' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Sliding-band companding'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '15d9ea52-beee-5fea-8efc-4b432dce6cee','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='15d9ea52-beee-5fea-8efc-4b432dce6cee' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b9226897-e838-5b81-9d6d-8780e6549c06','Slip sheet','In compact-cassette construction, a slip sheet (liner or lubricating sheet) is a thin, low-friction sheet, often graphite-coated or of a slick polymer, placed between each face of the tape pack and the inner wall of the shell. It reduces friction so the tape winds and moves smoothly and evenly.','Inside a cassette are two thin slippery sheets, one on each side of the tape coil. They let the tape slide smoothly against the case as it winds. Without them the tape would drag and its speed would wobble.','They exist to cut friction inside the shell, keeping tape motion smooth and steady so speed stays even and wow and flutter stay low.','When rehousing a cassette, the technician keeps and refits the slip sheets, along with the rollers and pressure pad, because leaving them out causes drag and speed problems.','Cassette Components',ARRAY['Slip-sheet buckling','Rehousing for equalization','Shell warp','Pressure pad','Wow and flutter']::text[],ARRAY['Discarding the slip sheets when opening a shell, then getting drag and wow after reassembly.','Refitting creased or dirty slip sheets, which cause uneven tape motion.','Confusing the cassette slip sheet with the paper index card in the case.']::text[],ARRAY['Rehousing a tape from a jamming welded shell into a screw shell.','Diagnosing new wow after a cassette repair.','Salvaging usable parts from a donor cassette shell.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b9226897-e838-5b81-9d6d-8780e6549c06' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Slip sheet'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b9226897-e838-5b81-9d6d-8780e6549c06','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b9226897-e838-5b81-9d6d-8780e6549c06' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ef4e710a-0e94-520e-ae63-07e4ccb131ec','Slip-sheet buckling','A fault in which a cassette''s internal liner (slip) sheets warp, cockle or fold, from heat, humidity or age, so they no longer lie flat against the pack. The buckled sheets add friction and drag, causing the tape to run unevenly or jam and raising wow and flutter.','The thin slippery sheets inside a cassette can wrinkle or fold over time. When they stop lying flat, they rub and grab the tape. This makes the tape drag, wobble in speed, or jam.','Naming this fault points the technician to the liner sheets as the cause of drag or speed trouble, so the fix is rehousing rather than adjusting the deck.','On a cassette that drags or wows, the technician opens the shell, sees the buckled slip sheets, and rehouses the tape with fresh flat liner sheets in a good shell.','Carrier Degradation',ARRAY['Slip sheet','Shell warp','Rehousing for equalization','Wow and flutter','Pressure pad']::text[],ARRAY['Blaming the deck''s capstan for wow when buckled liner sheets are the real cause.','Reusing buckled sheets during a rehouse instead of replacing them.','Forcing a jamming cassette to keep playing instead of stopping and rehousing, risking creasing or snapping the tape.']::text[],ARRAY['Inspecting a humidity-damaged cassette before transfer.','Diagnosing intermittent drag on an old tape.','Deciding to rehouse rather than digitise a jamming cassette as it is.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ef4e710a-0e94-520e-ae63-07e4ccb131ec' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Slip-sheet buckling'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'ef4e710a-0e94-520e-ae63-07e4ccb131ec','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ef4e710a-0e94-520e-ae63-07e4ccb131ec' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '10cc126d-2b5c-5d59-848c-f1841be60ad5','Source intercutting','In restoration and preservation editing, the practice of assembling the most complete and least-damaged version of a recording by intercutting, editing together corresponding passages taken from two or more different source copies, generations or takes, switching at each point to whichever source is cleanest or most intact.','Sometimes no single copy of a recording is perfect. Each copy may be clean in different places. This method stitches the best parts of each copy together. The result is one clean version.','It exists to recover a whole, clean programme when every surviving source has different damage, dropouts or gaps.','Holding two dubs of the same broadcast, the restorer aligns them and cuts between them, taking each section from whichever copy is free of clicks, dropouts or noise.','Transfer Workflow',ARRAY['Best copy selection','Reference transfer','Spectral inpainting','De-click','Splice']::text[],ARRAY['Intercutting without precisely aligning the sources, causing audible jumps in level, pitch or room tone.','Switching sources mid-phrase where the edit is exposed, rather than at a natural gap.','Failing to document which source each section came from.']::text[],ARRAY['Rebuilding a complete concert from two incomplete tape copies.','Filling a damaged passage on the best copy with clean audio from a lesser copy.','Restoring a broadcast where each surviving dub has different dropouts.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='10cc126d-2b5c-5d59-848c-f1841be60ad5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Source intercutting'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '10cc126d-2b5c-5d59-848c-f1841be60ad5','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='10cc126d-2b5c-5d59-848c-f1841be60ad5' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1d13948f-79da-562d-9970-76f11e8a428d','Spectral inpainting','A restoration technique that reconstructs missing or corrupted regions of a time-frequency representation (spectrogram) by inferring plausible spectral content from the surrounding, undamaged time-frequency data, the audio analogue of image inpainting. It is used to conceal short gaps, transient damage or the holes left after removing interference.','A spectrogram is a picture of sound over time and pitch. Damage leaves blank or wrong patches in it. This method fills those patches using the sound around them. It works much like fixing a torn photo.','It exists to replace lost or damaged sound with content that matches its surroundings, so a repair is inaudible rather than a silent hole or a smear.','In a spectral editor, a restorer selects a damaged area of the spectrogram and applies an inpainting or replace function that rebuilds it from nearby audio.','Digital Restoration',ARRAY['Sinusoidal interpolation','Spectral repair','De-click','Spectrogram','Source intercutting']::text[],ARRAY['Inpainting regions too large to guess from context, giving blurred or unnatural results.','Selecting sloppily and altering wanted sound next to the damage.','Relying on inpainting for faults better fixed at source, such as re-transferring the tape.']::text[],ARRAY['Removing a cough from a solo passage and rebuilding the notes behind it.','Repairing transient damage a broadband denoiser cannot fix.','Filling a short spectrogram gap left after deleting interference.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1d13948f-79da-562d-9970-76f11e8a428d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Spectral inpainting'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '1d13948f-79da-562d-9970-76f11e8a428d','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1d13948f-79da-562d-9970-76f11e8a428d' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '94ac1230-a64e-5685-869b-c0f9a880d4c1','Speed error','A deviation of a recording''s replay speed from the exact speed at which it was originally recorded, so that the reproduced audio is shifted in pitch and altered in duration. It arises from transport speed inaccuracy, incorrect speed selection, tape stretch or shrinkage, worn capstans, or differences between recording and replay standards.','Speed error means a tape plays back faster or slower than it was recorded. When that happens, the pitch goes too high or too low. The whole recording also runs too short or too long.','Naming the fault lets an archivist recognise and correct wrong replay speed so a transfer reproduces the true pitch and timing of the original performance rather than a distorted version of it.','During transfer a technician checks replay speed against a known reference, such as recorded mains hum or a line-up tone, and adjusts the machine or corrects the digital file until the pitch is right.','Speed & Timing',ARRAY['Speed-error signature','Timebase error','Wow and flutter','Transfer calibration tone','Pitch correction']::text[],ARRAY['Assuming the tape''s labelled speed is correct and transferring at that setting without verifying pitch against a reference.','Confusing a constant speed error, which shifts pitch uniformly, with wow and flutter, which vary the speed moment to moment.','Correcting pitch by ear alone and locking in an offset instead of using a measurable reference such as recorded hum.']::text[],ARRAY['Transferring a reel recorded on a machine whose motor ran slightly fast, leaving every note sharp.','Digitising a field recording made at a nominal speed on a portable recorder with an unstable transport.','Replaying a tape on a different machine or in a different mains-frequency region than where it was recorded.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='94ac1230-a64e-5685-869b-c0f9a880d4c1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Speed error'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '94ac1230-a64e-5685-869b-c0f9a880d4c1','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='94ac1230-a64e-5685-869b-c0f9a880d4c1' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '050ab2a1-84e2-5bad-b1dc-a2d1bb820d41','Speed-error signature','The characteristic, measurable evidence that reveals a replay-speed error, typically a reference component of known frequency, such as recorded mains hum or a line-up tone, appearing at a shifted frequency whose ratio to the expected value equals the speed offset. Analysts read this frequency shift, and its steadiness or drift, to quantify and correct the error.','A speed error leaves clues you can measure. A hum or test tone with a known pitch will show up at the wrong frequency. The size of that shift tells you exactly how far off the speed is.','It gives archivists an objective, frequency-based way to detect and measure speed error instead of guessing by ear, so replay speed can be corrected to a known standard.','A technician views the transfer''s spectrum, finds a known reference such as mains hum, and compares its measured frequency with the expected value to calculate the exact speed correction.','Speed & Timing',ARRAY['Speed error','Timebase error','Wow and flutter','Transfer calibration tone','Spectral analysis']::text[],ARRAY['Treating any low hum as a clean speed reference without confirming the recording''s original mains frequency.','Reading a single spectral snapshot and missing that the shift drifts over time, which points to wow rather than a fixed offset.','Assuming the shifted reference is the intended pitch and correcting the whole recording to the wrong target.']::text[],ARRAY['Using recorded mains hum in an old broadcast tape to recover the exact original replay speed.','Measuring a line-up tone at the head of a reel that reproduces slightly off its stated frequency.','Distinguishing a steady speed offset from fluctuating wow by watching how a reference frequency behaves over time.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='050ab2a1-84e2-5bad-b1dc-a2d1bb820d41' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Speed-error signature'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '050ab2a1-84e2-5bad-b1dc-a2d1bb820d41','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='050ab2a1-84e2-5bad-b1dc-a2d1bb820d41' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2ba9bc46-1054-5381-8845-d9e49f9cf01d','Splice bump','A brief, localised disturbance in reproduced audio caused by a physical tape splice passing the heads, heard as a momentary level change, thump or dropout. It results from the added thickness and adhesive of the splicing tape, slight head-to-tape spacing changes, or a small discontinuity at the join.','A splice is where two pieces of tape are joined. As that join passes the playback head, it can make a short thump or dip in the sound. That little glitch is the splice bump.','Recognising the artefact tells a restorer that a defect is a known mechanical join rather than damage in the recording, so it can be treated correctly during transfer.','During or after transfer the technician locates the bump at each splice and reduces it with de-click, de-crackle or spectral repair tools, or by careful gain editing across the join.','Tape Defects',ARRAY['Splicing block','Tone splice','Dropout','De-click','Spectral repair']::text[],ARRAY['Mistaking a splice bump for a musical event or an intentional edit and leaving an audible click in the transfer.','Over-processing the whole track to chase one short bump, degrading surrounding audio.','Assuming every splice is stable, when old adhesive can fail and needs re-splicing before transfer.']::text[],ARRAY['Playing back a spliced 1/4-inch master and hearing a soft thump at each edit point.','Transferring an archival reel where old splices have hardened and shed adhesive.','Cleaning up edit-point clicks after digitising a heavily edited spoken-word programme.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2ba9bc46-1054-5381-8845-d9e49f9cf01d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Splice bump'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '2ba9bc46-1054-5381-8845-d9e49f9cf01d','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='2ba9bc46-1054-5381-8845-d9e49f9cf01d' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd7f5e116-fe95-5946-b627-d7da6facc88b','Splicing block','A precision editing tool, usually of machined aluminium, that holds magnetic tape in a shallow channel and guides a blade through angled cutting slots, commonly a diagonal cut near forty-five degrees and a square cut, so two tape ends can be trimmed and butt-joined with splicing tape. The channel width matches the tape gauge, such as 1/4-inch.','A splicing block is a small grooved metal tool for editing tape. The tape sits in the groove, and slots guide a blade to make a clean, angled cut. You then butt the ends together and join them with special tape.','It holds the tape straight and sets a repeatable cut angle so splices are accurate and mechanically sound, which is essential for editing and for repairing damaged archival tape.','A restorer lays tape oxide-side down in the block, cuts at the diagonal slot, aligns the two ends, and applies splicing tape before transferring or repairing a reel.','Tape Handling Tools',ARRAY['Splice bump','Tone splice','Timing leader','Leader tape','Editing']::text[],ARRAY['UNSAFE: handling the razor blade carelessly or leaving it exposed in the block, risking cuts to the fingers.','Using ordinary sticky tape or too much splicing tape, which oozes adhesive, fouls heads and creates a splice bump.','Cutting with a square butt when a diagonal splice would be less audible, or letting the tape sit skewed in the channel.']::text[],ARRAY['Repairing a broken archival reel before digitisation by re-splicing the parted ends.','Removing damaged tape or a bad splice and rejoining sound sections in the block.','Attaching leader tape to the head and tail of a reel during preparation for transfer.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d7f5e116-fe95-5946-b627-d7da6facc88b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Splicing block'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'd7f5e116-fe95-5946-b627-d7da6facc88b','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d7f5e116-fe95-5946-b627-d7da6facc88b' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e2c22d78-b8b8-5aa8-82eb-91e2e1449957','Surface metrology','The science and practice of measuring the micro-scale topography and geometry of a surface, quantifying features such as roughness, waviness and form. In audio archiving it underlies optical, non-contact methods that map the three-dimensional shape of a record groove or cylinder surface so the stored signal can be reconstructed.','Surface metrology means measuring the tiny bumps and dips on a surface very precisely. For old records, it maps the exact shape of the groove. That map can then be turned back into sound without a needle touching it.','It provides the accurate surface measurements that let fragile or broken grooved media be read optically, avoiding contact wear and recovering audio that a stylus could not safely play.','An archivist uses a confocal or interferometric microscope to capture the groove surface, then software traces the measured wall shape to produce an audio file.','Optical Scanning',ARRAY['Three-dimensional groove imaging','Optical scanning','Confocal microscopy','Groove','Digitisation']::text[],ARRAY['Assuming an optical scan is automatically better than a good stylus transfer, when scan quality depends on clean, well-measured surfaces.','Ignoring dust and debris, which the measurement reads as false groove detail and turns into noise.','Under-sampling the surface so fine high-frequency detail in the groove is lost.']::text[],ARRAY['Optically scanning a cracked shellac disc that is too fragile to play with a stylus.','Mapping the surface of a wax cylinder for non-contact audio recovery.','Recovering sound from a broken or delaminating disc by imaging its groove geometry.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e2c22d78-b8b8-5aa8-82eb-91e2e1449957' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Surface metrology'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e2c22d78-b8b8-5aa8-82eb-91e2e1449957','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e2c22d78-b8b8-5aa8-82eb-91e2e1449957' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '89aba92e-e10d-5d7c-ad41-89aaaef9104a','Switching hash','A high-frequency electrical noise, heard as a raspy buzz, generated by rapid switching devices such as thyristor light dimmers, switch-mode power supplies and motor commutators, which couples into audio circuits through the mains, grounds or radiated fields. Its energy is often related to the mains frequency and rich in sharp, high-frequency spikes.','Switching hash is a harsh, buzzy noise from electrical gear that turns power on and off very fast. Light dimmers and cheap power supplies are common sources. The noise leaks into the audio and sounds like a gritty buzz.','Naming this noise type helps a technician trace it to a switching source and remove or avoid it, protecting the clarity of a recording or transfer.','On the job a technician tracks hash to a dimmer or power supply and fixes it at source with filtering or better grounding, or removes it from a transfer with de-hum and spectral tools.','Noise & Interference',ARRAY['Hum removal','De-noise','Spectral repair','Grounding','Radio-frequency interference']::text[],ARRAY['Blaming the recorder for buzz that is actually radiated hash from a nearby dimmer or power supply.','Trying to remove hash with a simple hum notch, which leaves the sharp high-frequency components untouched.','Chasing it only in software when fixing the source or grounding would prevent it entirely.']::text[],ARRAY['Recovering a live recording spoiled by buzz from stage lighting dimmers.','Cleaning a transfer that picked up noise from a nearby switch-mode power supply.','Diagnosing a gritty buzz on a console traced to a shared, poorly grounded power circuit.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='89aba92e-e10d-5d7c-ad41-89aaaef9104a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Switching hash'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '89aba92e-e10d-5d7c-ad41-89aaaef9104a','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='89aba92e-e10d-5d7c-ad41-89aaaef9104a' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6079792a-de90-5df6-a7b1-12a2c4868572','Tape-type detection notch','A molded cutout in the top edge of a compact cassette shell that lets a recorder automatically sense the tape formulation and select the matching bias and replay equalization. Under the cassette standard, ferric Type I uses only the write-protect openings, high-bias Type II adds a pair of holes beside them, and metal Type IV adds a further central pair; Type I uses a longer replay time constant and Types II and IV a shorter one.','Cassettes have small holes cut into the top edge. Feelers in the deck read these holes to tell what kind of tape is inside. The deck then sets the right recording strength and tone settings for that tape.','The notches let a deck apply the correct bias and equalization for each tape formulation automatically, so recordings sound right without the user setting switches by hand.','A technician checks or, when copying a rare tape, tapes over or opens these notches so a deck applies the correct equalization for an accurate transfer.','Cassette Format',ARRAY['Bias','Equalization','Compact cassette','Write-protect tab','Transfer calibration tone']::text[],ARRAY['Assuming every deck reads the notches, when many basic and older machines have fixed settings and ignore them.','Believing the notch changes the tape itself, when it only signals the deck which bias and equalization to use.','Overlooking a mislabeled or reshelled tape whose notches no longer match its actual formulation.']::text[],ARRAY['Setting up an auto-sensing deck to transfer a chrome, high-bias cassette correctly.','Diagnosing dull or hissy playback caused by a deck reading the wrong tape type.','Preparing a metal-formulation cassette for accurate digitisation.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6079792a-de90-5df6-a7b1-12a2c4868572' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Tape-type detection notch'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6079792a-de90-5df6-a7b1-12a2c4868572','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6079792a-de90-5df6-a7b1-12a2c4868572' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e14ca8e8-29f5-5d3b-9c81-49e35a339784','Three-dimensional groove imaging','A non-contact preservation technique that optically measures the full three-dimensional shape of a record or cylinder groove, using methods such as confocal microscopy, and computationally traces the groove walls to reconstruct the recorded audio. It suits vertically cut and physically damaged media where the depth of the groove carries the signal.','This method takes a detailed three-dimensional picture of a record''s groove. No needle ever touches the disc. Software then follows the shape of the groove walls and turns it back into sound.','It recovers audio from fragile, broken or vertically cut media without a stylus, capturing groove depth as well as side-to-side motion so damaged or unplayable recordings can still be read.','An archivist scans a cracked disc or a cylinder under a confocal microscope, stitches the surface data, and processes it into an audio file when normal playback is impossible.','Optical Scanning',ARRAY['Surface metrology','Optical scanning','Confocal microscopy','Groove','Digitisation']::text[],ARRAY['Assuming three-dimensional imaging always beats a stylus, when a clean playable disc often transfers well by contact.','Skipping cleaning, so dust and mold in the scan add noise to the recovered audio.','Under-resolving the groove, which loses the fine detail that carries high frequencies.']::text[],ARRAY['Recovering audio from a broken shellac disc that cannot be safely played.','Reading a vertically cut wax cylinder where groove depth carries the signal.','Digitising a warped or delaminating disc that a stylus cannot track.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e14ca8e8-29f5-5d3b-9c81-49e35a339784' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Three-dimensional groove imaging'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e14ca8e8-29f5-5d3b-9c81-49e35a339784','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e14ca8e8-29f5-5d3b-9c81-49e35a339784' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'dcb46d0c-1e24-546b-bfd9-2bcbc003d701','Thump removal','A restoration process that removes brief low-frequency transient disturbances, called thumps, such as those from tape splices, dropouts, physical shocks, plosive breath blasts or edit points. It targets the short burst of low-frequency energy while preserving the surrounding programme.','Thumps are short, low bumps of sound, like a soft knock or a burst of breath on a microphone. Thump removal takes out those brief low blasts. It tries to leave the rest of the audio untouched.','It exists to clear distracting low-frequency thumps and plosive bursts that a simple high-pass filter cannot remove cleanly, so speech and music stay intact and natural.','A technician marks each thump and applies a de-plosive or low-frequency transient tool, or interpolates across the burst, checking that the low end of the surrounding audio is preserved.','Restoration Processing',ARRAY['De-click','Spectral repair','Splice bump','Dropout','De-noise']::text[],ARRAY['Reaching for a broad high-pass filter, which thins the whole recording instead of removing single thumps.','Setting the tool too aggressively and hollowing out the natural low end of voice or music.','Treating a musical bass note or kick as a thump and removing wanted low-frequency content.']::text[],ARRAY['Cleaning plosive breath blasts on a close-miked spoken-word recording.','Removing low thumps at splice points in a transferred tape.','Fixing dull low-frequency knocks caused by handling or a dropped microphone.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='dcb46d0c-1e24-546b-bfd9-2bcbc003d701' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Thump removal'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'dcb46d0c-1e24-546b-bfd9-2bcbc003d701','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='dcb46d0c-1e24-546b-bfd9-2bcbc003d701' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6897786f-d05c-5baf-83d8-68778ab45b25','Timebase error','A deviation in the timing of a reproduced signal from a stable, uniform time reference, caused by speed instability in the transport or clock. In analog tape it appears as wow and flutter, slow and fast speed fluctuations, and in synchronised or video systems as jitter that must be corrected against a stable timebase.','Timebase error means the timing of the playback keeps drifting instead of staying steady. On tape it shows up as wobble in the pitch. Slow wobble is called wow and faster wobble is called flutter.','The concept lets technicians identify and correct unsteady timing so pitch stays constant and synchronised systems stay locked, rather than drifting or wavering.','A restorer measures speed fluctuation on a transfer and reduces wow and flutter with correction software, or uses a stable reference clock when syncing audio to picture.','Speed & Timing',ARRAY['Speed error','Wow and flutter','Speed-error signature','Jitter','Timing leader']::text[],ARRAY['Confusing a fixed speed offset, which shifts pitch uniformly, with timebase error, which makes the pitch waver.','Assuming all wobble is in the recording, when a worn capstan or dirty pinch roller on the replay machine can cause it.','Attempting timing correction before servicing the transport, so the machine keeps adding new instability.']::text[],ARRAY['Reducing audible wow on a tape recorded with a slipping or worn transport.','Correcting flutter in a transfer before it is used in a music restoration.','Keeping audio locked to picture where drift would break lip sync.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6897786f-d05c-5baf-83d8-68778ab45b25' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Timebase error'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6897786f-d05c-5baf-83d8-68778ab45b25','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6897786f-d05c-5baf-83d8-68778ab45b25' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '17767376-1368-5d34-8549-eed2eca8304b','Timing leader','A measured length of non-magnetic leader tape spliced between recorded items or before a selection to create a controlled, timed pause. Because leader travels at the tape speed, a known length corresponds to a known duration, letting editors set precise silent gaps and cue points on a reel.','Leader is the blank, non-magnetic tape spliced onto a reel. Timing leader is a measured piece used to make an exact silent gap. Since the tape moves at a set speed, a known length equals a known number of seconds.','It provides accurate, repeatable timed spacing between programme items and clean cue points, so pauses and starts fall exactly where the editor intends.','An editor cuts leader to a length that gives the wanted pause at the reel''s speed and splices it between selections, or ahead of a start, for reliable timing on playback.','Tape Handling Tools',ARRAY['Leader tape','Splicing block','Tone splice','Splice bump','Editing']::text[],ARRAY['Cutting leader length without accounting for the reel''s tape speed, so the timed gap is wrong.','Using magnetic tape instead of proper leader, which can pick up hum or print-through in the gap.','Splicing leader in reverse or with poor contact, causing tracking problems as it passes the heads.']::text[],ARRAY['Setting precise pauses between tracks when assembling a programme reel for broadcast.','Adding measured leader before a selection so it starts at a known cue time.','Separating items on an archival reel with timed, clearly visible gaps.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='17767376-1368-5d34-8549-eed2eca8304b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Timing leader'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '17767376-1368-5d34-8549-eed2eca8304b','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='17767376-1368-5d34-8549-eed2eca8304b' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '33222a33-5dd0-52ca-9d11-f8265c211332','Tone splice','A splice that joins a section carrying a recorded reference tone, such as head line-up tones, to a tape, so the calibration tone travels physically with the reel. It links the alignment tone segment, often on or next to leader, to the programme for use when the tape is later replayed or transferred.','A tone splice joins a piece of tape holding a test tone to the recording. The test tone is used later to set levels correctly. Splicing it on keeps that reference tone attached to the reel.','It keeps the alignment tones bound to the recording they belong to, so a future operator can set replay level and response from tones that match that exact tape.','When preparing a reel, an operator splices the line-up tone section to the head of the programme, then reads those tones to align the machine before transfer.','Tape Handling Tools',ARRAY['Transfer calibration tone','Splicing block','Timing leader','Leader tape','Splice bump']::text[],ARRAY['Recording or splicing on tones at a level or frequency that does not match the reel''s own reference standard.','Cutting the tone section off during editing, leaving the transfer with no way to verify original level.','Assuming spliced-on tones from another reel apply, when tones must match the specific tape and machine.']::text[],ARRAY['Attaching head line-up tones to a master before it is archived.','Aligning a replay machine from spliced-on reference tones before digitising a reel.','Confirming a tape''s original reference level from the tone section joined at its head.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='33222a33-5dd0-52ca-9d11-f8265c211332' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Tone splice'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '33222a33-5dd0-52ca-9d11-f8265c211332','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='33222a33-5dd0-52ca-9d11-f8265c211332' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5d0d16fc-e83d-5f0c-848e-9af7bd340d3a','Transfer calibration tone','A reference tone of known frequency and level, usually recorded at the head of a tape or supplied as a standard, used during transfer to align and verify the replay chain. Operators set replay level, azimuth and frequency response, and can check speed, against these tones so the digitised file faithfully represents the original.','A calibration tone is a steady test tone with a known pitch and loudness. Before copying a tape, the operator plays it and adjusts the machine to match. This makes sure the copy is a true, accurate transfer.','It gives the operator a known reference to align the playback machine and confirm level, response and speed, so the transfer is accurate and documented rather than guessed.','At the start of a transfer the technician plays the head tones, sets the replay level to the reference, checks response and azimuth, and logs the readings before capturing the programme.','Transfer & Calibration',ARRAY['Tone splice','Speed-error signature','Reference level','Azimuth','Speed error']::text[],ARRAY['Ignoring the head tones and setting transfer level by ear, losing the tape''s documented reference level.','Assuming a standard tone value without checking the paperwork, when reference levels and standards vary between studios.','Aligning to tones that were themselves recorded off-standard, so the whole transfer inherits the error.']::text[],ARRAY['Setting replay level from the line-up tones at the head of an archival master before digitising.','Checking and correcting head azimuth using a high-frequency reference tone.','Documenting a transfer''s reference level so future users can relate file level to the original.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5d0d16fc-e83d-5f0c-848e-9af7bd340d3a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Transfer calibration tone'),'[^a-z0-9]','','g'));
