INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5c214deb-1560-5eea-b489-617508f3ab5b','Transfer lineage','The documented chain of successive copies and format transfers a recording has passed through, from its original carrier to the current preservation copy, recording at each stage what was copied, on what equipment, with what settings and processing, and by whom. It is a form of provenance metadata that lets an archive judge a copy''s authenticity, generational distance and reliability.','Old recordings get copied from one format to the next over the years. Transfer lineage is the written history of those copies. It tells you what was copied, on what gear, and by whom. That history shows how far a copy sits from the original.','It exists so later users can trace a preservation copy back to its source, understand the processing and generation loss that lie between them, and judge whether to trust the copy''s fidelity and authenticity.','When ingesting or reusing a file, an archivist reads its lineage metadata to learn whether it came straight off the original carrier or through earlier copies, and what equalization or noise reduction was already applied.','Preservation Metadata',ARRAY['Provenance metadata','Generation loss','Flat transfer','Undecoded transfer','Preservation master']::text[],ARRAY['Documenting only the final transfer and omitting the intermediate copies, so the true number of generations is hidden.','Confusing transfer lineage (the history of copies and processing) with fixity (proof a file has not changed since a given point).','Assuming a digital file is a first-generation transfer when it may have been copied from an earlier tape or disc dub.']::text[],ARRAY['Recording the turntable, stylus, preamp and settings used, so a disc transfer''s lineage is complete.','Deciding which of several surviving copies is closest to the original by comparing their lineages.','Auditing an ingested collection and finding that some so-called masters are actually later-generation dubs.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5c214deb-1560-5eea-b489-617508f3ab5b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Transfer lineage'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '5c214deb-1560-5eea-b489-617508f3ab5b','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='5c214deb-1560-5eea-b489-617508f3ab5b' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'abbb4559-6210-503a-9426-ac73b25dc555','Transient reconstruction','In audio restoration, the rebuilding of the sharp, brief attack portions of a signal (transients) that have been damaged, clipped or removed, for example where a de-click or de-clip process has excised corrupted samples across an impulsive event. Restoration tools re-estimate the missing waveform by interpolation or resynthesis so the repaired attack keeps its natural sharpness rather than sounding dulled.','A transient is the short, sharp start of a sound, like a drum hit. Damage or click removal can flatten it. Transient reconstruction rebuilds that missing sharp part. The software fills the gap so the attack still sounds crisp.','It exists to restore the impact and clarity of attacks after clicks, clipping or dropouts have destroyed them, preventing repaired audio from sounding soft or lifeless.','After removing clicks or repairing clipped peaks, an engineer relies on the tool''s reconstruction to redraw the waveform under the repair so drum hits and consonants keep their bite.','Restoration Processing',ARRAY['De-click','De-clip','Spectral repair','Interpolation','Dropout']::text[],ARRAY['Setting click or clip repair so aggressively that real musical transients are removed and then only partly rebuilt, dulling the sound.','Confusing transient reconstruction (rebuilding the signal under a repair) with transient shaping (an effect that changes attack level).','Assuming reconstructed material is recovered original audio, when it is an estimate the software has interpolated.']::text[],ARRAY['Repairing a clipped live recording where loud peaks were flattened and their attacks must be rebuilt.','De-clicking a 78 rpm disc transfer without softening the percussion.','Filling a short dropout in a tape transfer so the note''s attack is not lost.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='abbb4559-6210-503a-9426-ac73b25dc555' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Transient reconstruction'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'abbb4559-6210-503a-9426-ac73b25dc555','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='abbb4559-6210-503a-9426-ac73b25dc555' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1adaea9b-2f55-5774-8fc5-e8f7db3bfc62','Turnover frequency','In disc recording and replay characteristics, the low-frequency point at which a recording or replay curve changes slope, marking the transition between its constant-amplitude and constant-velocity regions; below it the bass is progressively boosted on replay (and cut on record). For the RIAA characteristic the bass turnover is 500 Hz (a 318 microsecond time constant); pre-RIAA disc characteristics used various turnovers, commonly from about 250 Hz to 800 Hz.','When records are cut, the bass is turned down, and playback turns it back up. The turnover frequency is where that bass boost begins. Below it, low notes get lifted. Old records used different turnover points, so picking the right one matters.','It defines part of the equalization curve needed to undo the deliberate frequency shaping applied when a disc was cut, so the replayed signal matches the original tonal balance.','Transferring a pre-RIAA disc, an engineer selects the turnover (and rolloff) that matches the label''s cutting characteristic, or transfers flat and applies the correct turnover later.','Disc Reproduction',ARRAY['Rolloff frequency','RIAA equalization','Replay equalization','Unequalized transfer','Pre-RIAA equalization']::text[],ARRAY['Assuming every disc uses the RIAA 500 Hz turnover, when many pre-1955 records used different turnover frequencies.','Confusing the turnover frequency (the bass transition) with the rolloff frequency (the treble transition).','Guessing the turnover by ear instead of identifying the disc''s cutting characteristic, giving a wrong tonal balance.']::text[],ARRAY['Choosing turnover and rolloff on a transfer preamp for a 1940s shellac disc.','Comparing candidate turnover settings to find the flattest, most natural balance.','Documenting the turnover used so the transfer can be re-corrected later if needed.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1adaea9b-2f55-5774-8fc5-e8f7db3bfc62' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Turnover frequency'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '1adaea9b-2f55-5774-8fc5-e8f7db3bfc62','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1adaea9b-2f55-5774-8fc5-e8f7db3bfc62' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '62aff05b-6051-5617-9c1f-621334d61f6d','Two-dimensional groove imaging','An optical audio-recovery method in which a lateral-cut groove is captured as a high-resolution two-dimensional (top-down) image of its side-to-side modulation, without a physical stylus. Because a laterally cut groove carries its signal as horizontal displacement, a 2D image of the groove path is sufficient to recover the audio, whereas vertically cut (hill-and-dale) grooves and cylinders require three-dimensional (depth) imaging.','Some old records store sound as side-to-side wiggles in the groove. Two-dimensional groove imaging takes a flat, top-down photo of those wiggles. Software then reads the wiggles as sound. No needle ever touches the record.','It lets an archive recover audio from lateral-cut discs by photograph and computation, avoiding stylus contact and enabling playback of discs too fragile or broken to track normally.','An engineer scans a cracked or worn lateral disc with a 2D imaging system such as IRENE, then processes the images into sound instead of tracking it with a stylus.','Optical Scanning',ARRAY['Virtual stylus','Wall-profile extraction','Wall-to-wall summation','Virtual reassembly','Lateral-cut recording']::text[],ARRAY['Assuming 2D imaging suits every carrier, when vertical-cut discs and cylinders need three-dimensional depth scanning.','Believing the optical scan is itself the audio, when software must still extract and reconstruct the signal from the image.','Expecting imaging to remove all noise, when scratches and wear still appear in the scan and need restoration.']::text[],ARRAY['Recovering sound from a broken lateral 78 that cannot be tracked with a stylus.','Digitizing a delaminating lacquer disc by imaging it rather than playing it.','Choosing 2D imaging for lateral discs and 3D scanning for cylinders in the same collection.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='62aff05b-6051-5617-9c1f-621334d61f6d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Two-dimensional groove imaging'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '62aff05b-6051-5617-9c1f-621334d61f6d','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='62aff05b-6051-5617-9c1f-621334d61f6d' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9e09cee3-b575-5c2e-8a38-33ea4e848b08','Type III cassette','In the IEC compact cassette classification, a Type III (ferrichrome, FeCr) cassette, whose tape carries a dual magnetic coating: a thicker lower layer of gamma ferric oxide for low-frequency performance and a thin upper layer of chromium dioxide for high-frequency performance. Introduced by Sony in 1973 and codified as IEC Type III, it was specified for replay with 70 microsecond equalization; it saw limited adoption and was largely obsolete by the early 1980s.','A Type III cassette, also called ferrichrome, used two magnetic layers stacked together. The lower layer handled bass, and the thin top layer handled treble. Sony made it in the 1970s to get the best of both. It never caught on and soon disappeared.','It existed to combine the strong low-frequency handling of ferric tape with the crisp high-frequency handling of chrome tape in one formulation, aiming for wider dynamic range than either alone.','An archivist transferring a 1970s cassette collection must recognise a ferrichrome (Type III) shell and set the deck''s tape type correctly, since a wrong setting alters the equalization and tonal balance.','Obsolete Media',ARRAY['Type I cassette','Type II cassette','Type IV cassette','Tape bias','Replay equalization']::text[],ARRAY['Assuming a ferrichrome cassette behaves like an ordinary chrome (Type II) tape in every respect, when its recommended bias and equalization differ.','Confusing Type III (a dual-layer ferrichrome tape) with Type IV (single-layer metal-particle tape).','Guessing the tape type from the shell colour instead of its type notches or labelling, and setting the wrong equalization.']::text[],ARRAY['Identifying a Sony ferrichrome cassette in a donated 1970s collection before transfer.','Selecting the deck''s equalization for a Type III tape to obtain a flat transfer.','Documenting the tape formulation as part of the transfer''s technical metadata.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9e09cee3-b575-5c2e-8a38-33ea4e848b08' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Type III cassette'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9e09cee3-b575-5c2e-8a38-33ea4e848b08','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9e09cee3-b575-5c2e-8a38-33ea4e848b08' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '82e472e8-824e-52f8-aa80-944beed286be','Undecoded transfer','A transfer of a noise-reduction-encoded recording (for example one recorded with Dolby A, B, C, SR or dbx) that is captured without applying the corresponding decoder, so the still-encoded signal is preserved as-is. It is used when the encoding type or its correct calibration is uncertain, so that decoding can be performed later and correctly in the digital domain rather than baked in irreversibly during transfer.','Some tapes were recorded using noise reduction that must be reversed on playback. An undecoded transfer copies the tape without reversing it. The signal stays in its coded form. That lets you decode it correctly later, once you know the right system.','It exists to avoid locking in a wrong or mis-aligned decode during transfer; keeping the signal encoded preserves every later decoding option and documents the true state of the tape.','Unsure whether a tape used Dolby B or C, an engineer makes an undecoded transfer and notes the suspected system, decoding a copy later once the format is confirmed.','Transfer Technique',ARRAY['Noise reduction','Dolby noise reduction','Flat transfer','Unequalized transfer','Transfer lineage']::text[],ARRAY['Applying a decoder during transfer when the encoding type is unconfirmed, baking in a wrong decode that cannot be undone.','Failing to document that a transfer is undecoded, so a later user decodes it twice or not at all.','Confusing an undecoded transfer (noise reduction not reversed) with an unequalized transfer (replay equalization not applied).']::text[],ARRAY['Transferring a Dolby SR master flat when no calibrated SR decoder is available.','Preserving a dbx-encoded tape undecoded until its alignment tones can be checked.','Delivering both an undecoded preservation copy and a separately decoded listening copy.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='82e472e8-824e-52f8-aa80-944beed286be' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Undecoded transfer'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '82e472e8-824e-52f8-aa80-944beed286be','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='82e472e8-824e-52f8-aa80-944beed286be' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'fb2821ec-5576-5384-891f-cfd19aa68020','Unequalized transfer','A transfer made without applying the replay equalization a carrier requires, so the signal is captured flat, carrying only the fixed response of the replay chain. It is used chiefly for historical discs and tapes whose correct recording characteristic is unknown or disputed, so the appropriate equalization can be determined and applied later in the digital domain, and re-applied differently if better information emerges.','Records and tapes are cut with the tone deliberately changed, and playback must change it back. An unequalized transfer skips that correction and captures the sound flat. If the right setting is unknown, this keeps your options open. You add the correct tone fix later.','It preserves the raw carrier signal so that equalization becomes a reversible, documented digital step, rather than an irreversible choice made once at transfer time.','Facing a disc whose cutting characteristic is uncertain, an engineer transfers it flat (unequalized) and later tries candidate turnover and rolloff settings on the file.','Transfer Technique',ARRAY['Flat transfer','Replay equalization','Turnover frequency','Rolloff frequency','Undecoded transfer']::text[],ARRAY['Treating an unequalized (flat) transfer as a finished listening copy, when it still needs the correct replay equalization.','Forgetting to document that a transfer is unequalized, so someone applies equalization twice or not at all.','Confusing an unequalized transfer (no replay equalization) with an undecoded transfer (noise reduction not reversed).']::text[],ARRAY['Transferring a pre-RIAA disc flat and choosing turnover and rolloff afterwards.','Capturing a tape flat when its recording characteristic is undocumented.','Keeping a flat preservation master while deriving equalized access copies.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='fb2821ec-5576-5384-891f-cfd19aa68020' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Unequalized transfer'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'fb2821ec-5576-5384-891f-cfd19aa68020','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='fb2821ec-5576-5384-891f-cfd19aa68020' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '246eb84a-557f-55a4-a7f4-d327cf92a6d1','Unweighted wow and flutter','A measurement of wow and flutter (short-term speed variation of a recorder or player) made without the perceptual weighting filter, so all fluctuation-rate components are counted equally, typically as a peak or RMS deviation of a reproduced reference tone (commonly 3.15 kHz). Because it omits the roughly 4 Hz-peaking weighting used in weighted measurements, an unweighted figure is generally numerically higher and characterises the machine''s raw speed stability rather than perceived pitch instability.','Wow and flutter means small speed changes that make pitch waver. An unweighted measurement counts all those wobbles equally. It does not adjust for what the ear notices most. So the number is usually higher than a weighted one. It shows the machine''s raw speed steadiness.','It gives an objective, filter-free figure for a transport''s speed stability, useful for engineering comparison and for judging a machine''s mechanical condition independent of listener perception.','Servicing or qualifying a transfer deck, a technician measures unweighted wow and flutter with a test tape or disc to check the transport, expecting a higher figure than the weighted specification.','Speed Stability',ARRAY['Weighted wow and flutter','Wow and flutter','Flutter','Speed stability','Test tape']::text[],ARRAY['Comparing an unweighted figure directly against a weighted one, when the two use different methods and are not interchangeable.','Quoting a wow and flutter number without stating whether it is weighted or unweighted, making it meaningless.','Assuming a good unweighted figure guarantees good perceived pitch stability, which the weighted measure addresses more directly.']::text[],ARRAY['Bench-testing a reel-to-reel transport''s raw speed stability with an unweighted measurement.','Comparing two decks'' unweighted specifications when choosing a transfer machine.','Diagnosing a mechanical fault by watching the unweighted flutter figure rise.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='246eb84a-557f-55a4-a7f4-d327cf92a6d1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Unweighted wow and flutter'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '246eb84a-557f-55a4-a7f4-d327cf92a6d1','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='246eb84a-557f-55a4-a7f4-d327cf92a6d1' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '651ac1d8-46ca-553d-9569-b995813ccb0a','Virtual reassembly','In optical audio recovery, the digital reconstruction of a broken or fragmented carrier by aligning and joining high-resolution images of its pieces, so a continuous groove path can be followed across the breaks without physically repairing the object. It allows sound to be recovered from discs or cylinders that are cracked, shattered or delaminating and that could never be tracked by a stylus.','Some old discs and cylinders are cracked or broken into pieces. Virtual reassembly scans each piece and joins the images on a computer. The software then follows the groove across the breaks. The record is rebuilt as a picture, not with glue.','It exists to recover audio from carriers too damaged to play, reassembling them in software so no risky physical repair or stylus contact is needed.','Given a disc broken into shards, an engineer images each shard, aligns them virtually, and extracts a continuous signal across the joins.','Optical Scanning',ARRAY['Two-dimensional groove imaging','Virtual stylus','Wall-profile extraction','Confocal microscopy','Lacquer disc']::text[],ARRAY['Assuming a shattered disc must be glued back together, when imaging and virtual reassembly avoid the handling risk.','Expecting perfect, seamless audio across every break, when material missing at a join still causes gaps or noise.','Confusing virtual reassembly (rejoining images of a broken carrier) with the virtual stylus (computing motion from groove shape).']::text[],ARRAY['Recovering a performance from a lacquer disc that shattered in storage.','Imaging the fragments of a broken cylinder and aligning them in software.','Reading a delaminating disc whose flaking surface could not survive a stylus.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='651ac1d8-46ca-553d-9569-b995813ccb0a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Virtual reassembly'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '651ac1d8-46ca-553d-9569-b995813ccb0a','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='651ac1d8-46ca-553d-9569-b995813ccb0a' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1152aca4-9b7f-54d3-8072-66189f60937a','Virtual stylus','In optical audio recovery, a software model that computes the motion an idealized stylus would have made from the measured geometry of a scanned groove, converting the extracted groove-wall profile into an audio waveform without any physical contact. It replaces the mechanical pickup with a numerical one, and its effective tip size, shape and path can be varied in software to avoid worn or damaged regions of the groove.','A virtual stylus is a needle that exists only in software. It looks at the scanned shape of the groove and works out how a real needle would move. That motion becomes the sound. Because it is not real, it never wears or damages the record.','It exists to turn an optical scan of a groove into audio while letting the operator change the modelled tip and path in software, steering around damage that a real stylus could not avoid.','After imaging a disc, an engineer runs the virtual stylus over the extracted groove profile, adjusting its modelled contact to skip a scratched section.','Optical Scanning',ARRAY['Two-dimensional groove imaging','Wall-profile extraction','Wall-to-wall summation','Virtual reassembly','Stylus tip radius']::text[],ARRAY['Thinking the virtual stylus physically touches the disc, when it is purely a computation on the scanned image.','Assuming any modelled tip shape recovers the same audio, when the chosen contact geometry changes noise and distortion.','Confusing the virtual stylus (computing motion from groove shape) with the imaging step that captures the groove.']::text[],ARRAY['Extracting audio from a scanned 78 by running a virtual stylus over the groove profile.','Adjusting the modelled tip to avoid a damaged groove wall during an optical transfer.','Comparing virtual-stylus output with a conventional stylus transfer of the same disc.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1152aca4-9b7f-54d3-8072-66189f60937a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Virtual stylus'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '1152aca4-9b7f-54d3-8072-66189f60937a','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1152aca4-9b7f-54d3-8072-66189f60937a' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '69f6cec2-5150-512e-b579-d6e100cb5d2f','Wall-profile extraction','In optical groove analysis, the image-processing step that locates and traces the edge or surface profile of each groove wall in the scanned data, yielding a displacement (or depth) trace for the wall along the length of the groove. These extracted wall profiles are the raw geometry from which a virtual stylus derives the audio signal.','A groove has two sloping side walls that carry the sound. Wall-profile extraction is the step where software finds and traces the exact shape of each wall in the scan. Those traced shapes are the data the sound is read from.','It exists to convert raw scan images into precise numeric traces of the groove walls, the geometry needed before any audio can be computed.','In an optical transfer workflow, the software first extracts each wall''s profile from the images, and the operator checks these traces before the signal is derived.','Optical Scanning',ARRAY['Two-dimensional groove imaging','Virtual stylus','Wall-to-wall summation','Virtual reassembly','Lateral-cut recording']::text[],ARRAY['Assuming the extracted profile is automatically clean, when dirt, scratches and scan artefacts can be mistaken for groove edges.','Confusing wall-profile extraction (tracing the groove walls) with wall-to-wall summation (combining the two walls into a signal).','Neglecting to inspect the traced walls, so extraction errors pass unnoticed into the audio.']::text[],ARRAY['Reviewing extracted groove-wall traces before deriving audio from a scanned disc.','Tuning extraction settings so debris is not read as part of the groove wall.','Extracting both walls of a stereo groove to feed separate left and right channels.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='69f6cec2-5150-512e-b579-d6e100cb5d2f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Wall-profile extraction'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '69f6cec2-5150-512e-b579-d6e100cb5d2f','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='69f6cec2-5150-512e-b579-d6e100cb5d2f' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8c299723-1045-57f9-bc3e-592bc3200671','Wall-to-wall summation','In optical groove recovery, the combination of the two extracted groove-wall displacement traces to derive the reproduced signal: for a lateral-cut (mono) groove the two walls move together side to side, so summing (averaging) their lateral displacements yields the audio while cancelling common vertical noise; for a vertical-cut groove the depth signal is instead the difference of the walls. It mirrors how a mechanical stylus responds to the combined motion of both groove walls.','A groove has two walls. In a normal side-to-side record they move together. Software adds the two wall traces to get the sound. Adding them also cancels some up-and-down noise. In up-and-down cut records, the walls'' difference gives the sound.','It exists to turn the two separate wall profiles into a single correct audio channel, using the sum for lateral signals and the difference for vertical ones, while rejecting noise common to both walls.','Deriving audio from a scanned lateral disc, the software sums the two wall traces; for a vertical-cut disc or cylinder it takes their difference instead.','Optical Scanning',ARRAY['Wall-profile extraction','Virtual stylus','Two-dimensional groove imaging','Lateral-cut recording','Vertical-cut recording']::text[],ARRAY['Summing the walls for a vertical-cut groove, when its signal is the difference of the walls, not the sum.','Assuming summation alone removes all noise, when only noise common to both walls is cancelled.','Confusing wall-to-wall summation (combining the walls) with wall-profile extraction (tracing them).']::text[],ARRAY['Recovering a mono lateral 78 by summing its two groove-wall traces.','Switching to wall differencing to read a vertical-cut Edison disc.','Using summation to cancel vertical noise from a warped lateral disc scan.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8c299723-1045-57f9-bc3e-592bc3200671' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Wall-to-wall summation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '8c299723-1045-57f9-bc3e-592bc3200671','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8c299723-1045-57f9-bc3e-592bc3200671' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3d313395-dbb9-5d1d-9529-7e37a7824d10','Weighted wow and flutter','A measurement of wow and flutter in which the fluctuation of a reproduced reference tone (commonly 3.15 kHz) is passed through a perceptual weighting filter that peaks near 4 Hz before detection, so the figure reflects how audible the pitch instability is to a listener. The weighting network and quasi-peak detection are defined in standards such as DIN 45507, IEC 60386 and AES6; a weighted figure is typically lower than the corresponding unweighted value.','Wow and flutter are small speed changes that make pitch waver. People notice wobbles near four times a second the most. A weighted measurement gives those wobbles more importance. So the number matches what the ear actually hears. It is usually lower than an unweighted number.','It exists to express speed instability in terms of perceived pitch wobble, giving a figure that tracks how bothersome the effect is rather than its raw size.','Checking a transfer deck against its specification, a technician measures weighted wow and flutter, which should match the manufacturer''s weighted figure.','Speed Stability',ARRAY['Unweighted wow and flutter','Wow and flutter','Flutter','Speed stability','Test tape']::text[],ARRAY['Comparing a weighted figure with an unweighted one, when they use different methods and are not directly comparable.','Reporting wow and flutter without stating that it is weighted, leaving the number ambiguous.','Assuming a low weighted figure means the transport is mechanically perfect, when it only reflects perceived pitch wobble.']::text[],ARRAY['Verifying that a cassette deck meets its weighted wow and flutter specification.','Comparing decks by their weighted figures when perceived pitch stability matters.','Logging a weighted measurement in a transfer station''s maintenance record.']::text[],'ab73f3b5-426f-4585-8a7c-f829e2a03138'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3d313395-dbb9-5d1d-9529-7e37a7824d10' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Weighted wow and flutter'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '3d313395-dbb9-5d1d-9529-7e37a7824d10','ab73f3b5-426f-4585-8a7c-f829e2a03138',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='3d313395-dbb9-5d1d-9529-7e37a7824d10' AND gt.achievement_id='ab73f3b5-426f-4585-8a7c-f829e2a03138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4dedca14-a439-5d66-893b-08c79ccadd10','Abrasive contamination','The presence on a tape''s surface or in the tape path of hard particulate matter - dust, grit, shed oxide or back-coat debris, dried residue or mould - that mechanically abrades the tape and the transport''s heads and guides during playback. It accelerates head and tape wear, clogs heads, and causes dropouts and signal loss.','Tiny hard bits like dust, grit, and shed debris settle on tape. When the tape plays, these bits scrape the tape and the heads. That wear can cause dropouts and clog the heads. Cleaning the tape first helps stop the damage.','The concept exists to warn technicians that abrasive particulate causes cumulative, irreversible wear to both tape and heads, so contaminated tapes must be assessed and cleaned before they are played.','Before transferring an old or dirty tape, a technician inspects it and cleans loose contamination from its surface and the tape path, protecting both the fragile recording and the deck''s heads.','Tape Contamination',ARRAY['Back-coat shedding','Oxide shedding','Head clog','Dropout','Tape cleaning']::text[],ARRAY['Playing a visibly dirty or gritty tape without cleaning it first, so contaminants scratch the tape and heads.','Confusing loose surface contamination with permanent oxide loss; contamination can often be cleaned, but wear cannot be undone.','UNSAFE: Handling or cleaning a mould-contaminated tape without a respirator and gloves, risking inhalation of spores.']::text[],ARRAY['Inspecting a dusty attic tape and cleaning grit from it before threading a valued transfer deck.','Diagnosing repeated dropouts and head clogging traced to gritty debris on the tape surface.','Deciding a contaminated tape must be cleaned before, not after, its only preservation transfer.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4dedca14-a439-5d66-893b-08c79ccadd10' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Abrasive contamination'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '4dedca14-a439-5d66-893b-08c79ccadd10','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4dedca14-a439-5d66-893b-08c79ccadd10' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ee5b1fd3-485c-5a96-ab86-ce50fbbb7471','Acetate-base decomposition','The chemical deterioration of a cellulose-acetate tape base through hydrolysis (deacetylation), in which the acetate reacts with moisture and releases acetic acid - the source of the characteristic vinegar odour. It makes the base brittle, causes it to shrink and warp, and eventually renders the tape too fragile or distorted to play; the reaction is autocatalytic, accelerating as acid accumulates.','Older tapes used a plastic base made from cellulose acetate. Over time, moisture makes it break down. It gives off a vinegar smell and turns brittle and warped. Cool, dry storage slows this down.','Recognising acetate-base decomposition exists so archivists can identify at-risk acetate tapes early, because the reaction feeds on itself and affected tapes must be prioritised for transfer and moved to cold, dry storage.','An archivist who detects a vinegar smell from a reel identifies acetate decay, flags the tape as high priority for transfer, and stores it cold and dry to slow the reaction.','Chemical Degradation',ARRAY['Vinegar syndrome','Base-film hydrolysis','Base film','Cellulose acetate','Print-through']::text[],ARRAY['Assuming a vinegar smell is harmless, when it signals active acetate decay that will accelerate and spread.','Confusing acetate-base decomposition with binder sticky-shed; they affect different layers and need different responses.','UNSAFE: Working with strongly decomposing acetate in an unventilated space, exposing yourself to concentrated acetic-acid vapour.']::text[],ARRAY['Opening a box of 1950s reels and noticing a sharp vinegar smell that signals acetate decay.','Prioritising badly decomposing acetate tapes for urgent transfer before they become unplayable.','Moving affected acetate tapes into cold, dry storage to slow further decomposition.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ee5b1fd3-485c-5a96-ab86-ce50fbbb7471' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Acetate-base decomposition'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'ee5b1fd3-485c-5a96-ab86-ce50fbbb7471','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ee5b1fd3-485c-5a96-ab86-ce50fbbb7471' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'fa6d21f1-7029-5c14-be4c-1ed7c30f0d3f','Adhesive failure','Loss of adhesion in a bonded joint within the tape package - most commonly the splicing-tape or leader-tape adhesive losing grip so splices separate, or, more broadly, the binder losing adhesion to the base so the magnetic coating lifts or delaminates. It threatens both the physical continuity of the tape and the integrity of the recorded signal.','Tape is held together by glues in a few places. Splices and the coating all rely on sticking. Adhesive failure is when one of these glue bonds lets go. Splices can pop apart or the coating can peel.','As a failure mode it identifies where a tape may physically come apart during handling or playback, so joints and coating adhesion can be inspected and repaired before a transfer is attempted.','Before running an old reel, a technician checks splices and leader joins for failing adhesive and re-splices weak joints so the tape does not part or spill during playback.','Tape Damage',ARRAY['Adhesive ooze','Splice','Binder hydrolysis','Delamination','Leader tape']::text[],ARRAY['Assuming every splice will hold, when old splicing-tape adhesive dries out and lets splices separate during playback.','Confusing adhesive failure of a splice with binder failure that peels the magnetic coating from the base.','Fast-winding a tape with failing splices, which can snap a splice and spill the pack.']::text[],ARRAY['Threading an old reel and finding its splices separating as the tape is wound.','Repairing failed leader and splice joins before attempting a transfer.','Inspecting an archive tape whose magnetic coating is lifting from the base.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='fa6d21f1-7029-5c14-be4c-1ed7c30f0d3f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Adhesive failure'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'fa6d21f1-7029-5c14-be4c-1ed7c30f0d3f','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='fa6d21f1-7029-5c14-be4c-1ed7c30f0d3f' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3d28eb5d-67e6-5ff7-a5c7-f31e06369a57','Adhesive ooze','The exudation or migration of adhesive out of its intended location - typically splice or leader-tape adhesive seeping from the edges of a join, or a pressure-sensitive adhesive bleeding between tape layers - leaving sticky residue on the tape surface, adjacent wraps and the tape path. It can cause layers to stick together (blocking), contaminate heads and guides, and jam playback.','Some splices and tapes have sticky glue that can seep out over time. This ooze spreads onto the tape and the next layer. It makes the tape stick to itself and leaves residue. That can jam the machine during playback.','The concept exists to alert technicians that migrating adhesive contaminates the tape and machine, so oozing joints must be identified and cleaned or replaced before playback.','Encountering a reel with adhesive seeping from its splices, a technician cleans the residue from the tape path and re-splices the joins before transferring.','Chemical Degradation',ARRAY['Adhesive failure','Splice','Blocking','Print-through','Tape cleaning']::text[],ARRAY['Storing spliced tapes in heat, which makes splice adhesive soften and ooze onto the tape and machine.','Confusing adhesive ooze from a splice with sticky-shed residue from binder breakdown.','Playing a tape with oozing adhesive without cleaning, letting sticky residue transfer to heads and guides.']::text[],ARRAY['Finding sticky residue oozing from splices on a tape stored in a warm room.','Cleaning oozed adhesive from tape guides and heads after a jammed playback.','Deciding to re-splice a reel whose original splice adhesive has bled onto the tape.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3d28eb5d-67e6-5ff7-a5c7-f31e06369a57' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Adhesive ooze'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '3d28eb5d-67e6-5ff7-a5c7-f31e06369a57','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='3d28eb5d-67e6-5ff7-a5c7-f31e06369a57' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4c34f0e8-d014-552c-b36f-1594e04dbd54','Adjacent-track crosstalk','Unwanted coupling of signal from one recorded track into a physically neighbouring track on the same tape, caused by fringing magnetic fields, finite guard-band spacing, and head geometry or misalignment. It reduces channel separation, so a faint copy of one track is reproduced on another.','A tape can hold several sound tracks side by side. Crosstalk is when one track leaks faintly into the track next to it. You hear a quiet copy of one channel in another. Good head alignment and spacing keep it low.','Understanding adjacent-track crosstalk matters because it sets a limit on channel separation in multitrack and stereo formats, and it distinguishes a tape-and-head problem from a fault in the original recording.','Hearing one channel bleed faintly into another during a multitrack transfer, an engineer checks head alignment and cleanliness before concluding the crosstalk is inherent to the tape.','Signal Degradation',ARRAY['Print-through','Azimuth error','Track format','Guard band','Channel separation']::text[],ARRAY['Blaming crosstalk on a bad recording when misaligned head azimuth or a dirty head is leaking signal between tracks.','Confusing adjacent-track crosstalk with print-through; crosstalk is between tracks, print-through is between tape layers.','Assuming crosstalk means the tape is faulty, when track layout and head alignment usually explain it.']::text[],ARRAY['Hearing a faint bleed of one channel into another on a multitrack tape transfer.','Checking head alignment and cleanliness after noticing track-to-track leakage.','Comparing tracks on a stereo master to judge whether crosstalk is on the tape or in the deck.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4c34f0e8-d014-552c-b36f-1594e04dbd54' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Adjacent-track crosstalk'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '4c34f0e8-d014-552c-b36f-1594e04dbd54','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4c34f0e8-d014-552c-b36f-1594e04dbd54' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '495c977d-abc8-55a2-9ce4-e8bbbdd6030c','Automatic azimuth correction','A capability in some tape reproducers or transfer workflows that automatically detects azimuth misalignment between the recorded tracks and the replay head and compensates for it - for example by servo-adjusting the head angle, or by realigning the channels'' timing in software - to maximise high-frequency output and restore correct inter-channel phase. It is used to play back tapes recorded on differently aligned machines.','Azimuth is the tilt of the playback head against the tape. If it is off, the high notes fade. Automatic azimuth correction adjusts the head or the signal by itself. It lines things up to bring back the treble.','It exists to recover high-frequency response and stereo phase lost to azimuth error without constant manual adjustment, which is valuable when transferring many tapes recorded on varied or misaligned machines.','Transferring cassettes recorded on unknown machines, an engineer uses a deck with automatic azimuth correction, or a software realignment step, to restore treble and phase without hand-aligning each tape.','Head Alignment',ARRAY['Azimuth error','Azimuth drift','Head alignment','Playback head','Phase error']::text[],ARRAY['Trusting automatic correction to fix a severely damaged or badly spliced tape, when only careful manual work will do.','Assuming automatic azimuth correction repairs the tape, when it only optimises playback of the existing recording.','Confusing automatic azimuth correction with fixed factory alignment that never adjusts to the tape.']::text[],ARRAY['Using a deck''s automatic azimuth feature to optimise playback of a cassette recorded on another machine.','Relying on automatic correction to steady high-frequency output on a tape with varying azimuth.','Comparing automatic correction against a careful manual alignment on a difficult transfer.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='495c977d-abc8-55a2-9ce4-e8bbbdd6030c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Automatic azimuth correction'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '495c977d-abc8-55a2-9ce4-e8bbbdd6030c','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='495c977d-abc8-55a2-9ce4-e8bbbdd6030c' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'cd849271-1815-5cb1-b8e2-a2e3d26f78d7','Azimuth drift','A gradual, progressive change in head azimuth - the angle of the head gap relative to the direction of tape travel - over time or during use, arising from head wear, mechanical loosening, thermal change or tape-pack effects. As azimuth drifts away from the correct perpendicular, high-frequency response falls and, on stereo or multitrack tapes, inter-channel phase errors grow.','Azimuth is the angle of the head against the moving tape. Drift means that angle slowly changes over time. As it drifts, the high notes fade and stereo can smear. Technicians recheck and reset the head to fix it.','The concept exists to remind technicians that a once-correct alignment does not stay fixed, so azimuth must be rechecked periodically to keep transfers consistent and full-bandwidth.','During a long transfer session a technician rechecks head azimuth against a reference, catching any drift before it quietly dulls the high frequencies of later tapes.','Head Alignment',ARRAY['Azimuth error','Automatic azimuth correction','Head alignment','High-frequency loss','Head wear']::text[],ARRAY['Setting head azimuth once and never rechecking it, so slow drift quietly robs the transfer of high frequencies.','Blaming dull high frequencies on the tape when the playback head azimuth has drifted out of alignment.','Confusing gradual azimuth drift with a fixed azimuth error present from the original recording.']::text[],ARRAY['Noticing the high frequencies slowly dulling across a long transfer session as head azimuth drifts.','Rechecking head azimuth partway through a batch of tapes to catch any drift.','Tracing a gradual loss of treble to a loosening head mount rather than the tape.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='cd849271-1815-5cb1-b8e2-a2e3d26f78d7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Azimuth drift'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'cd849271-1815-5cb1-b8e2-a2e3d26f78d7','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='cd849271-1815-5cb1-b8e2-a2e3d26f78d7' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b2b93fc7-1b72-51f3-b266-8edf85d88c91','Azimuth error','A misalignment in which the record or replay head gap is not perpendicular to the direction of tape travel, deviating from the correct azimuth. It causes progressive high-frequency loss, because the gap is effectively widened relative to the recorded wavelength, and, on stereo or multitrack tapes, time and phase differences between channels.','The playback head has a thin gap that should sit square to the tape. Azimuth error means that gap is tilted, not square. This mostly cuts the high notes and blurs stereo. Adjusting the head angle restores the sound.','Understanding azimuth error is essential because correct azimuth is required to recover the full recorded bandwidth and correct stereo phase; even a small error audibly dulls and smears the sound.','Before transferring a master, a technician sets replay-head azimuth with a high-frequency test tape and a phase meter, correcting any error so the high frequencies and stereo image are faithfully recovered.','Head Alignment',ARRAY['Azimuth drift','Automatic azimuth correction','Head alignment','High-frequency loss','Phase error']::text[],ARRAY['Adjusting azimuth by ear on music alone instead of using a test tape and a proper high-frequency reference.','Ignoring the phase meter, so stereo azimuth error passes unnoticed until the mix collapses in mono.','Assuming the replay head is square when a small azimuth error is already cutting the high frequencies.']::text[],ARRAY['Setting playback head azimuth with a test tape before transferring a stereo master.','Watching a phase meter collapse toward mono because of an azimuth error.','Adjusting azimuth per tape when reels were recorded on different, misaligned machines.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b2b93fc7-1b72-51f3-b266-8edf85d88c91' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Azimuth error'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b2b93fc7-1b72-51f3-b266-8edf85d88c91','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b2b93fc7-1b72-51f3-b266-8edf85d88c91' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b141b4c2-2d41-54be-a34f-8d3e61349913','Back coating','A coating - typically carbon black dispersed in a polymer binder - applied to the reverse, non-magnetic side of a tape''s base film. It bleeds off static charge, lowers friction, and improves winding so the tape forms a smooth, even, stable pack with consistent tension and tracking.','Many tapes have a dark coating on the back side. It is usually carbon that carries away static. It helps the tape wind evenly and run smoothly. This makes the tape pack neat and steady.','It exists to make professional tape wind and track reliably: the conductive, textured back layer prevents the static build-up and slippage that would otherwise cause uneven packs, cinching and tracking errors.','A technician recognises a back-coated professional tape by its dark, matte reverse and records that in the carrier''s technical description, knowing such tapes also need watching for back-coat degradation.','Tape Construction',ARRAY['Back-coat shedding','Back-coat transfer','Base film','Print-through','Tape pack']::text[],ARRAY['Assuming every tape has a back coating, when many early and consumer tapes have a bare, shiny base backing.','Mistaking a healthy carbon back coating for dirt and trying to clean it off the tape.','Confusing the back coating with the magnetic oxide layer, which is on the opposite side.']::text[],ARRAY['Identifying a back-coated professional tape by its dark, matte reverse side.','Explaining why a back-coated reel winds more evenly than a bare-based one.','Recording the tape''s back coating as part of a carrier''s technical description.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b141b4c2-2d41-54be-a34f-8d3e61349913' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Back coating'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b141b4c2-2d41-54be-a34f-8d3e61349913','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b141b4c2-2d41-54be-a34f-8d3e61349913' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a5380ffb-fdd3-5a3b-a2fc-0545645fa8a1','Back-coat shedding','Degradation of a tape''s back coating - commonly driven by hydrolysis of its binder - in which the coating loosens and sheds particulate debris. The shed material contaminates the tape path, clogs heads and guides, and can deposit onto the magnetic surface of adjacent wraps, causing dropouts and unstable playback.','The coating on the back of the tape can break down with age. When it does, it sheds loose black bits. These bits dirty the heads and the tape path. That causes dropouts and can gum up playback.','Recognising back-coat shedding matters because it identifies tapes that will foul the transport and lose signal during playback, so they can be cleaned and, where binder hydrolysis is involved, treated before transfer.','Seeing black residue accumulate on the heads and guides during playback, a technician identifies back-coat shedding, cleans the path frequently, and assesses whether the tape needs remedial treatment before a clean transfer.','Chemical Degradation',ARRAY['Back coating','Sticky shed syndrome','Binder hydrolysis','Back-coat transfer','Head clog']::text[],ARRAY['Playing a shedding back-coated tape without cleaning, so loose debris clogs the heads and causes dropouts.','Confusing back-coat shedding with oxide shedding from the magnetic side of the tape.','UNSAFE: Baking a sticky tape in an uncontrolled or kitchen oven; use only a calibrated incubator to a documented temperature and time, as overheating can damage the tape or cause fire.']::text[],ARRAY['Seeing black residue build up on the heads and guides from a shedding back-coated tape.','Cleaning the tape path repeatedly during transfer of a shedding reel.','Identifying a batch of 1970s-1980s tapes prone to back-coat shedding before playback.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a5380ffb-fdd3-5a3b-a2fc-0545645fa8a1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Back-coat shedding'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a5380ffb-fdd3-5a3b-a2fc-0545645fa8a1','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a5380ffb-fdd3-5a3b-a2fc-0545645fa8a1' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'abd0001d-a9b6-54a5-bc02-64bfd25b4827','Back-coat transfer','The migration of back-coating material onto the magnetic (oxide) surface of the adjacent tape layer, which it contacts when the tape is wound on a reel. Degrading or tacky back coat leaves imprint marks or deposits on the recorded side, which can contaminate the oxide and cause dropouts or added noise on playback.','On a reel, the back of one layer touches the front of the next. If the back coating goes bad, it can print onto that next layer. This leaves marks on the recorded side. Those spots can cause dropouts when you play the tape.','The concept exists to explain why marks or deposits appear on a tape''s recorded surface from its own back coat, so technicians treat them as a contamination and storage issue rather than as damage to the recording.','Finding faint imprint marks on the recorded side of a tightly wound reel, a technician attributes them to back-coat transfer, cleans the surface where possible, and rewinds the tape to relieve the contact.','Physical Degradation',ARRAY['Back coating','Back-coat shedding','Print-through','Dropout','Tape pack']::text[],ARRAY['Mistaking back-coat transfer marks on the recorded side for damage to the recording itself.','Confusing back-coat transfer between tape layers with adjacent-track crosstalk between tracks.','Leaving a degrading back-coated tape tightly wound in storage, letting transfer marks build up over time.']::text[],ARRAY['Finding faint imprint marks on the recorded side from the back coat of the adjacent layer.','Diagnosing periodic dropouts caused by back-coat deposits on the oxide surface.','Deciding to clean and rewind a tightly packed reel showing back-coat transfer.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='abd0001d-a9b6-54a5-bc02-64bfd25b4827' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Back-coat transfer'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'abd0001d-a9b6-54a5-bc02-64bfd25b4827','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='abd0001d-a9b6-54a5-bc02-64bfd25b4827' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '032b5b5e-10ed-571f-9c4c-60c5021ab95b','Base film','The flexible plastic substrate that forms the structural support of magnetic tape, onto which the magnetic (oxide and binder) layer and any back coating are applied. Historically it has been paper, cellulose acetate, PVC and - since the late 1950s - polyester (polyethylene terephthalate, PET), which provides the tape''s mechanical strength and dimensional stability.','Every tape is built on a thin plastic ribbon called the base. The magnetic coating is spread on top of it. The base gives the tape its strength and shape. Older bases used acetate; newer ones use polyester.','It exists to give the magnetic coating a strong, dimensionally stable, flexible carrier that can be wound, threaded and driven through a transport without tearing or distorting the recorded signal.','A technician identifies whether a reel''s base is acetate or polyester - for example by the vinegar smell and brittleness of decaying acetate - because base material governs how the tape ages and how it must be handled.','Tape Construction',ARRAY['Base thickness','Base-film hydrolysis','Acetate-base decomposition','Polyester base','Back coating']::text[],ARRAY['Confusing the base film with the magnetic coating; the base is the clear support, the coating holds the signal.','Assuming all tape bases are polyester, when older tapes use acetate or PVC that age very differently.','Judging base material by reel size instead of checking for tell-tale signs like the vinegar smell of acetate.']::text[],ARRAY['Determining whether a reel''s base is acetate or polyester before choosing handling steps.','Explaining that the clear ribbon under the coating is the base film that carries everything.','Recording base material in a tape''s condition report.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='032b5b5e-10ed-571f-9c4c-60c5021ab95b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Base film'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '032b5b5e-10ed-571f-9c4c-60c5021ab95b','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='032b5b5e-10ed-571f-9c4c-60c5021ab95b' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6c1c2664-6745-5028-82a4-5415b5232057','Base thickness','The thickness of a tape''s base film, a defining specification that, together with the coatings, sets total tape thickness and therefore the playing time per reel, the tape''s tensile strength, and its susceptibility to stretch and print-through. Thinner bases (used for long-, double- and triple-play tapes) fit more length on a reel but are weaker and more prone to print-through, while thicker standard-play bases are more robust.','Base thickness is how thick that plastic ribbon is. A thinner base lets more tape fit on a reel. But thin tape stretches more easily and prints through. Thicker tape is stronger but gives less playing time.','Base thickness exists as a design trade-off between playing time and durability: it lets manufacturers offer longer-running tapes at the cost of strength and increased print-through, which the technician must account for when handling them.','Handling a thin long-play or double-play reel, a technician uses gentle winding tension and careful transport settings to avoid stretching the delicate base, and notes the thin base as a print-through risk.','Tape Construction',ARRAY['Base film','Print-through','Tape stretch','Playing time','Polyester base']::text[],ARRAY['Assuming a thinner base is always better, when thin tape stretches and prints through more easily.','Confusing base thickness with total tape thickness, which also includes the coatings.','Fast-winding thin, long-play tape carelessly, which can stretch or deform the delicate base.']::text[],ARRAY['Choosing gentle winding tension for a thin, long-play tape to avoid stretch.','Explaining why a triple-play reel holds more minutes but is more fragile.','Noting base thickness when assessing print-through risk on a stored master.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6c1c2664-6745-5028-82a4-5415b5232057' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Base thickness'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6c1c2664-6745-5028-82a4-5415b5232057','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6c1c2664-6745-5028-82a4-5415b5232057' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6b5eaa14-1a61-5afa-b3ba-28f0bdecd352','Base-film hydrolysis','Hydrolytic chemical breakdown of the tape base film itself, in which water reacts with and cleaves the polymer of the substrate. In cellulose-acetate bases this is deacetylation, releasing acetic acid (vinegar syndrome) and embrittling the base; polyester (PET) bases hydrolyse far more slowly but can still be weakened by prolonged high temperature and humidity. It is distinct from binder hydrolysis, which attacks the magnetic coating''s binder and causes sticky-shed.','Hydrolysis means water slowly breaks a material down. Base-film hydrolysis is when the tape''s plastic base breaks down this way. Acetate bases turn brittle and smell like vinegar. This is not the same as the sticky coating fault called sticky shed.','Distinguishing base-film hydrolysis exists so technicians correctly identify degradation of the base - not the coating - and respond appropriately, since it points to acetate decay or extreme storage conditions rather than to sticky-shed.','Faced with a brittle, shrinking acetate reel, a technician recognises base-film hydrolysis, handles the fragile tape gently, and prioritises cold, dry storage and transfer, while knowing that sticky residue instead points to binder hydrolysis.','Chemical Degradation',ARRAY['Acetate-base decomposition','Binder hydrolysis','Vinegar syndrome','Base film','Sticky shed syndrome']::text[],ARRAY['Confusing base-film hydrolysis with binder hydrolysis; one attacks the plastic base, the other attacks the coating.','Assuming polyester tape can never hydrolyse, when heat and humidity can still slowly weaken the base.','UNSAFE: Handling brittle, hydrolysing acetate tape roughly can shatter it, and doing so in an unventilated area exposes you to acetic-acid vapour.']::text[],ARRAY['Handling a brittle acetate reel whose base is hydrolysing and prone to snapping.','Explaining to a student why base-film hydrolysis differs from sticky-shed binder breakdown.','Storing tapes cool and dry to slow hydrolysis of the base film.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6b5eaa14-1a61-5afa-b3ba-28f0bdecd352' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Base-film hydrolysis'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6b5eaa14-1a61-5afa-b3ba-28f0bdecd352','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6b5eaa14-1a61-5afa-b3ba-28f0bdecd352' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a400f530-97eb-5ba0-8cba-25a6bdaf722f','Binder breakdown','The general deterioration of the polymer binder, the flexible resin (typically polyurethane) that holds the magnetic pigment particles to the tape base and bonds any back coating. As the binder breaks down it loses cohesion and adhesion, so the magnetic layer softens, becomes sticky, sheds, or separates, degrading playback and threatening loss of the recording.','Tape has a soft glue layer that holds the magnetic powder onto the plastic base. Over time this glue can break down. Then the coating gets sticky, sheds, or flakes off. A tape like this can be hard to play safely.','Naming this failure mode lets archivists spot at-risk tapes early and choose the right stabilisation before playback, since the binder is the layer whose decay most often makes a tape unplayable.','A technician inspects and briefly test-plays a suspect reel; if the binder is breaking down, shown by squealing, shedding, or residue on the guides, they stop, clean, and often dehydrate the tape before transfer.','Binder Degradation',ARRAY['Binder hydrolysis','Binder exudation','Sticky-shed syndrome','Back coating','Coating delamination','Blocking']::text[],ARRAY['Assuming any squealing tape just needs cleaning, when binder breakdown usually requires dehydration (baking) before it can be played.','UNSAFE: Force-playing a shedding tape, which packs debris onto the heads and can permanently damage both the tape and the machine.','Confusing binder breakdown (loss of the binder polymer) with base-film problems such as acetate embrittlement or vinegar syndrome.']::text[],ARRAY['A back-coated master from the 1970s squeals and leaves brown residue on the guides during a test play.','An archive triages a donated collection and sets aside reels showing binder breakdown for dehydration.','A transfer engineer schedules baking after a tape sheds coating on its first pass.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a400f530-97eb-5ba0-8cba-25a6bdaf722f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Binder breakdown'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a400f530-97eb-5ba0-8cba-25a6bdaf722f','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a400f530-97eb-5ba0-8cba-25a6bdaf722f' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '540c9a7a-8b26-5e2c-ae11-88c803cab1fd','Binder exudation','The migration and deposit of binder components, commonly low-molecular-weight breakdown products, lubricant, or fatty-acid residues, onto the surface of the magnetic coating, appearing as a sticky film, a white powdery bloom, or crystalline deposits. It is a visible symptom of binder degradation and can cause head clogging, shedding, and playback dropouts.','As the tape''s glue layer breaks down, some of its ingredients ooze to the surface. This can look like a sticky film or a white powder. That deposit clogs the playback head and causes dropouts. It is a warning sign the tape is decaying.','Recognising exudation lets an archivist tell surface deposits that clean off from deeper binder failure, and confirms a tape needs cleaning or dehydration before transfer.','A technician who sees white bloom or a greasy film on the coating gently cleans the tape and checks for shedding before deciding on baking and transfer.','Binder Degradation',ARRAY['Binder hydrolysis','Binder breakdown','Sticky-shed syndrome','Back coating','Blocking','Coating delamination']::text[],ARRAY['Mistaking white exudation for mould; the two need very different handling and one requires biohazard precautions.','UNSAFE: Wiping deposits with unknown solvents or bare fingers, since wrong solvents dissolve the binder and skin oils further contaminate the tape; use approved methods and gloves.','Assuming a cleaned tape is cured, when exudation signals ongoing binder degradation that will recur.']::text[],ARRAY['A reel shows a fine white bloom along its edges when unboxed after decades in storage.','Playback dropouts trace to a greasy deposit exuded onto the coating surface.','A conservator records surface exudation as evidence of binder deterioration in a condition report.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='540c9a7a-8b26-5e2c-ae11-88c803cab1fd' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Binder exudation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '540c9a7a-8b26-5e2c-ae11-88c803cab1fd','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='540c9a7a-8b26-5e2c-ae11-88c803cab1fd' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6f2b5584-fc29-53f4-8df0-723c99335c33','Binder hydrolysis','The chemical reaction in which the polyurethane binder absorbs atmospheric moisture and its polymer chains split (hydrolyse), breaking the ester linkages. This softens the binder and produces a sticky, gummy surface that sheds debris and squeals on playback, the direct cause of sticky-shed syndrome. It can often be temporarily reversed for transfer by low-temperature dehydration (baking) that drives out moisture.','The glue layer on tape can soak up water from the air. That water slowly breaks the glue''s chemistry apart. The tape turns sticky and gummy and squeals when played. Gently warming, or baking, the tape can dry it enough for one safe transfer.','Understanding hydrolysis explains why sticky tapes exist, why cool dry storage prevents them, and why baking temporarily reverses the problem, guiding both storage policy and treatment.','When a tape squeals and sheds, a technician identifies hydrolysis and dehydrates the reel in a temperature-controlled scientific oven before making a single careful transfer.','Binder Degradation',ARRAY['Binder breakdown','Sticky-shed syndrome','Binder exudation','Back coating','Blocking','Coating delamination']::text[],ARRAY['UNSAFE: Baking tape in a kitchen or toaster oven, since uncontrolled heat warps the pack, melts splices, and can ruin the recording; only a calibrated low-temperature oven is safe.','Baking cellulose-acetate or PVC tapes, which do not suffer this hydrolysis and can be harmed by heat; baking treats polyurethane-binder (polyester) tapes only.','Treating baking as permanent, when the improvement fades, so the tape must be transferred promptly after it cools.']::text[],ARRAY['A polyester master from the 1980s squeals and deposits gummy residue, so it is baked before digitising.','An archivist keeps tape stores cool and dry to slow hydrolysis across a whole collection.','A technician re-bakes a reel that was stabilised months earlier and has turned sticky again.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6f2b5584-fc29-53f4-8df0-723c99335c33' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Binder hydrolysis'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6f2b5584-fc29-53f4-8df0-723c99335c33','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6f2b5584-fc29-53f4-8df0-723c99335c33' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'faa2dd0b-c131-501f-a8ba-f4757a890f4a','Blocking','A tape-pack defect in which adjacent wound layers adhere to one another, so the tape cannot unwind cleanly and pulls away in patches or as a solid mass. It arises when a degrading, tacky binder, high storage temperature or humidity, or migrating plasticiser bonds the wraps together.','On a wound reel, the layers of tape can stick to each other. Then the tape will not peel apart smoothly when you try to play it. Heat, damp, and a sticky, aging coating all cause this. A badly blocked tape can tear as it unwinds.','Identifying blocking warns a technician that forcing playback will tear or stretch the tape, so the pack must be stabilised or eased apart first.','Facing a blocked reel, a technician avoids machine playback, and instead conditions or dehydrates the tape and, if needed, carefully separates layers by hand before transfer.','Winding Defect',ARRAY['Cinching','Binder hydrolysis','Binder breakdown','Sticky-shed syndrome','Back coating']::text[],ARRAY['UNSAFE: Powering a blocked section through a deck, which snaps or stretches the tape and can damage the transport.','Confusing blocking (layers stuck together) with cinching (layers slipping and creasing).','Storing tapes in hot or humid conditions, which promotes blocking over time.']::text[],ARRAY['A reel stored in a warm attic will not unspool because its wraps have bonded together.','A technician hand-separates blocked layers under low tension before a rescue transfer.','Condition-reporting a collection reveals several blocked reels needing treatment.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='faa2dd0b-c131-501f-a8ba-f4757a890f4a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Blocking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'faa2dd0b-c131-501f-a8ba-f4757a890f4a','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='faa2dd0b-c131-501f-a8ba-f4757a890f4a' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'fdce1f80-1013-5b29-a955-760885f02687','Calendering','A finishing step in magnetic-tape manufacture in which the coated web is passed under high pressure, often with heat, between hard polished rollers to compact and smooth the magnetic coating. Calendering densifies the pigment packing and reduces surface roughness, improving head-to-tape contact and high-frequency output.','When tape is made, the wet magnetic coating dries a little rough. Calendering squeezes it between smooth, hard rollers. This flattens and packs the coating tight. A smoother surface touches the playback head better and gives a stronger signal.','It exists to minimise the microscopic gap between tape and head, called spacing loss, and to raise coating density, both of which increase signal level and high-frequency response.','Preservation staff do not calender tape, but they use the concept to explain why a smooth, intact coating reads well and why surface damage or roughening lowers output.','Tape Manufacture',ARRAY['Calendering loss','Coating adhesion','Carbon back coating','Coating delamination','Binder breakdown']::text[],ARRAY['Assuming calendering adds a separate layer, when it only compresses and smooths the coating already applied.','Confusing calendering (a manufacturing step) with polishing damage or wear that happens later in use.','Thinking a glossier tape is always better, when over-calendering or later surface changes can still cause problems.']::text[],ARRAY['Explaining to a trainee why a smooth coating gives higher output than a rough one.','Diagnosing why a physically abraded tape has lost high-frequency response.','Comparing formulations where coating smoothness affects the recorded level.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='fdce1f80-1013-5b29-a955-760885f02687' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Calendering'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'fdce1f80-1013-5b29-a955-760885f02687','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='fdce1f80-1013-5b29-a955-760885f02687' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7758cdd6-f188-566c-8056-5109991a53f2','Calendering loss','The loss of high-frequency signal output that results when a tape''s coating surface is not smooth enough, because calendering was inadequate or the calendered finish has since roughened, increasing the effective head-to-tape spacing. Since reproduced level falls steeply as spacing grows, even slight surface roughness cuts the recovered signal, most severely at short wavelengths.','A tape''s coating must be very smooth to sit right against the playback head. If the surface is rough, a tiny air gap forms. That gap cuts the high notes the most. This drop in signal from a rough surface is calendering loss.','The concept links coating smoothness to output, helping technicians see why surface roughening, from poor manufacture or wear, quietly erodes high-frequency fidelity.','When a transfer sounds dull with weak treble and the tape looks abraded or matte, a technician suspects surface roughness and spacing loss rather than a head or alignment fault.','Signal Loss',ARRAY['Calendering','Coating delamination','Coating adhesion','Carbon back coating','Binder breakdown']::text[],ARRAY['Blaming dull high frequencies only on head wear or alignment, and overlooking a rough or damaged coating surface.','Assuming coating smoothness affects all frequencies equally, when spacing loss hits the high end hardest.','Cleaning ever more aggressively to restore treble, which can abrade the surface and worsen the loss.']::text[],ARRAY['A worn tape transfers with muffled treble despite a correctly aligned machine.','Comparing two copies where the rougher-surfaced tape reproduces less high-frequency detail.','Explaining why physical surface care matters as much as electronics for fidelity.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7758cdd6-f188-566c-8056-5109991a53f2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Calendering loss'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '7758cdd6-f188-566c-8056-5109991a53f2','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7758cdd6-f188-566c-8056-5109991a53f2' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c5e9a038-fc48-52dc-84d0-021080beb2e1','Capstan eccentricity','A mechanical fault in which the capstan, the driven spindle that pulls tape at constant speed, is not perfectly round or runs off its true axis, so its effective diameter varies as it rotates. This produces a periodic speed variation (wow and flutter) once per capstan revolution, heard as pitch instability.','The capstan is the small spinning shaft that pulls tape along at a steady speed. It may be slightly out of round or off-center. Then the tape speeds up and slows down a little each turn. You hear this as a wobble in pitch. It shows up most on long, steady notes.','Knowing this failure mode lets a technician trace a regular, once-per-revolution pitch wobble to the capstan or its bearing rather than to the tape or the recording.','When playback shows periodic flutter, a technician checks capstan runout, bearing wear, and cleanliness, and services or replaces the capstan before an archival transfer.','Speed and Transport',ARRAY['Capstan imprint','Capstanless correction','Wow and flutter','Pinch roller','Cinching']::text[],ARRAY['Blaming wow and flutter on the tape when a worn or dirty capstan is the true cause.','Ignoring a worn capstan bearing, which adds periodic speed error that no alignment can fix.','Assuming digital capture removes the problem, when a mechanical speed error is captured into the file unless corrected.']::text[],ARRAY['A sustained piano note in a transfer wavers in pitch once per capstan turn.','A technician measures speed with a test tone and finds periodic flutter from capstan runout.','Servicing an old deck''s capstan assembly before a batch of preservation transfers.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c5e9a038-fc48-52dc-84d0-021080beb2e1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Capstan eccentricity'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c5e9a038-fc48-52dc-84d0-021080beb2e1','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c5e9a038-fc48-52dc-84d0-021080beb2e1' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f727655f-d973-5245-adde-9e97f21608dc','Capstan imprint','A physical deformation or mark left across the tape where it was pressed between the capstan and pinch roller for a prolonged period, typically when a reel is stored still threaded in the transport. The localised set or ridge can cause a brief level drop, flutter tick, or tracking disturbance each time that point passes the head.','The capstan and a rubber roller pinch the tape to pull it along. If a tape is left sitting in the machine a long time, that squeeze can leave a mark on it. When you later play the tape, that spot gives a little glitch or dropout. So tapes should be taken off the machine for storage.','The term reminds technicians never to store tape parked in the transport, because sustained pinch-roller pressure can permanently deform the tape at one spot.','After a session, a technician unloads and rewinds tapes onto storage reels rather than leaving them threaded, avoiding a pressure imprint at the capstan.','Speed and Transport',ARRAY['Capstan eccentricity','Pinch roller','Print-through','Capstanless correction','Cinching']::text[],ARRAY['Storing a tape still threaded on the deck, letting the pinch roller press one spot for months.','Confusing a mechanical capstan imprint with magnetic print-through, which is signal transfer between layers.','Leaving a reel paused under tension during a break instead of parking the transport safely.']::text[],ARRAY['A tape left in a machine for years shows a repeating dropout at one point on playback.','An archive''s handling policy requires tapes to be wound off machines for storage.','Diagnosing a periodic tick that matches a visible mark on the tape.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f727655f-d973-5245-adde-9e97f21608dc' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Capstan imprint'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'f727655f-d973-5245-adde-9e97f21608dc','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f727655f-d973-5245-adde-9e97f21608dc' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a7cd7572-4c64-5e1b-abe3-4f40f8be7b87','Capstanless correction','A replay and restoration approach that transfers tape without relying on the capstan to hold speed constant, and instead corrects wow, flutter, and long-term speed error in software. A stable reference recorded on the tape, such as the recorder''s high-frequency bias, an AC mains-hum component, or a pilot tone, is tracked and used to resample the audio back to correct pitch and timing.','Normally a spinning shaft, the capstan, keeps tape moving at a steady speed. In capstanless correction the machine does not fight to hold speed. Instead, software measures the tiny speed changes using a steady signal already on the tape. It then stretches and squeezes the sound to fix the pitch.','It exists to recover tapes whose speed a mechanical transport cannot stabilise, such as shrunken, damaged, or off-speed originals, by fixing timing errors after capture rather than during it.','For a problem tape, an engineer captures the signal, sometimes off a specially instrumented transport, then runs software that reads the bias or pilot reference and removes flutter and pitch drift.','Speed and Transport',ARRAY['Capstan eccentricity','Wow and flutter','Capstan imprint','Pilot tone','Time-base correction']::text[],ARRAY['Expecting software correction to fix speed errors when there is no usable reference signal on the tape.','Assuming it replaces good mechanical setup, when a clean, stable capture still gives the best starting point.','Confusing speed and pitch correction with noise reduction; capstanless correction fixes timing, not hiss.']::text[],ARRAY['A shrunken acetate tape runs unevenly, so its flutter is corrected in software using the bias signal.','An engineer recovers a field recording''s pitch by tracking its mains-hum reference.','A restoration house transfers a warped master and removes residual wow after capture.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a7cd7572-4c64-5e1b-abe3-4f40f8be7b87' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Capstanless correction'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a7cd7572-4c64-5e1b-abe3-4f40f8be7b87','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a7cd7572-4c64-5e1b-abe3-4f40f8be7b87' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'de4a0dbe-56b0-5947-a2ed-a49948ddf8dd','Carbon back coating','A thin, matte layer of carbon black in a binder applied to the reverse, non-magnetic side of many professional tapes. Being electrically conductive and slightly rough, it dissipates static charge, gives a firmer and more even wound pack, and reduces friction and tracking errors during transport.','Many pro tapes have a dull black layer on the back. It is made with carbon, which carries away static electricity. It also grips a little, so the tape winds in a neat, even roll. This helps the tape run smoothly and stack without slipping.','It exists to control static, steady tape tension and winding, and cut friction, but its own binder can also degrade, so it is a known site of shedding.','A technician recognises a matte black backing as a back-coated professional tape and watches such tapes for back-coat shedding and sticky-shed during handling.','Tape Construction',ARRAY['Binder breakdown','Binder hydrolysis','Sticky-shed syndrome','Blocking','Cinching']::text[],ARRAY['Thinking the back coating carries signal, when only the front magnetic coating records audio.','UNSAFE: Ignoring black residue shedding from the back coat, then force-playing and clogging the heads with debris.','Assuming all tapes are back-coated, when many consumer and early tapes have a bare, shiny base backing.']::text[],ARRAY['Black powder on the guides reveals that a back-coated master is shedding.','Identifying a professional tape by its matte black reverse side before transfer.','Explaining why back-coated tapes wind more evenly than uncoated ones.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='de4a0dbe-56b0-5947-a2ed-a49948ddf8dd' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Carbon back coating'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'de4a0dbe-56b0-5947-a2ed-a49948ddf8dd','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='de4a0dbe-56b0-5947-a2ed-a49948ddf8dd' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'da438d65-d05b-57ff-a717-dca48a6d08a0','Cellulose-acetate base','An early magnetic-tape base film, or backing, made of cellulose-acetate plastic, common from the 1930s to the early 1960s before polyester (PET) replaced it. It is comparatively brittle and chemically unstable: it absorbs moisture, embrittles with age, and can undergo vinegar syndrome, releasing acetic acid, shrinking, and cracking so the tape snaps easily.','The clear plastic ribbon that carries the magnetic coating is called the base. Early tapes used a base made of cellulose acetate. Over time this plastic gets brittle and can smell like vinegar. Old acetate tape snaps easily, so it must be handled very gently.','Identifying an acetate base tells an archivist the tape is fragile and chemically decaying, so it needs gentle handling, cool dry storage, and priority transfer before it becomes unplayable.','A technician spots acetate by a vinegar odour, brittleness, splice behaviour, or by holding the reel to light, since acetate is often translucent, then handles and transfers it with extra care.','Tape Base Film',ARRAY['Polyester base','Vinegar syndrome','Coating delamination','Coating adhesion','Cinching']::text[],ARRAY['UNSAFE: Winding or playing brittle acetate at normal tension or speed, causing it to snap or shatter; it needs low tension and slow, careful handling.','Baking acetate tape, when baking treats polyurethane-binder hydrolysis, not acetate base decay, and heat can harm acetate.','Confusing acetate base decay (vinegar syndrome, in the backing) with binder breakdown (in the coating).']::text[],ARRAY['A reel from the 1950s smells of vinegar and cracks when flexed, marking an acetate base.','An archivist prioritises acetate tapes for transfer before they embrittle further.','Handling a translucent, brittle tape under low tension to avoid breakage.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='da438d65-d05b-57ff-a717-dca48a6d08a0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cellulose-acetate base'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'da438d65-d05b-57ff-a717-dca48a6d08a0','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='da438d65-d05b-57ff-a717-dca48a6d08a0' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '762fee31-0b72-57ec-8308-727e7094efe9','Cinching','A winding defect in which loosely or unevenly wound layers of tape slip past one another, then buckle into folds or creases when the pack suddenly tightens, for example on a fast start, stop, or drop. The resulting kinks cause dropouts and permanent creases; the associated star-shaped pattern of loose loops is called spoking (pack slip is a distinct defect: lateral slippage of the wound layers).','If a reel is wound loosely, the tape layers can slide against each other. A sudden jerk then makes them bunch up into folds and creases. These kinks damage the tape and cause dropouts. Winding tapes smoothly and evenly prevents it.','Naming cinching tells a technician that loose or jerky winding creases tape, so smooth, even-tension library winds and gentle handling are needed to protect the pack.','Before storage, a technician gives each reel a smooth, even library wind at play speed rather than a fast, uneven one, reducing the chance of cinching and creasing.','Winding Defect',ARRAY['Blocking','Pack slip','Spoking','Coating delamination','Cellulose-acetate base']::text[],ARRAY['UNSAFE: Fast-winding or abruptly stopping a loosely packed reel, which cinches and permanently creases the tape.','Storing tapes wound at uneven tension, which leaves a loose pack prone to slipping.','Confusing cinching (layers slipping and creasing) with blocking (layers stuck together).']::text[],ARRAY['A loosely wound reel is jolted in transit and arrives with folded, creased tape.','A sudden machine stop buckles slack layers, leaving a run of dropouts.','An archivist library-winds incoming reels to firm, even packs before shelving.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='762fee31-0b72-57ec-8308-727e7094efe9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cinching'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '762fee31-0b72-57ec-8308-727e7094efe9','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='762fee31-0b72-57ec-8308-727e7094efe9' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ef73edc1-7cfe-557e-95a0-201f11f81785','Coating adhesion','The strength of the bond between the magnetic coating, or the back coating, and the base film that carries it. Good adhesion keeps the coating firmly attached during winding and playback; when adhesion fails through binder degradation, flexing, or poor manufacture, the coating can shed, flake, or delaminate from the base.','The magnetic coating must stick tightly to the plastic base underneath it. Coating adhesion is how well that bond holds. If the bond weakens, the coating flakes or peels away from the base. A tape losing its coating is losing the recording itself.','The concept explains why a tape can physically lose its recorded layer, guiding inspection for flaking or lifting coating and decisions about whether a tape is safe to play.','A technician inspecting a fragile tape checks whether the coating is lifting or flaking; if adhesion is failing, playback is avoided or done with extreme care to prevent losing coating on the heads.','Coating Integrity',ARRAY['Coating delamination','Binder breakdown','Carbon back coating','Calendering','Cellulose-acetate base']::text[],ARRAY['UNSAFE: Playing a tape whose coating is lifting, which strips the magnetic layer onto the heads and destroys the recording.','Assuming adhesion problems are always chemical, when flexing, heat cycling, and poor manufacture also weaken the bond.','Confusing coating adhesion (the coating-to-base bond) with binder cohesion (holding the pigment within the coating).']::text[],ARRAY['A tape''s coating flakes off onto the guides, revealing clear base film underneath.','Inspecting an old reel shows the magnetic layer lifting at the edges.','Deciding a tape with failing adhesion is too fragile to play without treatment.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ef73edc1-7cfe-557e-95a0-201f11f81785' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Coating adhesion'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'ef73edc1-7cfe-557e-95a0-201f11f81785','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ef73edc1-7cfe-557e-95a0-201f11f81785' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '96f2d7d0-719a-54fb-8d01-3f1f6f2d3340','Coating delamination','The physical separation of the magnetic coating from the tape base, or of coating layers from one another, so the recorded layer lifts, flakes, or peels away. It results from failed coating adhesion through binder degradation, base instability, mechanical stress, or moisture, and causes irreversible signal loss wherever coating is lost.','Delamination is when the magnetic coating peels away from the plastic base. The recorded layer lifts off in flakes. Wherever the coating is gone, that part of the recording is lost for good. It is one of the most serious kinds of tape damage.','The term flags the most destructive physical failure of a tape, telling a technician that any coating lost is unrecoverable and that such tapes need specialist handling and immediate assessment.','When a technician sees the coating peeling or shedding in flakes, they stop normal playback and consult a conservator, since a single pass could shed away irreplaceable audio.','Coating Integrity',ARRAY['Coating adhesion','Binder breakdown','Binder hydrolysis','Cellulose-acetate base','Calendering loss']::text[],ARRAY['UNSAFE: Test-playing a delaminating tape, which sheds the coating onto the heads and permanently erases that audio.','Believing lost coating can be re-adhered, when delamination is essentially irreversible where the layer is gone.','Confusing delamination (coating separating from the base) with shedding of loose surface debris that can clean off.']::text[],ARRAY['Sections of a brittle old tape shed their coating, leaving bare, clear base.','A conservator documents delamination as a reason a recording is only partly recoverable.','Triage flags a flaking reel for specialist treatment rather than routine transfer.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='96f2d7d0-719a-54fb-8d01-3f1f6f2d3340' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Coating delamination'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '96f2d7d0-719a-54fb-8d01-3f1f6f2d3340','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='96f2d7d0-719a-54fb-8d01-3f1f6f2d3340' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ffa33e4a-ca88-5455-b017-7fed1272129c','Coating friability','The tendency of a magnetic tape''s oxide coating to crumble or powder because its binder has lost cohesive strength, so the magnetic pigment is no longer firmly held and detaches as loose particles rather than a continuous film. Friability typically follows binder hydrolysis and related chemical degradation of the polyurethane binder.','Friable means it crumbles easily. The glue that holds the magnetic powder onto the tape breaks down over time. Then the coating turns powdery and flakes off. This is a sign the tape is decaying.','Naming this failure lets conservators grade a tape''s condition and predict shedding, dropouts, and information loss, guiding whether it needs treatment before transfer.','A technician inspecting a reel notes coating that rubs off as dust on a lint-free wipe, records it as friable, and schedules cleaning or treatment before attempting a transfer.','Coating degradation',ARRAY['Coating shed','Cohesive failure','Sticky-shed syndrome','Dropout','Dispersion quality']::text[],ARRAY['Confusing friability, where the coating crumbles on its own, with sticky-shed, where the coating instead turns gummy and sheds sticky residue','Assuming a friable tape can be safely played once, when even one pass can strip coating and lose the recording','UNSAFE: Handling heavily shedding or mouldy tape without gloves and an N95 respirator, letting fine oxide and binder dust be inhaled']::text[],ARRAY['Assessing an old reel whose oxide leaves a brown powder on the guides','Deciding a crumbling tape must be transferred by a specialist rather than played in-house','Documenting coating condition during a collection survey']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ffa33e4a-ca88-5455-b017-7fed1272129c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Coating friability'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'ffa33e4a-ca88-5455-b017-7fed1272129c','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ffa33e4a-ca88-5455-b017-7fed1272129c' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4bfd5373-c102-5b38-ba0e-5be2b764cf42','Coating shed','The physical loss of magnetic coating from a tape, in which oxide or metal pigment and degraded binder flake, rub, or slough off the base film during handling or playback, leaving deposits on heads, guides, and the tape path. It is a hallmark of binder degradation, including sticky-shed syndrome.','Shed means shedding, so the coating comes off the tape. The magnetic layer flakes or rubs away as the tape ages or plays. The loose material clogs the machine and drops out the sound. It means the recording is being lost.','It gives archivists a diagnostic term for why a tape clogs heads and loses signal, so they can decide on cleaning or remediation before transfer.','During a transfer the technician sees brown or black deposits building up on the heads and pinch roller, stops, and cleans between passes to limit further loss.','Coating degradation',ARRAY['Coating friability','Sticky-shed syndrome','Dropout','Cohesive failure','Debris embossing']::text[],ARRAY['Continuing to play a shedding tape, which grinds off more coating with every pass','UNSAFE: Cleaning shed residue with unknown or aggressive solvents that dissolve the binder or give off harmful fumes','Blaming a dirty head on the machine when the tape itself is shedding']::text[],ARRAY['Heads clogging repeatedly during a reel-to-reel transfer','Finding oxide dust inside a cassette shell','Planning a cleaning pass before digitising a deteriorated tape']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4bfd5373-c102-5b38-ba0e-5be2b764cf42' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Coating shed'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '4bfd5373-c102-5b38-ba0e-5be2b764cf42','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4bfd5373-c102-5b38-ba0e-5be2b764cf42' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd5123541-7537-5a7e-a8c2-b553c6eb0bc1','Coating thickness','The depth of the magnetic layer applied over the base film, typically a few micrometres. It is a manufacturing parameter that influences output level and short-wavelength (high-frequency) response: thicker coatings raise long-wavelength output but suffer greater self-demagnetisation and thickness loss at short wavelengths.','This is how thick the magnetic layer is on the tape. A thicker layer can give a louder low sound. But it records high sounds less well. Makers pick the thickness to balance these two.','Coating thickness sets the trade-off between signal output and high-frequency detail, a design choice fixed when the tape is manufactured.','A technician matching a machine to an unknown archival tape recognises that thin, long-play stocks behave differently on playback and are more fragile than thicker standard-play tape.','Tape construction',ARRAY['Double-play tape','Coating-to-backing interaction','Dispersion quality','Print-through','Coating shed']::text[],ARRAY['Thinking a thicker coating is always better, when it worsens short-wavelength output','Confusing coating thickness with total tape thickness, which also includes the base film','Assuming all reels of the same size hold the same length, ignoring thinner long-play stocks']::text[],ARRAY['Identifying a thin long-play tape that needs gentle handling','Explaining why an old tape sounds dull at high frequencies','Selecting archival tape stock with an appropriate thickness']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d5123541-7537-5a7e-a8c2-b553c6eb0bc1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Coating thickness'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'd5123541-7537-5a7e-a8c2-b553c6eb0bc1','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d5123541-7537-5a7e-a8c2-b553c6eb0bc1' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c4b8c9bd-b2dc-53e8-851c-bc7c0eb65cd8','Coating-to-backing interaction','The mechanical and chemical relationship between the magnetic coating and the base film it is bonded to, including adhesion at the interface, differing response to temperature and humidity, and migration of binder or back-coat components. Imbalances in this interaction produce curl, cupping, or delamination.','The magnetic coating is stuck onto a plastic backing. The two layers must stay bonded and move together. If they swell or shrink by different amounts, the tape curls or the coating peels. Heat and moisture make this worse.','Understanding this interaction explains why tapes curl, cup, or shed, and why controlling temperature and humidity keeps the two layers dimensionally matched.','A conservator seeing a tape that curls across its width traces it to differential shrinkage between coating and backing and improves the storage climate to prevent further distortion.','Tape construction',ARRAY['Cupping','Coating shed','Cohesive failure','Coating thickness','Dish']::text[],ARRAY['Treating the coating and backing as independent, ignoring that a backing problem distorts the coating and playback','Blaming curl only on the backing, when differential coating shrinkage is often the driver','UNSAFE: Storing tape in hot, damp attics or basements where humidity cycling drives the layers apart']::text[],ARRAY['Diagnosing why a reel has cupped across its width','Investigating coating delamination on an old tape','Setting storage climate to keep tape layers stable']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c4b8c9bd-b2dc-53e8-851c-bc7c0eb65cd8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Coating-to-backing interaction'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c4b8c9bd-b2dc-53e8-851c-bc7c0eb65cd8','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c4b8c9bd-b2dc-53e8-851c-bc7c0eb65cd8' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd0eea2f9-1081-5bec-aafc-a44bcb2d59cc','Cohesive failure','A breakdown within the body of the magnetic coating itself, in which the binder loses internal cohesion so the layer splits or crumbles internally, as opposed to adhesive failure, where the coating separates cleanly from the base film at the interface. It is commonly caused by binder hydrolysis weakening the polymer network.','A tape''s coating is powder held together by a glue-like binder. Cohesive failure is when that binder loses its inner strength. The coating then breaks apart within itself and crumbles. This is different from the whole layer peeling off the backing.','Distinguishing cohesive from adhesive failure tells a conservator whether the coating is disintegrating internally or delaminating, which points to different causes and treatments.','Examining shed debris, a technician judges whether the coating is powdering from within (cohesive) or lifting in flakes from the backing (adhesive) and reports the mechanism.','Coating degradation',ARRAY['Coating friability','Coating shed','Coating-to-backing interaction','Dispersion quality','Sticky-shed syndrome']::text[],ARRAY['Using cohesive and adhesive failure interchangeably, when they describe different break planes','Assuming powdering always means the coating has lifted from the backing','Overlooking binder hydrolysis as the usual underlying cause']::text[],ARRAY['Classifying how a deteriorated coating is failing during condition assessment','Explaining why a tape crumbles rather than peels','Choosing a remediation route based on the failure mode']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d0eea2f9-1081-5bec-aafc-a44bcb2d59cc' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cohesive failure'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'd0eea2f9-1081-5bec-aafc-a44bcb2d59cc','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d0eea2f9-1081-5bec-aafc-a44bcb2d59cc' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '01fa4856-d481-5913-b8ce-2756554d81cd','Cold-storage acclimation','The controlled process of letting tape removed from cold or cool storage warm gradually to the temperature of the work area while sealed in a moisture barrier, so its surface never falls below the dew point and condensation cannot form. Required acclimation time increases with pack size and with the temperature and humidity difference.','Tapes are kept cool to slow decay. A cold tape brought into a warm room can get wet with condensation, like a cold drink can. So it is warmed up slowly while still sealed in its bag. Only after it reaches room temperature is it safe to open and play.','It prevents condensation on cold media, which would cause moisture damage, mould, and handling problems, letting archives use cool storage safely.','Before digitising, a technician takes reels from the cold vault, leaves them bagged on a shelf for the required hours, and only unwraps them once they reach room temperature.','Storage practice',ARRAY['Cold storage','Relative humidity','Mould','Controlled unspooling','Coating-to-backing interaction','Environmental acclimatization']::text[],ARRAY['Opening the sealed bag before the tape has warmed up, causing condensation on the tape','Guessing the wait time, when large reels need far longer than cassettes','UNSAFE: Rushing acclimation with a heater or hot air, which can warp the pack and still drive condensation']::text[],ARRAY['Pulling reels from a cold vault for a digitisation session','Returning acclimated tapes to cool storage after transfer','Setting a workflow rule for how long each format must acclimate']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='01fa4856-d481-5913-b8ce-2756554d81cd' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cold-storage acclimation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '01fa4856-d481-5913-b8ce-2756554d81cd','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='01fa4856-d481-5913-b8ce-2756554d81cd' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'fb25b498-0c27-5580-ac49-30c997529a52','Contour effect','A low-frequency reproduction artefact in tape recording in which the replay head produces undulations or ripples in its response at wavelengths comparable to the physical dimensions of the head, because flux paths around the finite head structure add and cancel. It is also known as head bumps.','When a tape plays, very low sounds make long wave patterns on it. These can be as long as the playback head is big. The head then adds and cancels the signal unevenly. This makes bumps and dips in the low frequencies.','Recognising the contour effect explains uneven bass response on tape machines and shows it is a property of the head geometry, not a fault in the tape.','An engineer aligning a reel machine sees ripples in the low-frequency response and attributes them to head contour bumps rather than adjusting the tape or electronics.','Playback artifact',ARRAY['Dropout','Coating thickness','Print-through','Frequency response','Head clog']::text[],ARRAY['Mistaking contour-effect bass ripples for a damaged tape or a bad recording','Trying to fix head bumps with equalisation without understanding they come from head geometry','Confusing the low-frequency contour effect with high-frequency losses']::text[],ARRAY['Interpreting a wavy low-frequency response during machine alignment','Comparing bass response between machines with different head sizes','Explaining bass unevenness on a transferred archival tape']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='fb25b498-0c27-5580-ac49-30c997529a52' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Contour effect'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'fb25b498-0c27-5580-ac49-30c997529a52','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
