INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '383b7933-41b1-5027-aa2a-d6828284e1c4','Controlled unspooling','The deliberate, low-tension unwinding of a tape, often by hand or on a machine at reduced speed, to inspect, clean, dry, or free stuck windings without stretching, creasing, or shedding the coating. It is a conservation handling technique for fragile or stuck tapes.','Fragile tape can stretch or tear if pulled fast. Controlled unspooling means unwinding it slowly and gently. It is done to check it, clean it, or free stuck layers. Careful tension keeps the tape from being damaged.','It lets conservators access and treat fragile tape while keeping mechanical stress low enough to avoid stretching, creasing, or coating loss.','Facing a tape stuck to itself, a technician hand-winds it slowly onto another reel, easing apart windings rather than letting a machine yank it at speed.','Handling technique',ARRAY['Crease memory','Coating shed','Cold-storage acclimation','Sticky-shed syndrome','Dish']::text[],ARRAY['Using a normal fast wind or play speed on a fragile tape, which stretches or snaps it','Forcing stuck windings apart instead of easing them under gentle, even tension','UNSAFE: Unspooling mouldy tape without gloves and a respirator, spreading spores and inhaling them']::text[],ARRAY['Freeing a sticky-shed tape that has bound to itself','Inspecting the full length of a fragile reel for damage','Gently winding tape during a cleaning or drying treatment']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='383b7933-41b1-5027-aa2a-d6828284e1c4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Controlled unspooling'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '383b7933-41b1-5027-aa2a-d6828284e1c4','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='383b7933-41b1-5027-aa2a-d6828284e1c4' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5d9fa542-95ca-528a-9110-6192d7c4bb9d','Crease memory','The tendency of a polyester tape to retain a permanent crease, fold, or wrinkle after being sharply bent, because the base film has been plastically deformed beyond its elastic limit and holds the deformation. Creased sections lift off the head and cause dropouts.','Bend a plastic tape too far and it keeps the fold. The tape remembers the crease and will not lie flat again. Creased parts lift away from the playback head. That makes the sound or picture drop out.','The term flags permanent physical damage that cannot simply be flattened out, warning that creased tape will lose head contact and lose signal there.','Spotting a shiny crease line across a tape, a technician expects a dropout at that point and handles the section carefully during transfer.','Physical deformation',ARRAY['Cupping','Dish','Dropout','Debris embossing','Controlled unspooling']::text[],ARRAY['Believing a creased tape can be fully flattened back to normal, when the deformation is permanent','Winding tape under uneven tension, creating creases that then set in','Ignoring a crease until it causes a dropout during transfer']::text[],ARRAY['Finding a folded tape end that was caught in a machine','Diagnosing a repeating dropout at a creased section','Handling a wrinkled leader during rewinding']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5d9fa542-95ca-528a-9110-6192d7c4bb9d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Crease memory'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '5d9fa542-95ca-528a-9110-6192d7c4bb9d','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='5d9fa542-95ca-528a-9110-6192d7c4bb9d' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e5ca4715-e937-5f6c-b737-733a7ff6f874','Cupping','A lateral curl in which a tape curves across its width into a shallow trough or U shape, caused by differential dimensional change between the magnetic coating and the base film, for example the coating shrinking more than the backing. Cupping lifts the tape edges away from the head and degrades contact.','Cupping is when a flat tape curls sideways into a shallow U. It happens because the coating and the backing shrink by different amounts. The curled tape no longer sits flat on the playback head. That weakens contact and hurts the signal.','Naming cupping lets a conservator recognise poor head contact caused by curl and link it to differential shrinkage and storage climate.','A technician noticing a tape that will not lie flat across a guide identifies cupping and expects unstable level and high-frequency loss on playback.','Physical deformation',ARRAY['Dish','Crease memory','Coating-to-backing interaction','Coating thickness','Debris embossing']::text[],ARRAY['Confusing cupping, which is curl across the width, with dishing, which is sideways deformation of the whole reel pack','Assuming cupping is only a backing problem, when coating shrinkage often drives it','UNSAFE: Trying to flatten cupped tape with heat, which can warp or melt the base film']::text[],ARRAY['Assessing a tape that rides unevenly on the heads','Explaining fluctuating high-frequency output on an old reel','Linking cupping to a history of humidity swings in storage']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e5ca4715-e937-5f6c-b737-733a7ff6f874' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cupping'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e5ca4715-e937-5f6c-b737-733a7ff6f874','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e5ca4715-e937-5f6c-b737-733a7ff6f874' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4d033924-636c-5b8b-8cae-d176823688b1','Debris embossing','The formation of repeating impressions in wound tape when a hard particle, splice, or lump trapped in the pack presses into adjacent layers under winding pressure. The impressions recur at the circumference interval of the pack and cause periodic dropouts; even lumps only tens of micrometres high can emboss.','Tape is wound tightly in a roll. If a bit of grit or a bump is trapped inside, it presses on the layers touching it. This stamps a dent into the tape that repeats around the roll. Those dents make the sound or picture drop out.','The concept explains a class of repeating dropouts and warns why the tape path and pack must be kept clean and free of hard debris.','Seeing dropouts that recur at a regular spacing, a technician suspects debris embossing and inspects the pack for trapped particles or a raised splice.','Physical deformation',ARRAY['Dropout','Coating shed','Crease memory','Cupping','Dish']::text[],ARRAY['Mistaking regularly spaced embossing dropouts for a recording fault rather than physical damage','Winding dirty tape, trapping grit that then embosses the pack','UNSAFE: Blowing out debris by mouth or with unfiltered compressed air, spreading particles and oxide dust']::text[],ARRAY['Investigating dropouts that repeat every few tens of metres','Finding a grain of grit pressed into a tape pack','Keeping the tape path clean to prevent embossing during winding']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4d033924-636c-5b8b-8cae-d176823688b1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Debris embossing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
