WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4d033924-636c-5b8b-8cae-d176823688b1' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c79a0013-f9e2-5c03-9a64-28d630ff1c81','Desiccation treatment','A remediation in which a hydrolytically degraded (sticky-shed) tape is held in a controlled low-humidity, gently elevated-temperature environment to drive out absorbed moisture and temporarily reverse binder hydrolysis, restoring playability long enough to make a transfer. It is the basis of the well-known tape ''baking'' procedure.','Some old tapes go sticky because their binder soaked up water. Desiccation treatment dries that water back out with gentle warmth in a low-humidity oven. The tape then plays well enough for a short time. Archivists use that window to copy it at once. The fix is temporary, not permanent.','It temporarily restores a sticky tape to a playable state so its content can be transferred before the binder re-absorbs moisture and becomes unplayable again.','A technician incubates a squealing, shedding reel in a temperature-controlled scientific oven, then transfers it within days while it remains stable.','Remediation',ARRAY['Sticky-shed syndrome','Coating shed','Cohesive failure','Coating friability','Controlled unspooling']::text[],ARRAY['Expecting the fix to be permanent, when the tape re-absorbs moisture and must be transferred quickly','UNSAFE: Using a domestic kitchen oven or microwave, whose uneven or excessive heat can warp, melt, or ignite tape and release fumes; only a calibrated low-temperature scientific oven or incubator is acceptable','UNSAFE: Baking acetate-based tapes or tapes of unknown base, which do not benefit and can be damaged by heat']::text[],ARRAY['Preparing a sticky-shed reel for a one-time digital transfer','Stabilising a squealing tape that clogs heads','Scheduling a transfer immediately after treatment before re-deterioration']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c79a0013-f9e2-5c03-9a64-28d630ff1c81' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Desiccation treatment'),'[^a-z0-9]','','g'));
