INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b3dbb057-0948-53c3-9da0-31488f189b31','Dish','A deformation of the wound tape pack in which the reel of tape takes on a dished or conical shape, with windings displaced sideways relative to one another so the pack no longer forms a flat cylinder. It arises from uneven winding tension, pack slip, or improper storage, and can crease or damage tape edges.','A healthy tape roll is a flat, even cylinder. Dishing is when the roll sags to one side into a cone or dish shape. The layers have slipped sideways. This can bend or scrape the tape edges and make it hard to play.','The term identifies a pack-level fault that stresses tape edges and disrupts smooth playback, pointing to winding and storage problems.','A technician who finds a reel whose pack has slumped to a cone re-winds it at even tension before playback to avoid edge damage.','Physical deformation',ARRAY['Cupping','Crease memory','Controlled unspooling','Debris embossing','Coating-to-backing interaction']::text[],ARRAY['Confusing dish, a whole-pack deformation, with cupping, the curl across a single strand''s width','Storing reels flat on their sides, letting the pack slump and dish','Playing a badly dished pack without re-winding, risking edge damage']::text[],ARRAY['Finding a reel whose pack has slumped into a cone during storage','Re-winding a dished pack to even tension before transfer','Diagnosing edge damage traced to a dished tape']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b3dbb057-0948-53c3-9da0-31488f189b31' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dish'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b3dbb057-0948-53c3-9da0-31488f189b31','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b3dbb057-0948-53c3-9da0-31488f189b31' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '69efa6c3-9358-5665-bc1d-9c0de4c974da','Dispersion quality','How uniformly the magnetic pigment particles are distributed and de-agglomerated within the binder of the tape coating, established during manufacture. Good dispersion gives smooth, uniform output and low noise; poor dispersion leaves clumps that raise noise, cause dropouts, and reduce output.','The magnetic layer is tiny particles mixed into a binder. Good mixing spreads them out evenly. Poor mixing leaves clumps. Even spreading gives clean, steady sound. Clumps add hiss and cause drop-outs.','Dispersion quality determines a tape''s noise floor, output uniformity, and reliability, and reflects how well the coating was manufactured.','Comparing tape stocks, an engineer links a noisier, patchier transfer to poorer pigment dispersion in a lower-grade tape.','Tape construction',ARRAY['Coating thickness','Coating-to-backing interaction','Dropout','Double-play tape','Cohesive failure']::text[],ARRAY['Assuming all tape of the same format performs identically, ignoring dispersion differences between brands and grades','Blaming a noisy transfer on the machine when poor tape dispersion is the cause','Thinking dispersion can be improved after manufacture, when it is fixed as the tape is made']::text[],ARRAY['Explaining why one tape brand sounds noisier than another','Selecting higher-grade stock for a master recording','Assessing dropout-prone tape traced to pigment clumping']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='69efa6c3-9358-5665-bc1d-9c0de4c974da' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dispersion quality'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '69efa6c3-9358-5665-bc1d-9c0de4c974da','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='69efa6c3-9358-5665-bc1d-9c0de4c974da' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'de2c4101-36a0-57c5-bded-7f7b52c30858','Double-play tape','A magnetic tape manufactured with a thinner base film, and often a thinner coating, than standard-play tape, so that roughly twice the playing time fits on a reel of the same size. The reduced thickness makes it more prone to stretching, print-through, and mechanical damage, and less archivally robust.','Double-play tape is made thinner than normal tape. Being thinner, twice as much fits on the same size reel. But thin tape stretches, tears, and prints its signal onto the next layer more easily. So it is more fragile and harder to preserve.','It exists to extend recording time per reel, trading physical strength and archival stability for extra capacity.','Handling an old reel labelled long- or double-play, a technician winds and threads it gently, expecting a thin, stretch-prone tape with more print-through.','Tape construction',ARRAY['Coating thickness','Print-through','Dispersion quality','Cupping','Coating-to-backing interaction']::text[],ARRAY['Assuming reels of the same size hold the same length, when thinner double-play tape holds far more','Handling thin double-play tape at high tension, stretching or snapping it','Overlooking that thin tapes suffer more print-through between layers']::text[],ARRAY['Identifying an unusually long recording on a small reel','Handling fragile thin stock during a transfer','Explaining print-through echoes on a thin tape']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='de2c4101-36a0-57c5-bded-7f7b52c30858' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Double-play tape'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'de2c4101-36a0-57c5-bded-7f7b52c30858','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='de2c4101-36a0-57c5-bded-7f7b52c30858' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2da13f79-ca87-5f6c-89ad-1ac6e6f7c967','Dry cleaning','A conservation cleaning method that removes loose dust, debris and shed particles from magnetic tape without any liquid or solvent, typically by drawing the tape slowly across a soft, lint-free wiping material such as Pellon fleece mounted in the tape path, and by using a soft brush, low-suction vacuum and filtered compressed air. It is the gentlest first-stage treatment, applied before any wet or solvent cleaning is considered.','Dry cleaning wipes dust and loose bits off a tape with no liquid at all. The tape is pulled slowly past a soft, lint-free pad. A soft brush or gentle vacuum can help as well. It is the safest first step before trying anything wet.','It removes surface contaminants that would otherwise cause dropouts, clog heads and scratch the tape, while avoiding the extra risk that water or solvents pose to unknown or fragile tape formulations.','An archivist runs a shedding reel through a cleaning machine fitted with a lint-free wiping pad, or hand-cleans with a soft brush and low vacuum, to prepare the tape for inspection and transfer.','Cleaning & Restoration',ARRAY['Sticky-shed syndrome','Head clog','Dropout','Binder hydrolysis','Flat wind']::text[],ARRAY['Reaching for solvents or a wet clean first, when a gentle dry clean with brush, vacuum or lint-free wipe should always be tried before any liquid method.','UNSAFE: Dry-cleaning a mouldy tape at an open bench without respiratory protection, which spreads fungal spores; mould removal must be done in a fume hood or outdoors while wearing a properly rated respirator and gloves.','Using ordinary cloth, cotton wool or paper towel that sheds its own lint onto the tape instead of a proper lint-free wiping material.','Running a fragile or sticky tape across a cleaning blade or sharp burnishing edge, which shaves off the oxide and destroys the recording.']::text[],ARRAY['Preparing a dusty reel-to-reel tape from an arid-climate collection for transfer.','Removing shed oxide and loose debris from an old cassette before it is played.','First-stage treatment of an incoming tape before deciding whether baking or wet cleaning is needed.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2da13f79-ca87-5f6c-89ad-1ac6e6f7c967' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dry cleaning'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '2da13f79-ca87-5f6c-89ad-1ac6e6f7c967','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='2da13f79-ca87-5f6c-89ad-1ac6e6f7c967' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'dcf843f3-895d-5a4b-be5e-fc2cd14c87c7','Dynamic azimuth error','A time-varying deviation of the azimuth angle - the angle between the head gap and a line square to the tape''s direction of travel - so that the effective azimuth fluctuates moment to moment during playback rather than sitting at a fixed offset. It is usually caused by lateral tape weave, scrape flutter, tension changes, worn guides or damaged and curled edges, and it produces fluctuating high-frequency loss and, on stereo or multitrack tape, wandering phase between channels.','Azimuth is how squarely the play head lines up with the recorded track. A dynamic azimuth error means that alignment keeps drifting while the tape runs. So the treble level wavers and, in stereo, the channels drift out of step. Loose guides, weaving tape or worn edges usually cause it.','Naming this fault lets a technician separate a moving, transport-related alignment error from a fixed head misadjustment, because the two demand different fixes.','When a transfer shows treble that pumps up and down or stereo imaging that wanders, a technician checks tape guides, tension and edge condition instead of just resetting a static azimuth.','Replay Artifact',ARRAY['Azimuth','Edge weave','Scrape flutter','Flutter','Gap loss','Tracking error']::text[],ARRAY['Treating it like a static azimuth error and simply readjusting the head, which cannot correct an alignment that keeps changing as the tape moves.','Blaming the recording or the head when the real cause is a mechanical fault in the tape path or damaged edges.','Ignoring worn guides or an uneven pack that let the tape weave, so the fault returns on the next tape.']::text[],ARRAY['A stereo master transfers with the image drifting and phase cancellation coming and going.','High-frequency content on a longitudinal audio tape fades in and out during playback.','Diagnosing why a tape sounds dull only intermittently on an otherwise aligned machine.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='dcf843f3-895d-5a4b-be5e-fc2cd14c87c7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dynamic azimuth error'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'dcf843f3-895d-5a4b-be5e-fc2cd14c87c7','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='dcf843f3-895d-5a4b-be5e-fc2cd14c87c7' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b6c4d54c-3a78-532a-a9b1-14037989c446','Edge damage','Physical deformation or destruction of a tape''s longitudinal edge - nicks, tears, stretching, folding, cupping or curling - usually from contact with reel flanges, poorly aligned guides, careless handling, or storage in a stepped or flange-packed wind. Because most transports guide the tape by one edge, edge damage causes mistracking, level and azimuth fluctuations, and can render outer tracks unplayable.','Edge damage is harm to the thin outer edge of the tape, such as nicks, bends or curling. Machines steer the tape by its edge, so a damaged edge makes the tape wander off track. That causes dropouts and wobbling sound. Flanges, bad guides and rough handling are common causes.','The term flags a mechanical failure mode that directly degrades tracking, telling a technician the tape rather than the machine is the source and that the damage is often permanent.','On inspection a technician who spots curled or nicked edges copies the recording promptly, because a guided edge that is bent will mistrack and the damage tends to worsen with each pass.','Media Damage',ARRAY['Edge weave','Flange pack contact','Flange squeeze','Flat wind','Cinching','Popped strand']::text[],ARRAY['Continuing to play a tape with a badly nicked or bent edge, which lets the damage worsen and can spread debris through the transport.','Storing reels flat so the pack slumps against a flange, then blaming the machine when edges emerge scraped.','Assuming edge damage only affects the outer track, when a guided edge that is deformed throws the whole tape off track.']::text[],ARRAY['An open-reel tape stored flat shows scraped, curled edges where it settled against the flange.','A cassette mistracks after its tape edge was creased by a jammed transport.','Inspecting an incoming reel and finding popped strands with bent edges from a previous flange pack.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b6c4d54c-3a78-532a-a9b1-14037989c446' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Edge damage'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b6c4d54c-3a78-532a-a9b1-14037989c446','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b6c4d54c-3a78-532a-a9b1-14037989c446' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7c4ba5b0-83ef-53a4-a19c-e3d38cb84c0b','Edge weave','Lateral, side-to-side wandering of the tape as it travels through the transport, and, in manufacturing terms, the deviation of a slit tape edge from a straight reference line. It arises from imprecise slitting, damaged or curled edges, worn or misadjusted guides and uneven packs, and it produces dynamic tracking errors, level and azimuth fluctuations, and unstable stereo imaging.','Edge weave is the tape drifting side to side as it moves past the heads. It can come from tape that was cut unevenly, from bent edges, or from worn guides. Because the machine steers by the edge, weaving makes the tape wander off track. The sound level and treble then wobble.','The concept lets technicians name and diagnose lateral instability of the tape path, so a weaving tape can be traced to guides, edge condition or slitting rather than to other faults.','When playback level and high frequencies fluctuate rhythmically, a technician watches the tape at the guides for side-to-side motion and checks guide wear and edge condition.','Replay Artifact',ARRAY['Edge damage','Dynamic azimuth error','Tracking error','Flat wind','Tape guide','Flutter']::text[],ARRAY['Confusing edge weave, a side-to-side wander, with flutter, a speed variation; they have different causes and fixes.','Overlooking worn or dirty guides that let the tape weave, and instead repeatedly resetting the heads.','Playing a tape with weaving, damaged edges without first copying it, allowing the edges to degrade further.']::text[],ARRAY['Stereo imaging on a transfer drifts because the tape is weaving through worn guides.','A poorly slit batch of tape mistracks on machines that edge-guide.','Level pumping is traced to a tape wandering laterally at the head.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7c4ba5b0-83ef-53a4-a19c-e3d38cb84c0b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Edge weave'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '7c4ba5b0-83ef-53a4-a19c-e3d38cb84c0b','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7c4ba5b0-83ef-53a4-a19c-e3d38cb84c0b' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6c722f51-3a00-5590-9c49-24e89c1288db','Embrittlement','The loss of flexibility of a tape''s backing or binder so that it becomes stiff and brittle and cracks or breaks when bent or tensioned. In cellulose-acetate tapes it accompanies the vinegar syndrome, the hydrolysis of the acetate base that also shrinks the backing; in some binders and backings it results from chemical aging, and in all cases it makes the tape fragile to handle and play.','Embrittlement means the tape has lost its bend and turned brittle. A brittle tape can snap or crack when it is played or handled. In old acetate tapes it comes with a vinegar smell as the plastic breaks down. Cool, dry, steady storage slows it down.','The term identifies a stage of chemical aging that makes a tape mechanically fragile, warning handlers that the carrier may break during winding or playback and needs extra care or urgent copying.','Meeting a reel that smells of vinegar and feels stiff, a technician winds it onto a spool at low tension on a gentle transport and prioritizes transfer before it becomes unplayable.','Chemical Degradation',ARRAY['Vinegar syndrome','Binder hydrolysis','Cellulose acetate','Sticky-shed syndrome','Environmental acclimatization']::text[],ARRAY['UNSAFE: Force-winding or sharply bending a brittle tape, which can snap it and fling sharp fragments; handle at low tension and support the pack.','Storing embrittled acetate tape warm and humid, which speeds the vinegar reaction that drives further embrittlement.','Assuming a brittle tape will loosen up if played, when playing it risks breakage and loss.']::text[],ARRAY['An early acetate reel is stiff, smells of vinegar and cracks at the leader.','Deciding storage priority for tapes showing early embrittlement.','Choosing a low-tension transport to transfer a fragile, aging tape.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6c722f51-3a00-5590-9c49-24e89c1288db' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Embrittlement'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6c722f51-3a00-5590-9c49-24e89c1288db','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6c722f51-3a00-5590-9c49-24e89c1288db' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a8d5a1f3-b6ef-53dc-ad4a-f4476e142834','Environmental acclimatization','The controlled process of letting a tape removed from cold or dry archival storage equilibrate to the temperature and humidity of the playback environment before it is handled or played, so that pack stresses equalize and moisture-related dimensional changes settle. Required time grows with tape width and with the size of the temperature or humidity change; roughly, a tape twice as wide takes about four times as long.','Cold, dry storage keeps tapes safe, but a tape must adjust before you play it. Acclimatization is that waiting time in the playback room. It lets the tape settle so it does not sweat moisture or run under stress. Wider tapes need much longer to adjust.','It exists to prevent the condensation, tracking errors and pack distortion that occur when a cold or dry tape is played before it has reached the operating room''s temperature and humidity.','Before transferring a reel pulled from a cold vault, a technician leaves it sealed or in an intermediate space for the recommended hours to a day so it reaches room conditions without condensation.','Handling & Storage',ARRAY['Archival storage','Relative humidity','Tape pack','Flat wind','Embrittlement','Cold-storage acclimation']::text[],ARRAY['Playing a tape straight from cold storage, so moisture condenses on the cold surface and the pack runs under stress.','Allowing the same short wait for a wide reel as for a cassette, when wide tape needs far longer to equilibrate.','Unsealing a cold tape at once in a warm, humid room instead of letting it warm up first to avoid condensation.']::text[],ARRAY['Retrieving a wide video master from a cold vault for a scheduled transfer.','Setting a workflow rule for how long vault tapes rest before playback.','Preventing condensation when moving tapes from a cold store to a warm studio.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a8d5a1f3-b6ef-53dc-ad4a-f4476e142834' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Environmental acclimatization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a8d5a1f3-b6ef-53dc-ad4a-f4476e142834','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a8d5a1f3-b6ef-53dc-ad4a-f4476e142834' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a72454ac-ff4f-5d75-aac0-ea028e16ec0e','Flange pack contact','A tape-pack condition in which the wound tape presses against or rubs on a reel flange instead of riding free between the flanges - caused by a loose or stepped wind, flat storage that lets the pack slump sideways, a misaligned recorder, or a bent or deflected flange. The tape edge scrapes the flange as it winds and unwinds, producing edge damage.','On a good reel the tape pack sits between the side walls without touching them. Flange pack contact means the wound tape is rubbing on a flange. That happens with a sloppy wind, flat storage or a bent flange. The tape edge gets scraped and damaged each time it runs.','Naming the condition helps a technician trace edge damage to its mechanical source and correct the wind, storage orientation or reel before the tape is played again.','Seeing a pack shoved against one flange, a technician rewinds the tape into an even pack, stores the reel upright on its hub and replaces any bent flange before transfer.','Tape Pack Condition',ARRAY['Flange squeeze','Flat wind','Edge damage','Pack slip','Popped strand','Cinching']::text[],ARRAY['Storing reels flat instead of upright on the hub, letting the pack sag against a flange.','Playing a flange-packed tape without rewinding it first, so the scraping edge damage continues.','Reusing reels with bent or deflected flanges that press on the tape.']::text[],ARRAY['A loosely wound reel stored flat has slumped against its lower flange.','Edge scrapes appear after a misaligned deck wound tape hard against a flange.','Inspecting reels for flange contact before a digitization batch.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a72454ac-ff4f-5d75-aac0-ea028e16ec0e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Flange pack contact'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a72454ac-ff4f-5d75-aac0-ea028e16ec0e','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a72454ac-ff4f-5d75-aac0-ea028e16ec0e' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '723e092e-2658-57c4-91b5-2e7dca6aa0f0','Flange squeeze','Compression of a tape pack''s edges between the two reel flanges - because the flanges are bowed inward, are deflected by supporting the reel by its flanges rather than its hub, or because the pack was wound off-centre toward one flange - pinching the tape edges and causing curling, cupping and edge damage.','Flange squeeze is when the two side walls of the reel press in on the edges of the tape pack. It happens if the flanges are bent inward. It also happens when the reel is held by its side walls, not its centre hub. The pinched edges curl and get damaged. Holding the reel by the hub avoids it.','The term identifies a way reels themselves damage tape edges, guiding handlers to support reels by the hub and to centre the wind so the pack never bears against a flange.','A technician lifts and shelves reels by the hub and adjusts guides so packs wind centred, keeping the flanges from squeezing and curling the tape edges.','Tape Pack Condition',ARRAY['Flange pack contact','Edge damage','Flat wind','Tape pack','Popped strand']::text[],ARRAY['Grabbing or supporting a reel by its flanges, which deflects them inward and squeezes the tape edges.','Winding the pack off-centre toward one flange so it is pinched during storage.','Keeping warped reels in service instead of replacing them with true, flat-flanged ones.']::text[],ARRAY['A reel carried by its flanges shows curled edges from the squeezed pack.','Setting guide alignment so packs wind centred on the hub.','Culling warped reels whose flanges bow into the tape.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='723e092e-2658-57c4-91b5-2e7dca6aa0f0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Flange squeeze'),'[^a-z0-9]','','g'));
