INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '80658e57-478f-5ca3-a557-03340145d1ad','Flat wind','A smooth, even tape pack in which every wrap lies flush with its neighbours, so the pack faces and the tape edges are flat and level with no stepped, protruding or dished layers. A flat wind is produced by winding the tape completely through in one continuous pass at an even library speed and tension, and it is the storage condition that best protects the tape from edge and pack damage.','A flat wind is a tape pack wound smooth and even, with no steps or bumps sticking out. You get it by running the tape all the way through at a steady speed. A flat, even pack keeps the edges safe in storage. A stepped or lumpy wind curls and damages the tape.','It is the target condition for storing tape, because an even pack spreads stress uniformly and keeps edges flush, preventing the curling, popped strands and deformation that uneven winds cause.','Before shelving a tape, a technician winds it end to end at library speed so it stores as a flat, even pack rather than the stepped one left by stop-start play.','Tape Pack Condition',ARRAY['Tape pack','Flange pack contact','Edge damage','Popped strand','Cinching']::text[],ARRAY['Storing a tape as played, stopped part-way, which leaves a step in the pack that deforms the tape.','Fast-winding roughly so the pack ends up uneven with popped strands.','Storing reels flat rather than upright, letting an otherwise flat pack slump.']::text[],ARRAY['Winding a reel fully through at even tension before returning it to the shelf.','Correcting a stepped pack left by a mid-tape stop.','Preparing tapes for long-term archival storage in even packs.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='80658e57-478f-5ca3-a557-03340145d1ad' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Flat wind'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '80658e57-478f-5ca3-a557-03340145d1ad','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='80658e57-478f-5ca3-a557-03340145d1ad' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a23fbb81-be2e-5600-a821-330ee4a69644','Flutter','Rapid, short-term variations in the speed of a tape as it passes the heads - conventionally the faster fluctuations, roughly above 10 hertz, as distinct from wow, the slower variations - caused by transport irregularities such as capstan or pinch-roller eccentricity, tension changes, guide friction or scrape flutter. It is heard as a warble, roughness or unsteady pitch and is measured as a weighted percentage under standards such as IEC 60386.','Flutter is fast, small changes in how quickly the tape moves past the heads. It makes the sound warble or seem rough and unsteady. Worn or dirty capstans, pinch rollers and guides usually cause it. Slower speed changes are called wow instead.','It names and quantifies short-term speed instability, so technicians can specify transport quality, judge a recording''s fidelity and trace pitch warble to a mechanical fault in the tape path.','Hearing a warble on playback, a technician cleans and checks the capstan, pinch roller and guides, and may measure wow and flutter with a test tape to confirm the transport is within spec.','Replay Artifact',ARRAY['Wow','Scrape flutter','Dynamic azimuth error','Capstan','Pinch roller','Tape speed']::text[],ARRAY['Confusing flutter, a fast speed variation, with wow, a slow speed variation; they point to different transport problems.','Overlooking a dirty or hardened pinch roller and capstan, a common source of flutter.','Blaming the tape for warble when the deck''s transport needs cleaning or servicing.']::text[],ARRAY['A transferred music tape has a warbling, unstable pitch.','Measuring wow and flutter with a test tape during machine calibration.','Diagnosing roughness traced to a worn pinch roller.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a23fbb81-be2e-5600-a821-330ee4a69644' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Flutter'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a23fbb81-be2e-5600-a821-330ee4a69644','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a23fbb81-be2e-5600-a821-330ee4a69644' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7e53046c-11d5-5456-9343-8f16124a1907','Fringing effect','A low-frequency boost, with associated response ripple, that occurs on playback when the reproduce head picks up magnetic flux from parts of the recorded track lying outside the head''s own track width - for example when the reproduce head is narrower than or misaligned with the recorded track. Because long wavelengths spread their flux farther, this extra fringe flux raises long-wavelength (low-frequency) output and must be allowed for when calibrating with standard tapes.','A play head normally reads only the strip of tape right in front of its gap. At low pitches the magnetic field spreads out wider than the head. The head then also picks up signal from the track beside it. That extra pickup lifts the low frequencies. Engineers call this the fringing effect.','Understanding it lets engineers correct low-frequency measurement errors, especially when a narrow reproduce head reads a wider recorded track or a full-track calibration tape, so response is judged accurately.','When aligning a machine to a full-track calibration tape with a narrower playback head, a technician allows for fringing, which otherwise reads the low frequencies as artificially high.','Reproduction Effect',ARRAY['Gap loss','Azimuth','Track width','Reproduce head','Calibration tape']::text[],ARRAY['Reading the raised low-frequency output from a full-track calibration tape as the machine''s true response, ignoring fringing.','Assuming the reproduce head only ever picks up the track directly under its gap.','Confusing fringing, a low-frequency pickup effect, with gap loss, a high-frequency reproduction loss.']::text[],ARRAY['Calibrating a two-track machine against a full-track reference tape.','Explaining an unexpected bass rise when a narrow head plays a wide recorded track.','Setting low-frequency reproduce levels during machine alignment.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7e53046c-11d5-5456-9343-8f16124a1907' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Fringing effect'),'[^a-z0-9]','','g'));
