SELECT '7e53046c-11d5-5456-9343-8f16124a1907','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7e53046c-11d5-5456-9343-8f16124a1907' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e116aad6-8117-5ca7-9a35-cce815a9ce15','Gap loss','The progressive loss of reproduced output as the recorded wavelength approaches the effective reproduce head-gap length, reaching a null when the wavelength equals the gap length and again at integer submultiples of it (lambda = g/2, g/3, ...), i.e. wherever the gap length spans a whole number of wavelengths. Because higher frequencies correspond to shorter wavelengths at a given tape speed, gap loss sets the high-frequency limit of a reproduce head and rises steeply as the wavelength shortens.','A play head reads the tape through a tiny slit called the gap. The recorded wave can get as short as that gap. Then the head can no longer read it. The output drops to nothing. So the gap sets how high a pitch the head can play back. Higher pitches make shorter waves, so they fade first. A narrower gap reads higher pitches.','It explains and bounds a reproduce head''s high-frequency response, so designers choose a gap length for the wanted bandwidth and technicians understand why treble falls off at short wavelengths.','Choosing or judging a playback head, a technician relates its gap length and the tape speed to the highest frequency it can reproduce, and runs faster speeds to extend high-frequency response.','Reproduction Effect',ARRAY['Fringing effect','Wavelength','Reproduce head','Head gap','Spacing loss','Tape speed']::text[],ARRAY['Confusing reproduce gap loss on playback with the much smaller record gap; the reproduce gap sets the high-frequency limit.','Trying to fix short-wavelength dullness with equalization alone when the wavelength has reached the gap-loss null and no signal remains.','Forgetting that lower tape speed shortens the wavelength for a given frequency, worsening gap loss.']::text[],ARRAY['Explaining why a worn head with a widened gap loses treble.','Choosing a higher tape speed to capture more high-frequency detail.','Setting expectations for the bandwidth of a given playback head and speed.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e116aad6-8117-5ca7-9a35-cce815a9ce15' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Gap loss'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e116aad6-8117-5ca7-9a35-cce815a9ce15','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
