INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f235aa2b-f392-5fe5-a2ae-64dd38f5a174','Guard-band intrusion','The condition in which a replay head''s active gap, instead of staying within its intended track, extends into the guard band separating tracks (or into a neighbouring track), because of head-height or track-registration error, record/replay format mismatch, or lateral tape motion. The result is reduced level on the wanted track together with crosstalk picked up from the adjacent one.','Tracks on tape are kept apart by thin blank strips called guard bands. Guard-band intrusion is when the playback head drifts off its track. It then reads into that blank strip or the next track. This makes the sound weaker and lets a nearby track bleed in.','The term names a specific track-registration failure so technicians can diagnose why a replay shows level loss and crosstalk together, and trace it to head height, format mismatch or tape weave rather than to the recording itself.','When a transfer shows one channel bleeding faintly into another and losing level, a technician checks head height and track format, adjusting alignment so each gap sits centred on its recorded track.','Head Alignment',ARRAY['Guard band','Head-height error','Adjacent-track crosstalk','Track format','Azimuth error','Fringing effect']::text[],ARRAY['Blaming faint crosstalk on the recording or a bad head when the real cause is a head-height or track-registration error.','Playing a tape on a head whose track width or format does not match the recording, so the gap straddles the guard band.']::text[],ARRAY['Transferring a half-track tape on a machine set up for a different track format, causing level loss and bleed.','Diagnosing a multitrack master where one channel carries a faint copy of its neighbour after head service.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f235aa2b-f392-5fe5-a2ae-64dd38f5a174' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Guard-band intrusion'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'f235aa2b-f392-5fe5-a2ae-64dd38f5a174','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f235aa2b-f392-5fe5-a2ae-64dd38f5a174' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '813be5f3-0d92-5f05-a121-64d2390d4200','Hard pack','A tape pack that has been wound, or has become over time, excessively tight, producing high radial and interlayer pressure within the roll. The elevated pressure stresses the backing and layers and promotes deformation, print-through, and, on subsequent play, cinching or popped strands.','A hard pack is a roll of tape wound far too tightly. The tight winding squeezes the layers together very hard. That pressure can warp the tape and print a faint echo. It can also make the tape jam or slip when you play it.','Naming this pack condition lets an archive flag a roll whose winding pressure is a preservation risk, so it can be re-wound at controlled tension before the pressure causes lasting deformation.','On inspection a technician who finds an unusually rigid, tightly wound reel plays it through once at proper tension to re-tension the pack, watching for cinching and print-through.','Tape Pack Defects',ARRAY['Cinching','Print-through','Interlayer slip','Windowing','Hub slip','Layer impression']::text[],ARRAY['Assuming a very tight, firm pack is a sign of good winding, when excessive tightness stresses and deforms the tape.','Fast-winding a hard-packed tape at high tension, which worsens the internal pressure instead of relieving it.']::text[],ARRAY['Assessing an old master wound tightly on a small hub that shows print-through echoes on playback.','Deciding whether an archival reel needs a controlled re-wind before digitisation.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='813be5f3-0d92-5f05-a121-64d2390d4200' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Hard pack'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '813be5f3-0d92-5f05-a121-64d2390d4200','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='813be5f3-0d92-5f05-a121-64d2390d4200' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'aa4fa6aa-ec8b-5467-8339-5e3c74c5a577','Head-gap scatter','The deviation of the individual track gaps in a multitrack head from perfect alignment along a single line perpendicular to tape travel, so the gaps are staggered fore-and-aft rather than coplanar. Because some channels'' gaps sit slightly ahead of others along the tape, it introduces a fixed interchannel time (phase) displacement between tracks.','A multitrack head has one tiny gap for each track. Ideally all the gaps line up in one straight row. Head-gap scatter means some gaps sit a little ahead of others. This makes some tracks play a hair early, throwing the channels out of time.','The concept explains a source of fixed interchannel timing error that is built into the head itself, distinct from azimuth or speed faults, helping technicians know which errors alignment can fix and which are inherent to the head.','When channels of a multitrack transfer will not phase-align even after azimuth adjustment, a technician suspects gap scatter and time-aligns the channels in software during the transfer.','Head Alignment',ARRAY['Interchannel time displacement','Azimuth error','Head-height error','Phase error','Head alignment']::text[],ARRAY['Trying to remove a fixed interchannel timing offset with azimuth adjustment alone, when the cause is gap scatter in the head.','Assuming every multitrack head has perfectly coplanar gaps and ignoring small built-in timing offsets between channels.']::text[],ARRAY['Aligning a multitrack machine where two channels stay slightly out of phase after azimuth is optimised.','Choosing a replay head for a stereo transfer where tight interchannel timing matters.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='aa4fa6aa-ec8b-5467-8339-5e3c74c5a577' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Head-gap scatter'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'aa4fa6aa-ec8b-5467-8339-5e3c74c5a577','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='aa4fa6aa-ec8b-5467-8339-5e3c74c5a577' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6d02a6aa-f072-5b26-845d-f90f5f9b08ac','Head-height error','A tape-head alignment fault in which the head sits too high or too low relative to the width of the tape, so its track gaps do not register vertically with the recorded track positions. It causes reduced replay level, mistracking, guard-band intrusion, and crosstalk from adjacent tracks.','The head must sit at the right height across the tape''s width. Head-height error means it sits too high or too low. Then its gaps no longer line up with the recorded tracks. The sound gets weaker and picks up bleed from the next track.','Head height is one of the standard head-alignment parameters; naming its error lets a technician correct vertical head position so each gap reads its full intended track for maximum level and separation.','During machine set-up a technician adjusts head height while watching output level and crosstalk, setting it so a test tone reads at full level with minimum bleed between tracks.','Head Alignment',ARRAY['Azimuth error','Guard-band intrusion','Head-to-tape contact','Adjacent-track crosstalk','Head alignment']::text[],ARRAY['Adjusting only azimuth and neglecting head height, leaving the gaps reading partly off the recorded tracks.','Mistaking the level loss and crosstalk of a height error for worn heads or a degraded tape.']::text[],ARRAY['Setting up a reel-to-reel machine before an archival transfer, using a calibration tape to check level and separation.','Diagnosing weak, crosstalk-laden playback traced to a head shifted vertically after servicing.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6d02a6aa-f072-5b26-845d-f90f5f9b08ac' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Head-height error'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6d02a6aa-f072-5b26-845d-f90f5f9b08ac','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6d02a6aa-f072-5b26-845d-f90f5f9b08ac' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e975075e-9e88-56cc-bc52-2766053cb890','Head-to-tape contact','The degree of intimate physical contact between the tape''s magnetic surface and the replay head at the gap. Because reproduced level falls off very rapidly with even slight head-to-tape separation (spacing loss), close, uniform contact—maintained by correct wrap, tension, tape flatness and clean surfaces—is essential for high-frequency response and for avoiding dropouts.','The tape''s coating must press firmly against the head to be read. This closeness is called head-to-tape contact. Even a tiny gap makes the high notes fade fast. Dirt, a curled tape, or the wrong tension can spoil the contact.','Good head-to-tape contact exists to keep the recorded magnetism close enough to the gap to be reproduced fully; without it the shortest wavelengths, which carry high frequencies, are lost first.','A technician cleans the heads and tape path, checks tension and wrap, and flattens cupped tape so the coating stays pressed to the head and high frequencies and level hold steady through a transfer.','Head Alignment',ARRAY['Head-wrap angle','Spacing loss','Dropout','Cupping','Contour effect','Head-height error']::text[],ARRAY['Chasing high-frequency loss with equalisation when the real cause is poor head-to-tape contact from dirt or a curled tape.','UNSAFE: Using solvents or abrasives not specified by the machine''s service manual to clean heads and path, which can damage heads and lift tape coating.']::text[],ARRAY['Transferring a cupped or debris-laden tape that keeps dropping high frequencies until contact is restored.','Routine head and path cleaning before a critical archival transfer to preserve response.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e975075e-9e88-56cc-bc52-2766053cb890' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Head-to-tape contact'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e975075e-9e88-56cc-bc52-2766053cb890','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e975075e-9e88-56cc-bc52-2766053cb890' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e9c549e5-0cf2-5423-ac72-0f275f00228f','Head-wrap angle','The angular extent of the arc over which the tape is bent around and pressed against the head face, set by head penetration into the tape path and by adjacent guide geometry. It governs the contact pressure and contact area at the gap, and hence the intimacy of head-to-tape contact and the high-frequency response.','As tape passes the head, it bends around the head''s face. The size of that bend is the head-wrap angle. It sets how hard and how widely the tape presses on the head. The right wrap keeps firm contact so high notes come through.','Wrap angle exists as an alignment and design parameter that sets contact pressure at the gap: enough wrap gives firm contact for good response, while too much adds friction and wear.','When high frequencies drop or the tape rides unevenly, a technician checks head penetration and guide height to restore the intended wrap around the head.','Head Alignment',ARRAY['Head-to-tape contact','Spacing loss','Head alignment','Tape guide','Head-height error']::text[],ARRAY['Increasing head penetration to force more wrap, which raises friction and accelerates head and tape wear.','Overlooking a misadjusted guide that has reduced wrap and weakened head-to-tape contact.']::text[],ARRAY['Restoring a serviced transport where a moved guide changed the tape''s wrap around the head.','Setting up an unfamiliar machine so the tape contacts each head with correct wrap before transfer.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e9c549e5-0cf2-5423-ac72-0f275f00228f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Head-wrap angle'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
