WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e9c549e5-0cf2-5423-ac72-0f275f00228f' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ae9c6647-a0ed-52b5-a4c7-4d4d4bd29cc9','Hub slip','A winding fault in which the tape pack slips rotationally against the reel hub rather than being firmly anchored to it, so the innermost turns move independently of the hub. The resulting loss of tension control produces uneven winding, cinching and pack distortion, especially during starts, stops and shuttling.','A reel''s tape is wound around a centre called the hub. Hub slip is when the tape roll slides around the hub instead of gripping it. The winding then loses its grip and its even tension. This can crease the tape or leave loose, tangled coils.','Recognising hub slip helps a technician explain sudden tension losses and cinching, and points to securing or replacing the hub-to-tape anchoring before further handling.','If a reel jerks or forms loose loops when starting and stopping, a technician checks that the tape end is properly secured to the hub and winds gently at controlled tension.','Tape Pack Defects',ARRAY['Hub support','Cinching','Interlayer slip','Hard pack','Windowing','Reel hub']::text[],ARRAY['Using sharp start-stop and shuttle moves on a loosely anchored pack, which lets the pack slip and cinch.','Assuming the loose innermost turns are harmless rather than a sign the pack is not gripping the hub.']::text[],ARRAY['Handling an archival reel whose tape end is no longer firmly fixed to the hub.','Investigating creasing that appears each time a transport starts or stops a particular reel.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ae9c6647-a0ed-52b5-a4c7-4d4d4bd29cc9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Hub slip'),'[^a-z0-9]','','g'));
