SELECT 'ae9c6647-a0ed-52b5-a4c7-4d4d4bd29cc9','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ae9c6647-a0ed-52b5-a4c7-4d4d4bd29cc9' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '44b612f4-9fc5-51d5-a4c5-3a3cd59417bf','Hub support','Support of a tape roll at its centre hub so that the mass of the wound pack is carried through the hub rather than by the tape edges or the reel flanges. Proper hub support—storing reels upright on precision hubs or winding onto cores that grip the centre—prevents pack slump, edge damage and flange-contact deformation.','A tape roll should rest on its centre hub, not on its edges. Hub support means the hub carries the weight of the roll. Stored this way, the tape edges stay flat and safe. Without it, the roll can sag and the edges can bend or crush.','Hub support exists to keep the pack''s weight off the delicate tape edges and flanges during storage, protecting edge tracks and pack shape over long-term storage.','An archivist stores reels vertically on sound hubs or rehouses tape onto proper cores, avoiding stacking reels flat where the pack settles on its edges.','Tape Handling',ARRAY['Hub slip','Flange pack contact','Edge damage','Reel hub','Vertical storage']::text[],ARRAY['Stacking reels flat so the tape pack rests and slumps on its own edges.','UNSAFE: Squeezing the reel flanges together to carry a reel, which crushes the tape pack in between.','Winding archival tape onto a hub or core too small or damaged to support the pack centrally.']::text[],ARRAY['Shelving a collection of open-reel tapes upright to keep weight on the hubs.','Rehousing a warped reel onto a new precision hub before storage.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='44b612f4-9fc5-51d5-a4c5-3a3cd59417bf' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Hub support'),'[^a-z0-9]','','g'));
