SELECT '44b612f4-9fc5-51d5-a4c5-3a3cd59417bf','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='44b612f4-9fc5-51d5-a4c5-3a3cd59417bf' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '501292b5-f1bf-5666-a283-458bbf718783','Hyphal anchoring','The process by which the thread-like filaments (hyphae) of a fungal (mould) colony grow into and grip the surface of a magnetic tape, embedding in the binder and backcoat. This anchoring binds the mould firmly to the carrier, so that removing it can lift or abrade the coating, and it marks active biodeterioration of the tape.','Mould grows as tiny threads called hyphae. Hyphal anchoring is when those threads grip into the tape''s surface. This holds the mould on tightly and shows it is growing. Pulling it off can rip away the coating, so it must be handled with care and protection.','The term describes how mould physically attaches to tape, which matters because anchored growth both signals active decay and makes cleaning risky, guiding when to isolate an item and seek conservation help.','On finding fuzzy or web-like growth gripping a tape, a technician isolates the reel, wears protection, and refers it for controlled cleaning rather than trying to wipe or play it.','Biological Contamination',ARRAY['Mould growth','Biodeterioration','Binder','Dry cleaning','Insect frass contamination','Quarantine']::text[],ARRAY['UNSAFE: Handling or cleaning mouldy tape without a properly fitted respirator (such as an N95 or higher), nitrile gloves and adequate ventilation or containment, exposing the worker to harmful spores.','UNSAFE: Using compressed air on mouldy tape, which aerosolises spores and spreads contamination.','Playing anchored, mouldy tape on a transport, which contaminates the machine and can strip the softened coating.','Wiping off anchored growth dry, which tears coating away with it instead of removing mould safely.']::text[],ARRAY['Surveying tapes recovered from a damp store where colonies have gripped the reels.','Deciding whether a mould-affected reel needs specialist cleaning before any playback attempt.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='501292b5-f1bf-5666-a283-458bbf718783' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Hyphal anchoring'),'[^a-z0-9]','','g'));
