SELECT '501292b5-f1bf-5666-a283-458bbf718783','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='501292b5-f1bf-5666-a283-458bbf718783' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1f8d1cc5-c848-52fc-99f3-a38d33b0048c','Insect frass contamination','Contamination of tape or its housing by frass—the excrement and refuse debris left by insects. Its presence signals pest activity in the collection; the deposits are abrasive and chemically active, can stain and abrade the tape surface during handling or replay, and can attract or support mould growth.','Frass is the droppings and debris left behind by insects. Finding it on tape means pests have been active nearby. The debris is gritty and can scratch or stain the tape. It can also draw in mould, so it must be cleaned up safely.','Identifying frass alerts an archive to an active pest problem and to a contaminant that can damage tape, prompting isolation of affected items and an integrated pest-management response.','When a technician finds gritty droppings in a tape box, the item is isolated, the debris is removed under controlled conditions before any play, and the storage area is checked for pests.','Biological Contamination',ARRAY['Integrated pest management','Mould growth','Hyphal anchoring','Abrasive contamination','Quarantine','Rehousing']::text[],ARRAY['UNSAFE: Handling frass-contaminated material without gloves and, where dust is disturbed, respiratory protection, ignoring the biological hazard of droppings.','Playing a tape still carrying gritty frass, which abrades both the tape and the heads.','Treating frass as harmless dust rather than as evidence of an active pest infestation needing response.']::text[],ARRAY['Inspecting boxes from a long-stored collection and finding insect droppings among the reels.','Triggering an integrated pest-management review after frass is found on several housings.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1f8d1cc5-c848-52fc-99f3-a38d33b0048c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Insect frass contamination'),'[^a-z0-9]','','g'));
