SELECT '1f8d1cc5-c848-52fc-99f3-a38d33b0048c','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1f8d1cc5-c848-52fc-99f3-a38d33b0048c' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd5de96ea-1762-5d0a-af4a-72439e58ff37','Interchannel time displacement','A timing offset between the reproduced signals of two or more tracks of a multichannel tape, in which one channel''s signal arrives earlier or later than another. It arises chiefly from gap scatter and azimuth error—longitudinal misalignment of the track gaps along the tape—and degrades stereo imaging, phase coherence and mono compatibility.','A stereo or multitrack tape holds several channels side by side. They should all play at the exact same moment. Interchannel time displacement means one channel plays slightly early or late. This blurs the stereo image and weakens the sound when mixed to mono.','The term captures a phase-related fault between channels so technicians can distinguish it from level or speed problems and correct it by realigning the head or time-aligning channels.','When a stereo transfer sounds hollow or collapses in mono, a technician adjusts azimuth and, if a fixed offset remains from gap scatter, time-aligns the channels in the workstation.','Speed & Timing',ARRAY['Head-gap scatter','Azimuth error','Phase error','Head alignment','Stereo image']::text[],ARRAY['Ignoring mono compatibility, so a channel timing offset only surfaces when the mix is summed to mono.','Assuming azimuth alone removes all interchannel timing error when part of it comes from fixed gap scatter.']::text[],ARRAY['Transferring a stereo master that sounds phasey and loses centre content in mono.','Aligning a multitrack machine so channels stay time-coherent across a transfer.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d5de96ea-1762-5d0a-af4a-72439e58ff37' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Interchannel time displacement'),'[^a-z0-9]','','g'));
