SELECT 'd5de96ea-1762-5d0a-af4a-72439e58ff37','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d5de96ea-1762-5d0a-af4a-72439e58ff37' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8e0e4093-3295-5adb-805e-f7f838b72b2d','Interlayer entrainment','The drawing-in and trapping of a thin film of air (and any airborne dust) between successive turns of tape as the pack is wound. The amount of entrained air, which increases with winding speed, governs interlayer friction and pack tightness: excess air yields a loose, slip-prone pack, while too little yields an over-tight hard pack.','When tape winds up fast, it drags in a thin film of air between the layers. This trapped air is called interlayer entrainment. A little air is fine, but too much makes the roll loose and slippery. Too little makes the roll pack too tight.','Understanding air entrainment explains why winding speed and tension change how tight and stable a pack is, guiding technicians to wind archival tape at speeds and tensions that give a firm but not hard pack.','To produce a stable archival wind, a technician avoids very high-speed winding that entrains too much air and leaves a loose, slip-prone pack.','Tape Pack Defects',ARRAY['Interlayer slip','Hard pack','Hub slip','Cinching','Winding tension','Back coating']::text[],ARRAY['Fast-winding archival tape for storage, which entrains air and leaves a loose pack prone to slipping and cinching.','Assuming winding tension alone sets pack tightness while ignoring the air drawn in at speed.']::text[],ARRAY['Preparing a final storage wind and choosing a slow, even wind for a stable pack.','Diagnosing why a fast-wound reel formed a loose, unstable pack that cinches on play.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8e0e4093-3295-5adb-805e-f7f838b72b2d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Interlayer entrainment'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '8e0e4093-3295-5adb-805e-f7f838b72b2d','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8e0e4093-3295-5adb-805e-f7f838b72b2d' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '39b66460-41ae-5eb8-9f08-38da0de98251','Interlayer slip','Relative movement between adjacent turns of tape within a wound pack, occurring when interlayer friction is too low to hold the layers in place. Under handling, shock or uneven tension, turns shift against one another, producing cinching, popped strands, pack slip and lateral (edge) misalignment.','In a tape roll the coils should stay put against each other. Interlayer slip is when nearby coils slide against one another. A bump or drop can then shift the coils out of place. This causes creases, loose loops, and edges that no longer line up.','Naming this failure lets a technician link cinching, popped strands and edge stagger to low interlayer friction, and to handle and wind tape so layers stay locked together.','To prevent slip, a technician winds at even tension and avoids dropping or jarring reels, since a shock to a loosely held pack lets the layers shift and cinch.','Tape Pack Defects',ARRAY['Cinching','Interlayer entrainment','Hub slip','Hard pack','Windowing','Edge damage']::text[],ARRAY['Jarring or dropping a reel with a loosely wound pack, letting the layers slip and cinch.','Winding at too low or uneven tension, leaving a pack whose layers slide out of place when handled.']::text[],ARRAY['Handling a poorly wound reel that cinches and pops strands when moved.','Choosing wind tension for archival storage to keep pack layers from shifting.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='39b66460-41ae-5eb8-9f08-38da0de98251' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Interlayer slip'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '39b66460-41ae-5eb8-9f08-38da0de98251','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='39b66460-41ae-5eb8-9f08-38da0de98251' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '77666031-d6a3-5d5c-b992-27f4b57ac63d','Layer adhesion','The sticking together of adjacent turns of tape within a wound pack, so that layers adhere rather than separating freely on unwinding—a condition also called blocking. It results from binder hydrolysis, exuded plasticizer or backcoat transfer combined with heat, humidity and pack pressure, and can strip coating from the tape when the stuck layers are forced apart.','Over time the coils in a tape roll can stick together. This sticking is called layer adhesion, or blocking. Heat, damp air, and a breaking-down coating make it worse. Forcing the stuck coils apart can peel the coating off the tape.','The term identifies a chemical-plus-mechanical failure of the pack so technicians know it must not be forced apart, and can choose conditioning or specialist treatment before any unwinding.','Meeting a reel whose layers cling and resist unwinding, a technician stops, assesses for binder degradation, and treats or conditions the tape rather than pulling the layers apart.','Tape Pack Defects',ARRAY['Blocking','Binder hydrolysis','Sticky shed syndrome','Back-coat transfer','Interlayer slip','Coating delamination']::text[],ARRAY['Forcing stuck layers apart on a transport, which tears coating from the base.','UNSAFE: Baking or incubating a degraded tape at an unverified temperature to relieve sticking, which can permanently damage or destroy the recording; use only documented, media-appropriate treatment parameters.','Storing tape warm and damp, the conditions that promote binder breakdown and layer sticking.']::text[],ARRAY['Encountering a tape that squeals and clings as its degraded layers resist separation.','Deciding whether a blocked reel needs conditioning before it can be safely unwound and transferred.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='77666031-d6a3-5d5c-b992-27f4b57ac63d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Layer adhesion'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '77666031-d6a3-5d5c-b992-27f4b57ac63d','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='77666031-d6a3-5d5c-b992-27f4b57ac63d' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4f255673-d24a-5a3e-a6eb-187694cf9610','Layer impression','A physical imprint or deformation transferred from one turn of tape onto the adjacent turn within the pack, formed when pack pressure presses debris, splices, edges or surface irregularities of one layer into its neighbour. The embossed deformation distorts the coating locally and can cause dropouts or a repeating physical print through the pack.','Tight winding presses the coils of tape hard against each other. A layer impression is a dent pressed from one coil into the next. A speck of dirt, a splice, or an edge can leave this mark. The dent warps the coating and can cause dropouts in the sound.','The term explains a mechanical (as opposed to magnetic) form of print-through, helping technicians trace repeating dropouts to embossed deformation rather than to the recording or the head.','When dropouts recur at the pack''s winding interval, a technician inspects for debris or splices embossed into neighbouring layers and removes the contaminant before winding.','Tape Pack Defects',ARRAY['Debris embossing','Print-through','Hard pack','Layer adhesion','Dropout','Cinching']::text[],ARRAY['Leaving grit or a proud splice in the pack, letting pack pressure emboss it into adjacent layers.','Confusing a mechanical layer impression with magnetic print-through and treating it as an unfixable recording flaw.']::text[],ARRAY['Investigating dropouts that repeat at the reel''s winding interval on playback.','Cleaning debris from a tape before rewinding so it does not emboss the next layer.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4f255673-d24a-5a3e-a6eb-187694cf9610' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Layer impression'),'[^a-z0-9]','','g'));
