SELECT '4f255673-d24a-5a3e-a6eb-187694cf9610','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4f255673-d24a-5a3e-a6eb-187694cf9610' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'fe01323c-d901-57eb-8d26-63e749a3e7bf','Leader embrittlement','The loss of flexibility and increasing brittleness of the non-magnetic leader tape spliced to the beginning and end of a reel, caused by ageing of its plastic or paper base, for example plasticiser loss in cellulose acetate or PVC leaders. Embrittled leader cracks, splits, or snaps under normal handling and threading tension, endangering the splice and the outermost turns of recorded tape.','Leader is the blank tape joined to the start and end of a reel. Over many years it can dry out and turn brittle. Brittle leader cracks or snaps when you handle the reel. That can pull apart the join and harm the recording next to it.','Recognising leader embrittlement warns a technician that the protective leader can no longer take handling or threading stress, so the splice and the outer recorded layers are at risk. It flags the reel for gentle handling or leader replacement before playback.','During inspection a technician gently flexes the leader; if it is stiff, cracked, or shedding pieces, the reel is set aside for leader replacement rather than threaded onto a machine.','Tape degradation',ARRAY['Leader replacement','Leader shrinkage','Splice','Plasticiser loss','Cellulose acetate base']::text[],ARRAY['Assuming a stiff, brittle leader is still safe to thread, when it can snap and jerk the recorded tape','Confusing leader embrittlement with sticky-shed syndrome, which affects the magnetic coating rather than the plastic base','UNSAFE: Pulling hard on a brittle leader to free a stuck reel, which can snap suddenly and sling the reel or sharp fragments']::text[],ARRAY['Inspecting an archival reel before digitisation','Deciding whether a reel needs new leader before playback','Diagnosing why a reel''s leader snapped during threading']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='fe01323c-d901-57eb-8d26-63e749a3e7bf' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Leader embrittlement'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'fe01323c-d901-57eb-8d26-63e749a3e7bf','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='fe01323c-d901-57eb-8d26-63e749a3e7bf' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd09a8a42-8d6f-5427-9bd0-e1c3454031ef','Leader replacement','A conservation treatment in which degraded, damaged, or missing leader tape is cut away and a fresh length of archival-grade leader is spliced onto the ends of a recorded reel. It restores a safe threading and handling margin and protects the outermost recorded turns during playback and rewinding.','Leader is the blank tape at each end of a reel. When it is brittle, torn, or gone, a technician joins on new leader. This gives a safe piece to thread through the machine. It also shields the recording from wear and handling.','It provides a sacrificial, non-magnetic length to thread and grip, so wear and handling damage fall on the leader rather than on the recording. It also secures the tape end and can carry identifying markings.','Before transferring a fragile reel, a technician splices new leader to each end with proper splicing tape and a splicing block, so the recorded tape is never gripped or threaded directly.','Conservation treatment',ARRAY['Leader embrittlement','Leader shrinkage','Splice','Splicing tape','Splicing block']::text[],ARRAY['Using pressure-sensitive office tape or the wrong adhesive, which can ooze, stain the recording, and contaminate the tape path','Splicing new leader out of alignment, so the tape tracks unevenly and its edges are stressed','Discarding original leader that carried box numbers or notes without first recording that information']::text[],ARRAY['Preparing a damaged reel for digitisation','Replacing a snapped or missing leader before playback','Restoring a safe handling margin on a heavily used tape']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d09a8a42-8d6f-5427-9bd0-e1c3454031ef' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Leader replacement'),'[^a-z0-9]','','g'));
