WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d09a8a42-8d6f-5427-9bd0-e1c3454031ef' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f8201d8e-2978-5a6f-bbc4-8df6959aa29d','Leader shrinkage','Dimensional shrinkage of the leader tape relative to the recorded tape, typically where an older cellulose acetate or PVC leader contracts with age and moisture loss while a polyester recorded tape does not. The mismatch causes cinching, buckling, or distortion at the splice and in the adjacent turns of the pack.','Leader is the blank tape at the ends of a reel. Old leader can slowly shrink as it ages and dries. If the recording tape does not shrink the same way, the two pull against each other. This can buckle or pinch the tape near the join.','Spotting leader shrinkage alerts a technician to stress and deformation building up at the splice, which can damage the first recorded turns. It signals that the old leader should be removed and replaced.','A technician who sees a puckered or curled splice and a leader that no longer matches the tape width removes the shrunken leader and splices on fresh, dimensionally stable leader before playback.','Tape degradation',ARRAY['Leader embrittlement','Leader replacement','Cellulose acetate base','Cupping','Splice']::text[],ARRAY['Mistaking splice-area buckling caused by leader shrinkage for damage in the recording itself','Leaving a shrunken acetate leader in place, so it keeps stressing the recorded tape','Assuming all leaders are dimensionally stable, when acetate and PVC leaders shrink with age']::text[],ARRAY['Assessing an old reel whose splice area looks puckered','Deciding whether to replace a mismatched, shrunken leader','Investigating edge damage traced to a contracting leader']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f8201d8e-2978-5a6f-bbc4-8df6959aa29d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Leader shrinkage'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'f8201d8e-2978-5a6f-bbc4-8df6959aa29d','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f8201d8e-2978-5a6f-bbc4-8df6959aa29d' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b9f27506-0ffe-55eb-8860-d66e3513714f','Localized dry-air treatment','A conservation intervention in which clean, dried (low-humidity) air is directed at a specific, limited area of a tape or its pack to draw off surface moisture, condensation, or loosely held debris, without wetting or heating the whole reel. It is a gentle, targeted alternative to bulk drying or immersion cleaning.','Sometimes only one spot of a tape is damp or dusty. A technician can aim clean, dry air at just that area. The dry air lifts away moisture and loose dirt. The rest of the reel is left untouched.','It removes moisture or loose foreign matter from a problem area while limiting the tape''s exposure to water, heat, and handling. Keeping the treatment local reduces the risk of spreading contamination or stressing the whole pack.','When a small patch of a reel shows condensation or loose surface dust, a technician uses filtered compressed clean air, or a controlled dry-air stream, to treat that spot before playback.','Conservation treatment',ARRAY['Low-temperature dehydration','Relative humidity','Tape cleaning','Mold staining','Dropout']::text[],ARRAY['Using unfiltered or oily shop compressed air, which drives contaminants and moisture into the coating','Blasting air at high pressure, which can lift the coating or disturb the tape pack','UNSAFE: Blowing air across a mouldy tape without containment or a fitted respirator, sending fungal spores into the air the operator breathes']::text[],ARRAY['Clearing condensation from a reel brought in from cool storage','Removing loose surface dust from a limited area before transfer','Treating a localised damp spot without wetting the whole reel']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b9f27506-0ffe-55eb-8860-d66e3513714f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Localized dry-air treatment'),'[^a-z0-9]','','g'));
