SELECT 'b9f27506-0ffe-55eb-8860-d66e3513714f','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b9f27506-0ffe-55eb-8860-d66e3513714f' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3c9ecfb1-9710-5684-81d9-f9efb853a01a','Long-play tape','Magnetic tape manufactured with a thinner base film than standard-play tape, so that a greater length fits on a reel or cassette of the same size and the playing time is extended. The reduced total thickness increases susceptibility to print-through, stretching, and mechanical deformation.','Long-play tape uses a thinner plastic base than normal tape. A thinner tape means more of it fits on the same reel. That gives longer recording and playing time. The trade-off is that thin tape stretches and prints through more easily.','It exists to extend recording time on a given reel or cassette size by packing in more tape. Archivists must recognise it because its thin, delicate base needs gentler tension and handling.','When a technician meets a reel that holds far more tape than usual for its size, they treat it as long-play stock and set lower tape tension to avoid stretching it.','Tape formats',ARRAY['Standard-play tape','Double-play tape','Print-through','Base film','Tape stretch']::text[],ARRAY['Playing thin long-play tape at high tension, which stretches it and distorts the sound','Ignoring the higher print-through risk of thin tape during long storage','Assuming all reels of one diameter hold the same length, regardless of base thickness']::text[],ARRAY['Identifying an unusually long reel before transfer','Setting gentle tension for thin amateur tape','Explaining stronger print-through on a long-play reel']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3c9ecfb1-9710-5684-81d9-f9efb853a01a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Long-play tape'),'[^a-z0-9]','','g'));
