SELECT '3c9ecfb1-9710-5684-81d9-f9efb853a01a','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='3c9ecfb1-9710-5684-81d9-f9efb853a01a' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c32bc41e-0893-5ff4-983f-ab866363fa24','Longitudinal curl','A lengthwise curvature deformation in which magnetic tape does not lie flat along its running direction, often arising from uneven or stepped winding, differential shrinkage, or storage stress. It degrades tape-to-head contact and can cause edge damage and unstable tracking during replay.','Tape should lie flat as it runs through the machine. Longitudinal curl means the tape curves along its length instead. Curled tape does not sit evenly against the heads. That weakens contact and can hurt the tape edges.','Identifying longitudinal curl explains lost high frequencies and unstable playback caused by poor head contact. It points to winding or storage problems that should be corrected before transfer.','A technician who sees tape that will not lie flat, or that tracks unevenly, may recondition it with a slow, even library wind and controlled storage to relax the curl.','Mechanical deformation',ARRAY['Cupping','Longitudinal vibration','Head-to-tape contact','Library wind','Tape pack']::text[],ARRAY['Confusing longitudinal curl with cupping, which is a curl across the tape''s width','Increasing tension to force a curled tape flat, which can crease or stretch it','Ignoring stepped or uneven winds that create curled tape edges over time']::text[],ARRAY['Diagnosing weak high-frequency output from poor head contact','Reconditioning a warped reel with an even wind','Assessing tape flatness before digitisation']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c32bc41e-0893-5ff4-983f-ab866363fa24' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Longitudinal curl'),'[^a-z0-9]','','g'));
