INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '084b1a36-17d4-5f80-b091-b72af8ba80e1','Longitudinal vibration','Vibration of the tape along its direction of travel (its long axis), in which small stretch-and-release oscillations of the moving tape modulate its instantaneous speed. In transports it is a source of flutter and scrape flutter, appearing as short-term speed and pitch instability in the reproduced signal.','A moving tape acts a bit like a stretched rubber band. It can vibrate back and forth along the way it travels. These tiny speed wobbles show up as unsteady pitch. Engineers call this longitudinal vibration.','Understanding longitudinal vibration explains kinds of flutter and pitch instability that arise in the tape path rather than in the recording itself. It guides where to add damping or improve guiding.','When a transfer shows rapid pitch waver, a technician checks guides, rollers, and tension for sources of longitudinal vibration such as stick-slip friction against fixed parts.','Tape mechanics',ARRAY['Wow and flutter','Scrape flutter','Longitudinal curl','Tape tension','Capstan']::text[],ARRAY['Blaming rapid pitch waver on the recording when it comes from vibration in the tape path','Overlooking stick-slip friction at guides and heads as a cause of scrape flutter','Confusing longitudinal, along-length vibration with lateral, side-to-side tape movement']::text[],ARRAY['Tracing fast flutter to a vibrating tape path','Fitting or checking a flutter-damping roller','Explaining pitch instability during a transfer']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='084b1a36-17d4-5f80-b091-b72af8ba80e1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Longitudinal vibration'),'[^a-z0-9]','','g'));
