INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd00134b3-340b-5c25-95a8-e07f1333213c','Low-temperature dehydration','A drying approach that removes absorbed moisture from tape at low or ambient temperature, relying on low-humidity air rather than heat, so that water is drawn out without the thermal stress that can deform the base or soften the binder. It is used when tapes have taken up excess moisture or been water-affected.','Wet or damp tape has to lose its moisture safely. Heat can warp tape or make the coating sticky. So the tape is dried in cool, very dry air instead. The low temperature pulls out water without harming the tape.','It lowers a tape''s moisture content while avoiding the heat damage and binder softening that warm drying can cause. Removing moisture also slows hydrolysis and discourages mould growth.','After a tape is exposed to damp or water, a technician dries it in a cool, low-humidity, well-ventilated space rather than applying heat, then checks it before playback.','Conservation treatment',ARRAY['Localized dry-air treatment','Relative humidity','Binder hydrolysis','Mold staining','Acclimatisation']::text[],ARRAY['UNSAFE: Drying tape in an oven or with a heat gun, which can warp the base, soften the binder, and destroy the recording','Drying tape in humid air, which fails to remove moisture and encourages mould','Playing a damp reel before it is fully dried, contaminating heads and the tape path']::text[],ARRAY['Recovering tapes after a water leak or flood','Reducing moisture in reels from a damp store','Preparing damp tape safely before transfer']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d00134b3-340b-5c25-95a8-e07f1333213c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Low-temperature dehydration'),'[^a-z0-9]','','g'));
