SELECT 'd00134b3-340b-5c25-95a8-e07f1333213c','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d00134b3-340b-5c25-95a8-e07f1333213c' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e151574a-868b-5853-8b7d-e2242431195c','Lubricant depletion','The gradual loss or consumption of the lubricant (typically fatty acids and esters) incorporated in a tape''s magnetic coating, through evaporation, repeated play, and ageing. As lubricant is depleted, friction between tape and heads rises, causing squeal, stiction, increased head wear, and unstable transport.','Tape coating holds a built-in lubricant that lets it slide past the heads. Over years and with heavy use, that lubricant runs low. With less lubricant the tape drags and can squeal. It also wears the heads faster and may stick.','The concept explains a common cause of squealing and sticking in old tape that is separate from sticky-shed. Recognising it guides safe playback and warns against harmful re-lubrication shortcuts.','When an old reel squeals or drags yet does not shed a gummy residue, a technician suspects lubricant depletion and proceeds cautiously, since adding lubricant is very hard to control.','Tape degradation',ARRAY['Lubricant exudation','Sticky-shed syndrome','Binder hydrolysis','Magnetic coating','Head-to-tape contact']::text[],ARRAY['Confusing lubricant depletion with sticky-shed syndrome, which is binder breakdown rather than loss of lubricant','UNSAFE: Applying random oils or solvents to ''re-lubricate'' tape, contaminating heads, guides, and other tapes and risking the recording','Assuming a squeal always means the tape must be baked, when depletion and hydrolysis have different causes']::text[],ARRAY['Diagnosing squeal on a heavily played archival reel','Deciding whether a squealing tape is shedding or simply dry','Explaining rising head wear on old stock']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e151574a-868b-5853-8b7d-e2242431195c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Lubricant depletion'),'[^a-z0-9]','','g'));
