SELECT 'e151574a-868b-5853-8b7d-e2242431195c','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e151574a-868b-5853-8b7d-e2242431195c' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '217df00d-8abe-5a0b-b297-4569599ea181','Lubricant exudation','The migration and crystallisation of lubricant out of the magnetic coating onto the tape surface, forming a bloom or deposit; certain lubricants such as stearic acid exude and crystallise particularly at low temperatures, below about 8 degrees Celsius. The deposit clogs replay heads, causes dropouts, and can contribute to stickiness during playback.','Tape coating holds a lubricant inside it. Sometimes that lubricant seeps out and forms a waxy film on the surface. This is worse when tapes are kept very cold. The film clogs the heads and can make playback drop out.','It names a specific cause of head clogging and dropouts that is distinct from binder shedding. Knowing it helps a technician clean correctly and store tape at a suitable temperature.','Seeing a waxy bloom on tape and clogged heads, a technician removes the surplus lubricant mechanically, sometimes aided by mild warmth, and reviews the cold-storage conditions.','Tape degradation',ARRAY['Lubricant depletion','Sticky-shed syndrome','Magnetic coating','Head clogging','Dropout']::text[],ARRAY['Mistaking a lubricant bloom for sticky-shed residue and reaching straight for baking','Storing lubricant-rich tape very cold, which can encourage stearic-acid exudation','UNSAFE: Removing surface deposits with unknown solvents whose reaction with the tape is unpredictable and whose vapours are hazardous']::text[],ARRAY['Cleaning a waxy deposit off tape and heads','Diagnosing dropouts from a clogged replay head','Reviewing cold-storage settings after exudation appears']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='217df00d-8abe-5a0b-b297-4569599ea181' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Lubricant exudation'),'[^a-z0-9]','','g'));
