INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '14e30df9-5469-5ec8-a031-b7f7c5e5eedf','Magnetic coating','The functional layer of a magnetic tape that stores the recorded signal, consisting of finely divided magnetic pigment (such as gamma ferric oxide, chromium dioxide, or metal particles) dispersed in a polymer binder, together with lubricants and other additives, coated onto the base film. Its magnetic and mechanical condition largely determines a recording''s playability and stability.','The magnetic coating is the working layer on a tape. It is a mix of tiny magnetic particles held in a plastic glue. This layer stores the actual sound or picture. The base film underneath is just the support that carries it.','It holds the magnetic particles that record and retain the signal, bonded firmly to the base film. Its makeup sets the tape''s output, noise, and how well it survives over time.','A technician inspects the magnetic coating for shedding, blooms, scratches, or flaking, since its condition dictates whether a tape can be safely played and transferred.','Tape components',ARRAY['Base film','Binder','Magnetic pigment','Sticky-shed syndrome','Back coating','Pigment layer']::text[],ARRAY['Confusing the magnetic coating with the base film, which only supports it and stores no signal','Assuming the recording lives on the shiny base side rather than the dull coated side','Touching the coated (oxide) surface with bare fingers, leaving oils that attract dust and feed mould']::text[],ARRAY['Assessing coating condition before playback','Identifying which side of the tape carries the signal','Explaining why coating breakdown loses the recording']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='14e30df9-5469-5ec8-a031-b7f7c5e5eedf' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Magnetic coating'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '14e30df9-5469-5ec8-a031-b7f7c5e5eedf','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='14e30df9-5469-5ec8-a031-b7f7c5e5eedf' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '482da0e5-cf60-5b24-bec3-9186e1cf43b6','Magnetic-particle agglomeration','The clumping together of the magnetic pigment particles within a tape''s coating, from incomplete dispersion during manufacture or from binder breakdown and ageing. Agglomerates disturb the smooth, uniform particle distribution needed for low noise, raising modulation noise and causing dropouts and uneven output.','A tape''s coating should hold its magnetic particles spread out evenly. Sometimes the particles clump into little lumps instead. Clumps make the surface less even. That adds noise and can cause brief signal dropouts.','The concept links audible noise and dropouts to the physical distribution of magnetic particles in the coating. It matters both in judging tape quality and in understanding age-related decline.','When a tape shows unusual noise or dropouts not explained by shedding or dirt, a technician may attribute it to poor particle dispersion or agglomeration in the coating and prioritise a clean transfer.','Tape degradation',ARRAY['Magnetic coating','Magnetic pigment','Modulation noise','Dropout','Binder','Particle agglomerate']::text[],ARRAY['Assuming all tape noise comes from the electronics, ignoring the coating''s particle distribution','Confusing agglomeration inside the coating with surface debris that can simply be cleaned off','Treating dropouts from agglomeration as something cleaning alone will fix']::text[],ARRAY['Explaining raised noise on a poorly dispersed tape stock','Diagnosing dropouts not caused by shedding or dirt','Comparing quality between tape formulations']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='482da0e5-cf60-5b24-bec3-9186e1cf43b6' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Magnetic-particle agglomeration'),'[^a-z0-9]','','g'));
