WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='482da0e5-cf60-5b24-bec3-9186e1cf43b6' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4913e813-feb1-5691-8b99-945b4e5088c7','Mains-hum speed correction','A restoration technique that uses the residual mains (power-line) hum captured in a recording, at the local supply frequency of nominally 50 or 60 Hz, as a stable reference to detect and correct playback speed and pitch errors. Because the power-line frequency is tightly regulated, deviation of the recorded hum from its nominal value reveals speed error, and tracking its short-term variation can also reduce wow and flutter.','Old recordings often pick up a faint hum from the mains power supply. This hum has a steady, known pitch. If the tape plays too fast or slow, the hum shifts away from that pitch. A technician measures the hum and corrects the speed until it matches again.','It gives archivists an objective reference for restoring the correct speed and pitch of a recording whose original machine speed is uncertain. It can also help smooth out wow and flutter.','Transferring a tape of unknown speed, a technician measures the recorded mains hum, compares it with the nominal 50 or 60 Hz, and adjusts the transfer speed so the hum returns to that value.','Signal restoration',ARRAY['Wow and flutter','Pitch correction','Playback speed','Print-through','Azimuth']::text[],ARRAY['Assuming the local mains frequency without checking whether the recording was made on a 50 Hz or 60 Hz supply','Treating the hum as perfectly fixed, ignoring small real variations in the supply frequency','Correcting to a hum that was introduced after the original recording rather than during it']::text[],ARRAY['Restoring correct pitch on a tape of unknown speed','Reducing wow by tracking recorded mains hum','Confirming whether a recording ran at the right speed']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4913e813-feb1-5691-8b99-945b4e5088c7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Mains-hum speed correction'),'[^a-z0-9]','','g'));
