INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '402d20b2-f700-53dd-841a-bce885e48a2f','Paper-base tape','An early form of magnetic recording tape that uses a paper backing (substrate) to carry the magnetic coating, predating the cellulose acetate and polyester film bases that followed. Used chiefly in the 1930s and 1940s, paper-base tapes are now rare; although the paper is generally chemically stable, it is brittle and mechanically fragile, prone to tearing or breaking during playback.','The earliest recording tapes used a paper strip as their backing, before plastic was used. The magnetic coating sat on top of the paper. These tapes are very rare today. The paper is fragile and can tear or snap when played, so it needs great care.','Knowing a tape is paper-based tells an archivist to expect a fragile, tear-prone carrier and to use an especially gentle, well-maintained transport for any playback.','Handling a suspected paper-base reel, a technician inspects it for brittleness, uses a clean well-aligned machine at low tension, and often makes a single careful preservation transfer.','Tape media',ARRAY['Acetate base','Polyester base','Tape substrate','Oxide shedding','Splice','Tape pack']::text[],ARRAY['Handling a brittle paper-base tape like modern polyester, so it tears or snaps during playback.','Running it at normal winding tension, which can break the fragile paper backing.','UNSAFE: Trying to unstick or clean an old paper-base tape with solvents or water, which can dissolve or cockle the paper and destroy the recording.']::text[],ARRAY['Identifying a 1940s reel whose backing is paper, not plastic.','Planning a single gentle transfer of a fragile paper-base recording.','Storing rare paper-base tapes upright and supported in a controlled archive.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='402d20b2-f700-53dd-841a-bce885e48a2f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Paper-base tape'),'[^a-z0-9]','','g'));
