INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '213d1314-b111-54e0-92d6-e64bf2096238','Particle agglomerate','A cluster of magnetic pigment particles that have clumped together within the magnetic coating instead of remaining finely and uniformly dispersed. Agglomerates arise from incomplete dispersion during manufacture or from binder degradation; they raise the coating''s surface roughness, creating asperities that increase head-to-tape spacing (spacing loss) and cause dropouts, and they may break free as debris.','A tape''s magnetic layer is made of tiny particles spread evenly in a binder. Sometimes those particles clump into lumps instead of staying separate. The lumps make the surface bumpy. Bumps lift the tape off the head, so the sound drops out. Lumps can also flake off as dirt.','The concept explains one source of surface roughness and dropouts on tape, linking playback faults to how well the magnetic particles were dispersed or how the coating has aged.','A technician who sees dropouts and surface asperities cleans the tape path, distinguishes agglomerate debris from shed binder, and factors coating condition into the transfer plan.','Media defects',ARRAY['Magnetic pigment','Oxide shedding','Dropout','Spacing loss','Particulate embedment','Binder','Magnetic-particle agglomeration']::text[],ARRAY['Blaming all dropouts on the machine or heads when clumped or shed coating on the tape is the cause.','Wiping the coating hard to remove lumps, which abrades the fragile surface and sheds more particles.','Confusing agglomerate debris with a head clog, so the tape path is not properly cleaned.']::text[],ARRAY['Diagnosing scattered dropouts traced to a rough, lumpy coating.','Cleaning debris from the tape path during transfer.','Assessing coating quality of an aged or poorly made tape.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='213d1314-b111-54e0-92d6-e64bf2096238' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Particle agglomerate'),'[^a-z0-9]','','g'));
