SELECT '213d1314-b111-54e0-92d6-e64bf2096238','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='213d1314-b111-54e0-92d6-e64bf2096238' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '178fb0a5-217b-5713-8608-6e1b609e8c93','Particulate embedment','The pressing and lodging of loose particulate debris, such as dust, dirt, or shed oxide and binder, into the surface of the magnetic coating or between the layers of the tape pack, typically under the pressure of winding or the head-to-tape contact of playback. Embedded particles create permanent surface defects and raised spots that increase head-to-tape spacing, causing dropouts and abrasive wear of heads and guides.','Loose dirt and shed coating can get pressed into the tape surface. The pressure of winding or of playing the tape drives the specks in. These embedded bits make raised spots that lift the tape off the head. That causes dropouts, and the grit wears down the heads.','The concept underlines why tapes and their environment must be kept clean, since trapped debris does lasting damage to both the recording and the equipment.','A technician keeps the tape path and workspace clean, cleans a dirty tape before winding, and stores reels boxed and upright to keep debris from being pressed into the surface.','Contamination',ARRAY['Dropout','Spacing loss','Oxide shedding','Particle agglomerate','Tape pack','Head clog']::text[],ARRAY['Winding a visibly dirty tape, which presses the grit into the coating and between the layers permanently.','Working in a dusty area or leaving reels unboxed, so airborne debris settles and is wound in.','Cleaning with a shedding cloth or bare fingers, which adds lint and oils that get embedded.']::text[],ARRAY['Finding raised specks and dropouts from debris pressed into an old tape.','Cleaning a reel before winding to avoid trapping grit.','Keeping the transfer bench and tape path clean during archival work.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='178fb0a5-217b-5713-8608-6e1b609e8c93' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Particulate embedment'),'[^a-z0-9]','','g'));
