WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='bc8c2506-7488-5a8f-a977-0d74c2c7d65a' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0a615bea-8820-5600-a0f0-060d3fc88b04','Polyvinyl-chloride base','A tape backing made of polyvinyl chloride (PVC), a flexible plasticized plastic used chiefly for German and other European magnetic tapes produced from the mid-1940s until about 1972, when polyester displaced it. PVC tapes have generally remained flexible and free of systematic chemical breakdown, though gradual plasticizer loss is a recognised long-term risk.','This is an early type of clear plastic backing for tape. It was used mostly on German tapes from the 1940s to the early 1970s. It has stayed bendy and aged fairly well. Its main long-term worry is the softener slowly leaking out.','Like any base film it carries the magnetic coating and gives the tape strength; PVC was valued for its soft, stable flexibility before polyester became the standard backing.','Encountering an older European reel, a technician may identify a PVC base, note that it has usually aged well, and handle it normally while watching for any stiffening from plasticizer loss.','Tape Structure',ARRAY['Polyester base','Cellulose acetate base','Plasticizer migration','Pigment layer','Print-through']::text[],ARRAY['Assuming all early tape is cellulose acetate, when much European tape of the 1940s to 1960s is PVC, which behaves and fails differently.','Expecting vinegar syndrome from PVC, when that acetic-acid odour is an acetate phenomenon, not a PVC one.','Overlooking gradual stiffening as a possible sign of plasticizer loss in a PVC backing.']::text[],ARRAY['Identifying the base material of a 1950s German broadcast reel.','Triaging a European archive containing mixed PVC and polyester tapes.','Explaining why a PVC tape has aged better than a contemporaneous acetate one.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0a615bea-8820-5600-a0f0-060d3fc88b04' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Polyvinyl-chloride base'),'[^a-z0-9]','','g'));
