INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a8191773-521f-53a3-83b9-9cec263eb44f','Popped strand','A single winding of tape that has slipped laterally out of an otherwise even tape pack and protrudes above the surrounding layers or beyond the reel flange. Caused by uneven or stepped winding and disturbance of the pack, the exposed strand is easily creased, folded, or edge-damaged during handling and fast winding.','In a neat tape roll every layer sits flush. A popped strand is one loop that has slipped sideways and sticks out. Because it pokes out, it gets crushed or folded easily. That can crease the tape and damage the edge.','Spotting a popped strand warns the technician of an uneven wind and a vulnerable, exposed loop, prompting a careful re-wind before the strand is damaged.','During inspection a technician sees a loop standing proud of the pack or past the flange and re-winds the tape at a slow, even library wind to draw the strand back flush before playback or storage.','Physical Degradation',ARRAY['Library wind','Reel eccentricity','Reel replacement','Edge damage','Tape pack']::text[],ARRAY['Fast-winding a reel with a popped strand, which crushes the protruding loop against the flange and creases the tape.','Pushing the strand back by hand instead of re-winding evenly, which can crimp or stretch it.','Storing a reel with an uneven wind, letting stepped windings and popped strands form curled, damaged edges.']::text[],ARRAY['Inspecting incoming reels before a digitisation batch.','Correcting an uneven pack left by a previous fast wind.','Preventing edge damage on a fragile master before transfer.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a8191773-521f-53a3-83b9-9cec263eb44f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Popped strand'),'[^a-z0-9]','','g'));
