SELECT 'a8191773-521f-53a3-83b9-9cec263eb44f','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a8191773-521f-53a3-83b9-9cec263eb44f' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ceef0604-9a31-5646-9e87-c86300ffeec7','Post-print','The component of print-through heard as a post-echo, a faint copy of the program that sounds after the original signal, produced when a strongly recorded layer magnetically imprints the adjacent tape layer that plays later. With standard oxide-in winding, tails-out storage is preferred so the stronger printed echo falls after the signal as a less objectionable post-print rather than before it.','Loud parts of a recording can magnetically copy onto the next layer of tape touching them. A post-print is that faint copy heard just after the real sound, like a soft echo. Storing the tape tails-out helps keep the loudest copy in this less annoying spot.','Distinguishing post-print (post-echo) from pre-print (pre-echo) guides storage orientation: archivists store tapes tails-out so the dominant printed echo becomes a post-print, which the ear tolerates far better than a pre-echo.','Hearing a faint echo after loud passages, a technician recognises post-print from print-through and confirms the tape is best stored tails-out to keep the stronger echo in that position.','Playback Artefact',ARRAY['Print-through','Pre-print','Tails-out storage','Library wind','Oxide-in winding']::text[],ARRAY['Mistaking a post-print echo for reverberation added during recording.','Storing tape heads-out, which places the stronger printed echo before the signal as a more audible pre-print.','Believing rewinding cannot help, when rewinding several times before playback reduces print-through echoes.']::text[],ARRAY['Auditioning a master and hearing a soft echo trailing loud notes.','Deciding storage orientation for a reel prone to print-through.','Explaining to a client why a faint echo follows the music.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ceef0604-9a31-5646-9e87-c86300ffeec7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Post-print'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'ceef0604-9a31-5646-9e87-c86300ffeec7','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ceef0604-9a31-5646-9e87-c86300ffeec7' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4bfc0e19-48c0-5f5d-a521-72f5ca9896e4','Pre-print','The component of print-through heard as a pre-echo, a faint copy of the program that sounds before the original signal, produced when a strongly recorded layer imprints the adjacent tape layer that plays earlier. Because a pre-echo is not masked by the sound that follows, it is more audible and objectionable than a post-echo, which is why tails-out storage is used to minimise it.','Loud sound can magnetically copy onto the touching layer of tape. A pre-print is that faint copy heard just before the real sound. Because nothing covers it up, this early echo is easy to notice and annoying. Good storage habits keep it as quiet as possible.','Identifying the pre-print (pre-echo) matters because it is the more disturbing form of print-through; keeping tapes cool, stored tails-out, and rewound before play all reduce it.','When a faint echo is heard ahead of a loud entrance, a technician diagnoses pre-print, rewinds the tape several times, and reviews the storage orientation to reduce it.','Playback Artefact',ARRAY['Print-through','Post-print','Tails-out storage','Library wind','Oxide-in winding']::text[],ARRAY['Confusing a pre-print echo with a tape-machine fault or a recording error.','Storing valuable tape heads-out, which makes the stronger printed echo a pre-echo.','Skipping the pre-play rewinds that measurably reduce print-through.']::text[],ARRAY['Hearing a ghost of a loud chord just before it actually plays.','Assessing print-through severity on a warm-stored master.','Choosing tails-out storage to keep the audible pre-echo down.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4bfc0e19-48c0-5f5d-a521-72f5ca9896e4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pre-print'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '4bfc0e19-48c0-5f5d-a521-72f5ca9896e4','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4bfc0e19-48c0-5f5d-a521-72f5ca9896e4' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3eb6679b-cd03-5c59-8df6-1fd4feac439a','Print-through','The unintentional transfer of a recorded magnetic signal from one layer of tape to the adjacent layers wound against it on the reel, heard on playback as faint pre- and post-echoes of the program. It increases with elevated storage temperature, thin tape, strong signal levels, and long storage, and is reduced by cool storage and by rewinding the tape before playback.','On a tape roll, each layer touches the next. A strong recording can slowly magnetise the layers pressed against it. You then hear faint echoes of the sound before and after it. Heat and long storage make this worse; cool storage and rewinding help.','Understanding print-through drives core storage rules: keep tape cool, wind it evenly, store important tapes tails-out, and rewind before playing, all to limit these self-generated echoes.','A technician who hears echoes tied to loud passages identifies print-through, rewinds the reel several times before transfer, and checks that storage has been cool and tails-out.','Playback Artefact',ARRAY['Pre-print','Post-print','Tails-out storage','Library wind','Stray magnetic field']::text[],ARRAY['Mistaking print-through echoes for reverb or a duplication error.','Storing tape warm or for long periods without rewinding, which lets print-through build up.','UNSAFE: Trying to erase print-through by exposing a recorded tape to a strong magnetic field or bulk eraser, which destroys the original recording.']::text[],ARRAY['Preparing a warm-stored master that now has audible echoes for transfer.','Explaining why a quiet passage carries a ghost of the loud one nearby.','Setting storage policy to minimise echo build-up on valuable reels.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3eb6679b-cd03-5c59-8df6-1fd4feac439a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Print-through'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '3eb6679b-cd03-5c59-8df6-1fd4feac439a','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='3eb6679b-cd03-5c59-8df6-1fd4feac439a' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7caa5946-6da9-517a-9cc7-213c853fadfe','Reel eccentricity','A condition in which a tape reel or its hub is not truly round or not centred on the spindle, so the tape pack''s effective radius varies as it turns. The resulting cyclic change in tape tension and linear speed produces wow at the reel''s rotational rate and can contribute to uneven winding.','A tape reel should spin true and centred. If it is warped or off-centre, the tape feeds unevenly as it turns. That makes the speed rise and fall once each spin. You hear it as a slow wavering pitch.','Recognising reel eccentricity as a source of slow speed variation lets the technician separate reel and hub faults from tape faults and fix them by replacing the misshapen reel.','Seeing a wobbling pack or a slow pitch waver, a technician checks for a warped or off-centre reel or a deformed hub and transfers the tape onto a true, slot-less reel.','Transport Fault',ARRAY['Pinch-roller eccentricity','Wow and flutter','Reel replacement','Library wind','Popped strand']::text[],ARRAY['Blaming the tape for slow pitch wobble when a warped or off-centre reel is the cause.','Keeping reels with slotted hubs, whose slots deform the innermost winds and disturb the pack over time.','Ignoring a visibly wobbling reel because the tape still plays, letting uneven tension damage the wind.']::text[],ARRAY['Tracing a once-per-revolution pitch waver to a warped supply reel.','Deciding to rehouse a tape whose original reel is misshapen.','Improving wind quality by moving tape onto a true reel.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7caa5946-6da9-517a-9cc7-213c853fadfe' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Reel eccentricity'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '7caa5946-6da9-517a-9cc7-213c853fadfe','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7caa5946-6da9-517a-9cc7-213c853fadfe' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '36fde0bf-2357-53a7-8e7f-6a6c29a44f73','Reel replacement','The conservation procedure of winding archival tape off a damaged, warped, or unsuitable reel or hub onto a sound, preferably slot-less, replacement reel of appropriate size and material. It is carried out when the original reel is misshapen, cracked, has deforming hub slots, or otherwise threatens the tape''s wind quality or physical safety.','Sometimes the reel holding a tape is warped, cracked, or badly designed. That can crush or bend the tape. Reel replacement means gently winding the tape onto a good new reel. This protects the tape for storage and playback.','It removes a mechanical hazard: a faulty reel or slotted hub can deform the tape and spoil the wind, so replacing it protects the tape pack and allows safe, even winding and playback.','Finding a cracked flange or a hub slot that has dented the inner winds, a technician spools the tape at an even library wind onto a flat, slot-less reel and rehouses it in a proper box.','Rehousing',ARRAY['Reel eccentricity','Library wind','Popped strand','Pellon wiping','Tails-out storage']::text[],ARRAY['Reusing a warped or slotted-hub reel because it still works, letting it keep deforming the tape.','Winding onto the new reel unevenly or at high speed, creating a stepped pack and curled edges.','UNSAFE: Forcing a brittle or degraded tape onto a new reel at speed, risking snapping it; degraded tape must be wound slowly and gently.']::text[],ARRAY['Rehousing a master whose original metal reel flange is bent.','Replacing a slotted-hub reel that has permanently dented the tape''s inner winds.','Standardising a collection onto flat, slot-less archival reels before storage.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='36fde0bf-2357-53a7-8e7f-6a6c29a44f73' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Reel replacement'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '36fde0bf-2357-53a7-8e7f-6a6c29a44f73','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='36fde0bf-2357-53a7-8e7f-6a6c29a44f73' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '49ad5b8d-a565-5c38-9525-3a3b361db27c','Reference-fluxivity mismatch','A discrepancy between the reference fluxivity (the standard recorded magnetic flux level per unit track width, expressed in nanowebers per metre, to which a reproducer''s replay gain is calibrated using an alignment tape) assumed during replay and the reference fluxivity actually used when the tape was recorded. Because several standard reference levels exist (for example 185, 250, 320 and 355 nWb/m, tied to different NAB, IEC and AES practices), aligning a reproducer to the wrong one shifts the whole transfer by a constant level offset.','Tape machines are set so a known test signal reads at the right level. Reference fluxivity is that agreed level. A tape may be made to one setting but played back on another. Then the sound comes out too loud or too soft.','Recognising a reference-fluxivity mismatch lets a transfer engineer restore the intended playback level, rather than capturing a recording that is uniformly too hot or too quiet.','During setup an engineer aligns replay gain to a known reference fluxivity on a calibration tape, then checks documentation or recorded line-up tone to confirm the recording used the same reference before trusting the level.','Replay Calibration',ARRAY['Reference tone','Replay calibration ambiguity','Operating level','Replay equalisation','Calibration tape','Absolute speed error']::text[],ARRAY['Assuming every tape uses the same reference fluxivity, so a modern high-output reference is applied to an older recording made at a lower level.','Aligning replay level to a calibration tape but never checking which reference the original recording actually used.','Confusing a reference-fluxivity level error, which is a constant offset, with a frequency-response error caused by wrong replay equalisation.']::text[],ARRAY['Setting replay gain on a studio recorder using a 320 nWb/m alignment tape before an archival transfer.','Discovering that a transferred tape plays several decibels low because it was recorded to a lower reference level.','Documenting the reference fluxivity used for a transfer in the technical metadata.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='49ad5b8d-a565-5c38-9525-3a3b361db27c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Reference-fluxivity mismatch'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '49ad5b8d-a565-5c38-9525-3a3b361db27c','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='49ad5b8d-a565-5c38-9525-3a3b361db27c' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3abdb2e9-3217-5665-a18b-58f64bdba08d','Rehousing','The conservation action of transferring an audio carrier out of a deteriorated, dirty, unstable or unsuitable container and into a new, clean, chemically stable housing, together with its identifying documentation. For magnetic tape this typically means fitting a reel and its wind into an inert box or new reel, or moving a tape into a sound shell, without altering the recording itself.','Rehousing means moving a tape into a new, clean, safe container. Old boxes or reels can be dirty, broken, or harmful to the tape. A fresh housing protects it and keeps its labels and notes with it.','Rehousing exists to remove sources of physical and chemical harm around a carrier and to give it a stable, well-labelled container, extending the life of the object and its information.','An archivist rehouses tapes that arrive in rusting cans, acidic boxes or broken reels, replacing the container with inert materials while carefully copying across all original labels and notes.','Conservation Treatment',ARRAY['Shell transplant','Smooth pack','Soft-binder syndrome','Tape pack','Archival storage','Rewinding']::text[],ARRAY['Discarding or failing to transfer the original box labels and inserts, so the recording loses its identification and provenance.','Rehousing a tape without first winding it into an even, properly tensioned pack, locking in an existing pack fault.','UNSAFE: Rehousing mouldy or water-damaged tape without gloves, a respirator and containment, risking inhalation of mould spores and spreading contamination.']::text[],ARRAY['Moving a collection of open-reel tapes out of rusted metal cans into inert archival boxes.','Replacing a cracked plastic reel while keeping the same tape and its documentation.','Rehousing tapes recovered from a flood after they have been cleaned and dried.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3abdb2e9-3217-5665-a18b-58f64bdba08d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Rehousing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '3abdb2e9-3217-5665-a18b-58f64bdba08d','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='3abdb2e9-3217-5665-a18b-58f64bdba08d' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4f77e2d9-fbbe-5c8b-9847-e443c41c9ed7','Replay calibration ambiguity','The uncertainty that arises when the parameters needed to reproduce a tape correctly, such as its recording equalisation, reference level and speed, are undocumented or contradictory, so the engineer cannot be sure which replay settings restore the original signal. Guidance is that, without objective evidence for other settings, a tape should be treated as properly aligned and, where documentation is absent, replay choices may have to be made aurally.','To play an old tape correctly, you must match the machine to how it was made. Often no one wrote those settings down. Replay calibration ambiguity is the doubt about which settings are the right ones.','Naming this ambiguity reminds an engineer to document assumptions and seek objective evidence, rather than silently guessing settings that change the pitch, level or tone of the transfer.','Facing a tape with no line-up tones or paperwork, an engineer defaults to standard alignment, listens critically for clues, and records every assumption made so the transfer can be reassessed later.','Replay Calibration',ARRAY['Replay equalisation','Reference-fluxivity mismatch','Reference tone','Segmental azimuth correction','Absolute speed error','Operating level']::text[],ARRAY['Guessing at replay settings without documenting the choice, so the transfer cannot be checked or corrected afterwards.','Assuming a non-standard setting when there is no objective evidence, instead of treating the tape as properly aligned.','Trusting a handwritten box note about speed or equalisation without confirming it against the tape''s own line-up tones.']::text[],ARRAY['Transferring an undocumented reel that has no reference tones at its head.','Deciding a replay equalisation by ear when the recording standard is unknown.','Logging every replay assumption in the transfer''s technical metadata for later review.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4f77e2d9-fbbe-5c8b-9847-e443c41c9ed7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Replay calibration ambiguity'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '4f77e2d9-fbbe-5c8b-9847-e443c41c9ed7','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4f77e2d9-fbbe-5c8b-9847-e443c41c9ed7' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5131ddae-ca7c-5e36-b0b3-b7f74090b43c','Salt contamination','The presence of soluble salt deposits on the surface of magnetic tape, most often introduced by immersion in salt or flood water, by perspiration and handling, or from a polluted storage environment. Salts are hygroscopic and mildly corrosive, so they draw moisture into the tape, can attack the pigment and backing, and form a solid film between the tape and the head that causes signal loss.','Salt can get onto tape from flood water, sweat, or dirty air. Salt pulls in moisture and can slowly eat at the tape. It also lifts the tape away from the playback head, so the sound drops out.','Identifying salt contamination tells a conservator that a tape needs careful cleaning and stabilising, because leaving the salt in place keeps drawing in damaging moisture and blocks good playback.','Handling tape recovered from a flood, a conservator rinses and cleans away salt residues with appropriate methods and dries the tape before any attempt to play or transfer it.','Contamination',ARRAY['Spacing loss','Dropout','Mould','Rehousing','Tape cleaning','Soft-binder syndrome']::text[],ARRAY['Playing a salt-contaminated tape before cleaning it, so grit and deposits abrade the tape and clog the heads.','Assuming a tape has dried safely when hygroscopic salt is still present and keeps reabsorbing moisture.','UNSAFE: Handling flood- or salt-water-damaged tape without gloves and respiratory protection, because such tape often also carries mould and biohazards.']::text[],ARRAY['Recovering open-reel tapes soaked in seawater after a coastal storm.','Finding salt haze and dropouts on tapes stored in a damp, polluted basement.','Cleaning perspiration and handling residues from heavily used field-recording tape.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5131ddae-ca7c-5e36-b0b3-b7f74090b43c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Salt contamination'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '5131ddae-ca7c-5e36-b0b3-b7f74090b43c','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='5131ddae-ca7c-5e36-b0b3-b7f74090b43c' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8dbd2347-33aa-5b69-83d1-eaa3beb5a596','Scattered wind','A tape-pack fault in which successive layers are not wound in lateral alignment, so the edges of the pack are uneven and individual strands protrude, giving a rough, ragged pack rather than a flat, smooth face. It results from poor winding tension or a misaligned or unsteady transport and leaves the exposed tape edges vulnerable to physical damage.','A good tape roll has smooth, even edges. A scattered wind is a messy roll where layers stick out unevenly. The rough, ragged pack can damage the tape edges and make it hard to play.','Spotting a scattered wind warns a technician that the pack is stressed and the tape edges are exposed, prompting a careful rewind to an even pack before storage or transfer.','Seeing protruding strands and a ragged pack edge, a technician winds the tape through at a controlled, even tension to produce a smooth pack before boxing it.','Tape Pack',ARRAY['Smooth pack','Soft pack','Popped strands','Cinching','Tape pack','Rewinding']::text[],ARRAY['Storing a tape with a scattered wind, leaving protruding edges to be crushed or creased in the box.','Fast-winding at uneven tension to tidy the pack, which can pull edges and worsen the damage.','Confusing a scattered wind, an edge-alignment fault, with a soft pack, which is a low-tension winding fault.']::text[],ARRAY['Finding an archival reel with tape strands sticking out of a ragged pack.','Rewinding a poorly wound tape to an even pack before archival storage.','Diagnosing edge damage traced to a tape repeatedly wound on a misaligned transport.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8dbd2347-33aa-5b69-83d1-eaa3beb5a596' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Scattered wind'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '8dbd2347-33aa-5b69-83d1-eaa3beb5a596','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8dbd2347-33aa-5b69-83d1-eaa3beb5a596' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c583a40a-6237-5ad7-b390-f0f584f80c34','Scrape flutter','A high-frequency form of flutter, typically in the low kilohertz range, produced when tape undergoes rapid stick-slip friction against fixed elements of the tape path such as heads and guides, exciting a longitudinal (string-like) vibration of the unsupported tape span. It adds noise and modulation sidebands to the signal and is commonly reduced with a rotating scrape-flutter idler that damps the free tape length.','As tape slides past fixed metal parts, it can grip and slip very fast. This makes the tape vibrate like a plucked string. That fast wobble adds a rough, fuzzy sound, heard mostly on high notes.','Understanding scrape flutter helps a technician trace a fuzzy, unstable high-frequency quality to friction in the tape path and fix it at the transport rather than in processing.','Hearing gritty modulation on sustained tones, a technician checks tape-path cleanliness and the scrape-flutter idler, since a seized or missing idler lets the free tape span vibrate.','Speed Stability',ARRAY['Wow and flutter','Scrape-flutter idler','Tape transport','Servo hunting','Head-to-tape contact','Tape tension']::text[],ARRAY['Confusing scrape flutter, a rapid high-frequency vibration, with wow, which is a slow speed variation.','Assuming the roughness is on the recording when a seized flutter idler or dirty guide is causing it.','Trying to fix scrape flutter with equalisation instead of servicing the tape path and idler.']::text[],ARRAY['A gritty, unstable top end on sustained notes that clears after the flutter idler is freed and cleaned.','Diagnosing modulation noise added by a fixed guide with a rough or sticky surface.','Checking a transport''s scrape-flutter idler as part of routine maintenance before a transfer.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c583a40a-6237-5ad7-b390-f0f584f80c34' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Scrape flutter'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c583a40a-6237-5ad7-b390-f0f584f80c34','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c583a40a-6237-5ad7-b390-f0f584f80c34' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '75a885d2-ea2d-5d59-b103-03e06b65b769','Segmental azimuth correction','The practice of re-adjusting the reproduce head''s azimuth (the angle of the head gap relative to a line across the tape) separately for different sections of a tape, because the azimuth can vary along its length, for instance where parts were recorded on different machines or at different times. Since an azimuth error causes progressive high-frequency loss, matching the head to each segment restores the treble that a single fixed setting would sacrifice.','Azimuth is the exact angle of the playback head against the tape. The correct angle can change from one part of a tape to the next. Segmental azimuth correction means resetting that angle for each section to keep the sound clear.','It exists so a transfer keeps its full high-frequency detail across a tape whose azimuth shifts, instead of accepting dull passages where one fixed head angle no longer matches the recording.','Transferring a tape assembled from several sources, an engineer re-peaks azimuth for maximum high-frequency output at each section rather than setting it once for the whole reel.','Replay Calibration',ARRAY['Azimuth error','Replay calibration ambiguity','Spacing loss','Reference tone','Replay equalisation','Head alignment']::text[],ARRAY['Setting azimuth once at the head of the tape and assuming it stays correct for the whole reel.','Peaking azimuth on programme material that lacks high frequencies, giving an unreliable setting.','Confusing an azimuth high-frequency loss with a replay-equalisation error, and adjusting the wrong control.']::text[],ARRAY['Transferring a compilation reel spliced from tapes recorded on different machines.','Restoring treble on a passage that went dull because its azimuth differs from the rest of the tape.','Re-peaking azimuth at each new segment while capturing a multi-session recording.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='75a885d2-ea2d-5d59-b103-03e06b65b769' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Segmental azimuth correction'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '75a885d2-ea2d-5d59-b103-03e06b65b769','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='75a885d2-ea2d-5d59-b103-03e06b65b769' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4189f148-08bd-568b-9cdf-57ba2f04733b','Servo hunting','An unstable behaviour of a closed-loop servo, such as a capstan or reel-motor speed servo in a tape transport, in which the control loop repeatedly overshoots and undershoots its target instead of settling, so the controlled quantity oscillates about the set point. In a transport this cyclic correction appears as a periodic speed variation, heard as wow, and usually points to excessive loop gain, mechanical lag or a fault in the feedback path.','A servo is an automatic control that keeps the tape at the right speed. If it overcorrects, it swings above and below the target instead of holding steady. This back-and-forth is called hunting, and it makes the speed wobble.','Recognising servo hunting separates a control-loop fault from a tape or recording problem, directing the technician to the transport''s servo electronics and feedback path.','Hearing a regular, cyclic wow that varies with the servo rather than the tape, a technician checks the tachometer feedback, loop adjustment and capstan servo instead of blaming the tape.','Tape Transport',ARRAY['Wow and flutter','Capstan','Tape transport','Scrape flutter','Actual tape speed','Brake drag']::text[],ARRAY['Blaming a cyclic wow on the tape when the capstan servo is hunting.','Correcting the audible pitch wobble in software instead of servicing the unstable servo loop.','Confusing servo hunting, a regular control-loop oscillation, with random flutter from friction in the tape path.']::text[],ARRAY['A steady, repeating pitch wobble that follows the deck''s servo rather than the recording.','Diagnosing a transport whose speed cycles because its tachometer feedback is faulty.','Servicing capstan servo electronics before trusting a deck for archival transfer.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4189f148-08bd-568b-9cdf-57ba2f04733b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Servo hunting'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '4189f148-08bd-568b-9cdf-57ba2f04733b','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4189f148-08bd-568b-9cdf-57ba2f04733b' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f63426b2-98e2-5935-9f2c-d2c171b8b10e','Shell transplant','A conservation repair in which the tape pack and hubs of a compact cassette (or similar cased tape) are removed from a damaged, seized or sonically welded shell and refitted into a sound donor or screw-together shell, without disturbing the recording. It restores a safely playable mechanism when the original housing, rather than the tape itself, is the point of failure.','A cassette''s plastic case is called its shell. If the shell is cracked or jammed, the tape inside cannot play safely. A shell transplant moves the tape into a new, working shell.','It exists to make a cassette playable again when its housing fails, by giving the good tape a reliable mechanism instead of forcing it through a broken or sealed shell.','Facing a jammed or welded cassette, a technician opens a screw-type donor shell, moves the tape pack and rollers across, and reassembles it so the recording can be transferred.','Conservation Treatment',ARRAY['Rehousing','Cassette','Pressure pad','Smooth pack','Soft-binder syndrome','Tape guide']::text[],ARRAY['Forcing a jammed sealed-shell cassette through a deck instead of transplanting the tape into a working shell.','Reusing worn pressure pads or guides from the failed shell, so playback quality suffers after the transplant.','Handling the loose tape pack carelessly during transfer, causing a scattered wind or creasing.']::text[],ARRAY['Moving the tape from a cracked cassette into a screw-together donor shell for transfer.','Freeing a recording trapped in a sonically welded shell that cannot be opened cleanly.','Replacing a cassette whose seized rollers stop the tape from moving.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f63426b2-98e2-5935-9f2c-d2c171b8b10e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Shell transplant'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'f63426b2-98e2-5935-9f2c-d2c171b8b10e','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f63426b2-98e2-5935-9f2c-d2c171b8b10e' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0cd306b3-e7cf-5fc1-b62b-3cc0d205dd3a','Smooth pack','A well-formed tape wind in which successive layers are laterally aligned under even, appropriate tension, producing a flat, uniform pack face free of protruding strands, steps or ridges. It is the desired condition for winding and storage because uniform packing distributes stress evenly and protects the tape edges.','A smooth pack is a tape roll wound evenly, with flat, even edges. It is the healthy way a tape should look on its reel. Even winding protects the tape and helps it play back steadily.','A smooth pack exists to spread winding stress uniformly and shield the tape edges, reducing the risk of cinching, popped strands and mechanical damage during storage and handling.','Before boxing a tape for storage, a technician winds it at a steady, even tension, checking that the pack face is flat and free of protruding strands.','Tape Pack',ARRAY['Soft pack','Scattered wind','Popped strands','Cinching','Tape pack','Rewinding']::text[],ARRAY['Believing any fast wind gives a smooth pack, when uneven tension leaves steps and protruding edges.','Judging pack quality by the reel''s outside only, missing tension faults deeper in the wind.','Winding at high speed for a neat look, which can trap air and give a deceptively loose pack.']::text[],ARRAY['Winding an archival tape to a flat, even pack before placing it in its box.','Comparing a healthy smooth pack against a ragged scattered wind on the same shelf.','Producing an even library wind at the end of an archival transfer.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0cd306b3-e7cf-5fc1-b62b-3cc0d205dd3a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Smooth pack'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '0cd306b3-e7cf-5fc1-b62b-3cc0d205dd3a','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0cd306b3-e7cf-5fc1-b62b-3cc0d205dd3a' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '97dcd943-5204-5137-aa41-9b3908de099d','Soft pack','A tape wind formed at too low a tension, so the pack is loose and lacks the internal support of a firm wind. Loose winds trap air and allow layers to slip; when the reel is stopped or handled abruptly the outer layers can slide inward and cinch, folding the tape on itself and producing creases and dropouts.','A soft pack is a tape roll wound too loosely. The loose layers can slip and fold over each other. This can crease the tape and cause dropouts, where the sound cuts out.','Identifying a soft pack warns a technician that the tape is prone to slippage and cinching, so it should be rewound to a firm, even pack before storage or transport.','Finding a loose, easily deformed pack, a technician rewinds the tape at correct tension to firm it up before boxing it, avoiding sudden stops that could cinch the loose layers.','Tape Pack',ARRAY['Smooth pack','Scattered wind','Cinching','Dropout','Tape tension','Rewinding']::text[],ARRAY['Leaving a soft, loose pack as found, so a sudden stop lets the outer layers slip and cinch.','Stopping a loosely wound reel abruptly in fast wind, folding the tape on itself.','Confusing a soft pack, a low-tension fault, with a scattered wind, which is an edge-alignment fault.']::text[],ARRAY['Rewinding a loosely packed reel to proper tension before archival storage.','Tracing creases and dropouts to a tape that had been left in a soft pack.','Avoiding a hard stop when handling a loosely wound archival tape.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='97dcd943-5204-5137-aa41-9b3908de099d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Soft pack'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '97dcd943-5204-5137-aa41-9b3908de099d','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='97dcd943-5204-5137-aa41-9b3908de099d' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1979c917-e21f-570d-805c-cee38e6c7d45','Soft-binder syndrome','A degradation of magnetic tape in which the polyurethane binder that holds the magnetic pigment to the backing absorbs moisture and undergoes hydrolysis, breaking down into a softened, tacky material. Also called sticky-shed syndrome, it raises tape-to-head friction and causes squealing, stick-slip motion, shedding of gummy residue that clogs heads, and in severe cases seizing of the tape.','The binder is the glue that holds the magnetic coating onto the tape. Over years, moisture can make it soft and sticky. The tape then squeals, sheds gunk, and can jam the machine. This is also called sticky-shed.','Recognising soft-binder syndrome lets an archivist diagnose why a tape squeals and sheds, and decide on temporary stabilising treatment before transferring it, rather than damaging the tape and heads.','Before transfer, a technician who hears squeal and sees residue treats the affected tape by controlled low-humidity or gentle heat conditioning, then transfers it promptly while it is temporarily playable.','Tape Degradation',ARRAY['Binder hydrolysis','Sticky-shed syndrome','Tape baking','Dropout','Head clog','Salt contamination']::text[],ARRAY['Repeatedly playing a squealing tape without treatment, grinding shed residue into the heads and abrading the tape.','Assuming heat treatment is a permanent cure, when it only makes the tape temporarily playable and transfer must follow soon.','UNSAFE: Baking tape in a domestic oven or a microwave, whose poor or uneven temperature control can overheat and permanently deform the tape; a temperature-controlled laboratory oven is required.','UNSAFE: Exceeding the recommended treatment temperature, since higher temperatures can deform the tape and cause irreversible loss.']::text[],ARRAY['A 1970s-80s back-coated tape that squeals and sheds brown residue on first playback.','Conditioning a hydrolysed tape at controlled low humidity before an urgent transfer.','Cleaning gummy deposits from heads and guides after playing an affected reel.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1979c917-e21f-570d-805c-cee38e6c7d45' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Soft-binder syndrome'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '1979c917-e21f-570d-805c-cee38e6c7d45','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1979c917-e21f-570d-805c-cee38e6c7d45' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7574e65e-3738-51be-84c0-e5157c97c597','Spacing loss','The loss of reproduced signal that results from any separation between the tape''s magnetic surface and the reproduce head gap. The loss increases rapidly with separation and with rising frequency, amounting to approximately 55 decibels for each wavelength of separation, so even a very thin layer of dust, debris or a rough or lifted surface can sharply attenuate high frequencies.','Tape must touch the playback head closely to be read well. Any gap, even from dust or a rough surface, weakens the signal fast. This drop in level from a tiny gap is called spacing loss.','The concept of spacing loss explains why intimate head-to-tape contact and cleanliness matter, and why contamination, debris or surface deformation cause dropouts and dull high frequencies.','Seeing high-frequency dropouts, a technician cleans the tape and head, and checks for debris or surface damage, knowing even a microscopic gap causes large spacing loss.','Signal Loss',ARRAY['Dropout','Head-to-tape contact','Salt contamination','Segmental azimuth correction','Head clog','Tape cleaning']::text[],ARRAY['Underestimating how a microscopic particle can cause large signal loss and a dropout.','Blaming lost high frequencies on the recording when debris or poor contact is causing spacing loss.','Cleaning the head but not the tape surface, so contamination still holds the tape off the gap.']::text[],ARRAY['A dropout caused by a speck of debris briefly lifting the tape off the head.','Dull, weak high frequencies traced to a contaminated or roughened tape surface.','Justifying strict tape-path cleanliness during archival transfer to avoid spacing loss.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7574e65e-3738-51be-84c0-e5157c97c597' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Spacing loss'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '7574e65e-3738-51be-84c0-e5157c97c597','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7574e65e-3738-51be-84c0-e5157c97c597' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0a0ddaa4-527c-5b94-a652-67dc74518998','Speed-reference reconstruction','The process of determining and restoring a tape''s correct playback speed by referencing a known-frequency signal captured in the recording, such as mains-frequency hum or a sync pilot tone, so that pitch and duration match the original event. It compensates for unknown original speeds and for transports that ran fast or slow during recording or transfer.','This finds the right playback speed for an old tape. Engineers use a steady sound already on the tape, like the hum from mains power. They match it to its known pitch so the tape plays at the correct speed.','It exists because a transfer played at the wrong speed shifts pitch and timing; a known reference lets the archivist recover the intended sound rather than an altered one.','During transfer a technician measures recorded mains hum or a pilot tone against its true frequency, then trims the deck''s speed until the reference reads correctly.','Playback & Transfer',ARRAY['Wow and flutter','Pilot tone','Capstan','Azimuth','Line-up tone']::text[],ARRAY['Assuming every tape was recorded at a standard speed, when field and amateur machines often ran fast or slow.','Correcting pitch in software after transfer instead of setting the correct replay speed at the source.','Filtering out a steady reference such as mains hum before it can be used to check speed.']::text[],ARRAY['Transferring a field recording whose portable recorder ran at an unknown speed.','Using recorded 50 Hz or 60 Hz mains hum to verify the true speed of an archival tape.','Restoring correct pitch on a recording made on an off-speed machine.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0a0ddaa4-527c-5b94-a652-67dc74518998' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Speed-reference reconstruction'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '0a0ddaa4-527c-5b94-a652-67dc74518998','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0a0ddaa4-527c-5b94-a652-67dc74518998' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '694b9d3d-ea6a-5b23-8fb7-d82036100578','Splice bleed','The migration of adhesive from splicing tape beyond the edges of a splice, so that tacky adhesive oozes onto the tape surface and onto adjacent windings in the pack. It develops as pressure-sensitive splicing-tape adhesive ages, softens, and is squeezed outward under tape-pack pressure.','Splices are joined with sticky tape. Over the years that glue can ooze out past the join. It then smears onto nearby layers of the wound tape and makes them stick.','It is a sign of adhesive breakdown at a splice; identifying it lets an archivist isolate the tape and plan resplicing before the migrating adhesive fouls heads or bonds layers together.','Inspecting a reel, a technician spots shiny, sticky residue seeping from a splice and flags the tape for adhesive cleaning and splice replacement before transfer.','Splicing & Repair',ARRAY['Splice replacement','Splice blocking','Blocking','Splicing tape','Print-through']::text[],ARRAY['Playing a tape with bleeding splice adhesive, which deposits residue on guides and heads.','Assuming the residue is harmless dust rather than migrating adhesive.','UNSAFE: Removing adhesive residue with unapproved or flammable solvents in an unventilated space instead of conservator-approved methods.']::text[],ARRAY['Finding gummy adhesive seeping from edit splices on an older master tape.','Adhesive from a splice sticking to the next layer and lifting oxide on unwind.','Assessing a reel before digitisation and flagging bleeding splices for repair.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='694b9d3d-ea6a-5b23-8fb7-d82036100578' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Splice bleed'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '694b9d3d-ea6a-5b23-8fb7-d82036100578','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='694b9d3d-ea6a-5b23-8fb7-d82036100578' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'cc06de34-f659-56cc-8a7b-9785563cabc0','Splice blocking','A localized form of blocking in which the adhesive at a splice bonds that turn of tape to the adjacent winding, so the layers resist separation when the reel is unwound. It results from splicing-tape adhesive that has softened, bled, or been over-applied, often aggravated by warm storage and tape-pack pressure.','Blocking is when tape layers stick together in the roll. Splice blocking is when the glue at a join sticks it to the next layer. Those stuck layers fight apart as you unwind the tape and can tear.','Spotting splice blocking warns that unwinding may tear tape or strip oxide at the join; it tells the conservator to free the layers gently and replace the splice before playback.','When a reel resists unwinding at a splice, a technician stops, works the bonded layers apart by hand, and re-splices rather than forcing the transport.','Splicing & Repair',ARRAY['Blocking','Splice bleed','Splice replacement','Sticky-shed syndrome','Tape pack']::text[],ARRAY['Forcing a machine to pull apart blocked layers, tearing the tape or stripping magnetic coating.','Confusing splice blocking with whole-pack blocking from binder failure.','UNSAFE: Handling mould-affected blocked tape without gloves and a fitted respirator.']::text[],ARRAY['A splice bonded to the next wrap on a warm-stored reel.','Layers snapping apart audibly as an old spliced tape is unwound.','Freeing a blocked splice before a preservation transfer.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='cc06de34-f659-56cc-8a7b-9785563cabc0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Splice blocking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'cc06de34-f659-56cc-8a7b-9785563cabc0','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='cc06de34-f659-56cc-8a7b-9785563cabc0' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c939a543-cbfe-5a4d-bb01-8ffdf0990080','Splice curl','A lifting or curling of the tape at or near a splice, where the join no longer lies flat against the heads and guides. It arises from shrinkage or stiffening of aged splicing tape, mismatched tension across the join, or a splice made with poorly mated ends.','A splice should lie flat and smooth. Splice curl is when the join lifts or curls up at the edge. The raised join loses good contact with the playback head and drops the sound out.','The curl lifts the tape off the head, so recognizing it explains momentary dropouts at a join and tells the technician the splice must be remade flat.','Hearing a level drop each time a splice passes the head, a technician inspects for a lifting join and remakes the splice so it lies flat.','Splicing & Repair',ARRAY['Splice failure','Splice replacement','Dropout','Cupping','Splicing tape']::text[],ARRAY['Blaming head-contact dropouts on the heads when a curled splice is the real cause.','Pressing a curled splice down without remaking it, so it lifts again.','Repairing with stretchy or non-archival tape that curls as it ages.']::text[],ARRAY['A lifted edit splice causing a click and dropout on every pass.','An old splice curling after decades in a warm store.','Checking splices for flatness before a clean transfer.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c939a543-cbfe-5a4d-bb01-8ffdf0990080' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Splice curl'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c939a543-cbfe-5a4d-bb01-8ffdf0990080','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c939a543-cbfe-5a4d-bb01-8ffdf0990080' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9d9cc9c3-a246-57ab-9663-66ccd62f0074','Splice failure','The parting or weakening of a splice so that the joined tape ends separate, either fully as a break or partially as a lifting or offset join. It is typically caused by splicing-tape adhesive that has dried out, embrittled, or lost tack with age, or by a poorly made original splice.','A splice is a repaired join in the tape. Splice failure is when that join comes apart. Old joining tape dries out and loses its grip, so the ends separate, often during playback.','It marks the point where a tape can physically break in the transport; identifying failing splices lets the archivist repair them before a snap damages the tape or the machine.','Before transfer a technician flexes and inspects each splice; any that has lost adhesion is remade with fresh archival splicing tape.','Splicing & Repair',ARRAY['Splice replacement','Splice curl','Splice bleed','Splicing tape','Leader tape']::text[],ARRAY['Running a tape with a weak splice, which parts at speed and spills the pack.','Repairing with household sticky tape instead of archival splicing tape.','Assuming a splice that looks intact still holds, without checking its tack.']::text[],ARRAY['A dried edit splice separating as a reel is played.','A leader-to-tape join failing during spooling.','Auditing all splices on a master before digitisation.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9d9cc9c3-a246-57ab-9663-66ccd62f0074' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Splice failure'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9d9cc9c3-a246-57ab-9663-66ccd62f0074','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9d9cc9c3-a246-57ab-9663-66ccd62f0074' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '14f8a129-55f3-58d1-a046-6642fa25aeeb','Splice imprint','An impression embossed into adjacent windings of the tape pack by the raised thickness of a splice, since even a well-made splice stands proud of the tape surface. The repeated bump deforms neighbouring layers and increases head-to-tape separation where those layers pass the head, producing periodic dropouts.','A splice is a little thicker than the tape. Wound in the roll, it presses a dent into the layers touching it. Where those dented layers meet the head, contact suffers and the sound can drop out.','It explains regularly spaced dropouts away from the splice itself; knowing the cause tells the archivist the deformation is mechanical, not a recording fault.','A technician who hears evenly spaced dropouts traces them to layers embossed by a nearby splice and, where possible, reduces the splice''s thickness on repair.','Splicing & Repair',ARRAY['Splice replacement','Print-through','Dropout','Embossing','Tape pack']::text[],ARRAY['Mistaking splice-imprint dropouts for magnetic print-through of the signal.','Repairing with thick or doubled splicing tape that embosses even more.','Storing spliced tape in hot conditions, which deepens the impressions.']::text[],ARRAY['Periodic dropouts on the layers next to an edit splice.','Impressions repeating every reel turn near a thick splice.','Assessing pack damage around splices before transfer.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='14f8a129-55f3-58d1-a046-6642fa25aeeb' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Splice imprint'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '14f8a129-55f3-58d1-a046-6642fa25aeeb','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='14f8a129-55f3-58d1-a046-6642fa25aeeb' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6d5c7941-dc20-59a3-b033-f249fdf0eb75','Splice replacement','The conservation procedure of removing a failed, contaminated, or non-archival splice and rejoining the tape ends with fresh, chemically stable splicing tape cut to the correct width and angle. It restores mechanical integrity and clean head contact so the tape can be transported and transferred safely.','This means taking out an old, bad splice and making a new one. The conservator uses fresh, stable joining tape cut to fit. A good new splice lets the tape run and play safely.','It exists to make degraded tapes playable again and to stop weak or oozing splices from breaking the tape or fouling the machine during transfer.','Using a splicing block and archival splicing tape, a technician trims the old join, butts the ends, and applies a new diagonal splice before playing the reel.','Splicing & Repair',ARRAY['Splice failure','Splice bleed','Splicing block','Splicing tape','Leader tape']::text[],ARRAY['Repairing archival tape with pressure-sensitive office tape that bleeds and fails.','Overlapping the tape ends instead of butt-joining them at the correct angle.','UNSAFE: Cleaning old adhesive with flammable or toxic solvents without ventilation and eye protection.']::text[],ARRAY['Replacing dried, failing edit splices on a master before digitisation.','Fitting new leader with a fresh splice after a tape break.','Removing a bleeding splice and rejoining with archival tape.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6d5c7941-dc20-59a3-b033-f249fdf0eb75' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Splice replacement'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6d5c7941-dc20-59a3-b033-f249fdf0eb75','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6d5c7941-dc20-59a3-b033-f249fdf0eb75' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '74a0dbb4-85bd-5207-9b22-a8dab8108368','Spoking','A pack deformation in which radial lines, or spokes, appear across the wound tape when viewed through the reel flange. Excessive winding tension makes pressure from the outer layers compress the inner turns until they develop small radial kinks that align to look like the spokes of a wheel.','Spoking shows up as lines that spread out like the spokes of a wheel. Look through the side of the reel to see them. They form when tape is wound too tight and the inner layers buckle.','Spoking is a visible warning of harmful tape-pack stress; seeing it tells the archivist to rewind the reel at proper tension before the kinks permanently deform the tape.','Noticing spoke lines through a flange, a technician rewinds the reel slowly at correct tension and copies the recording, as the deformation can become permanent.','Wind & Pack Defects',ARRAY['Pack slip','Cinching','Popped strands','Tape pack','Retensioning']::text[],ARRAY['Winding at high tension, which builds the internal pressure that causes spoking.','Ignoring visible spokes until edge stretch and mistracking become permanent.','Rewinding a spoked reel at high speed, which can worsen the deformation.']::text[],ARRAY['Radial lines seen through the flange of a tightly wound archival reel.','A tape spoking after storage through large temperature swings.','Rewinding to relieve stress on a spoked pack before transfer.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='74a0dbb4-85bd-5207-9b22-a8dab8108368' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Spoking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '74a0dbb4-85bd-5207-9b22-a8dab8108368','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='74a0dbb4-85bd-5207-9b22-a8dab8108368' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e92e442d-f056-59f1-9765-3c52c279cc7b','Stack alignment','The adjustment of a tape machine''s magnetic head stack so that the head gaps sit correctly relative to the moving tape and the recorded tracks, setting parameters such as azimuth, zenith, wrap, height, and tangency. Correct stack alignment maximizes high-frequency response, channel-to-channel timing, and track registration during replay or recording.','A tape machine reads tracks with a block of magnetic heads called the head stack. Stack alignment sets the angle and position of that block. Getting it right keeps the sound clear and the tracks lined up.','It exists because a misaligned head loses treble and smears timing between tracks; aligning the stack to the tape recovers full, accurate playback of the original recording.','Before transferring an archival tape, a technician plays a reference tape and adjusts head azimuth for peak high-frequency output and correct interchannel phase.','Playback & Transfer',ARRAY['Azimuth','Head stack','Reference tape','Wow and flutter','Line-up tone']::text[],ARRAY['Setting azimuth by ear on a music tape instead of using a reference tape.','Adjusting only azimuth and ignoring height, zenith, and wrap.','Aligning the machine to a damaged tape and losing the reference for later tapes.']::text[],ARRAY['Peaking head azimuth on an alignment tape before an archival transfer.','Recovering lost treble on a tape recorded on a misaligned machine.','Matching interchannel timing across a multitrack head stack.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e92e442d-f056-59f1-9765-3c52c279cc7b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Stack alignment'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e92e442d-f056-59f1-9765-3c52c279cc7b','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e92e442d-f056-59f1-9765-3c52c279cc7b' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ff457c61-c964-5f4d-ab75-5f485df68e6d','Standard-play tape','Open-reel magnetic tape made on the thickest, most robust base film of the reel-to-reel thickness classes, giving the standard (shortest) playing time for a given reel diameter. Its greater total thickness makes it mechanically stronger and less prone to stretch and print-through than the thinner long-play, double-play, and triple-play tapes that fit more length on the same reel.','Standard-play tape is the normal, thick kind of reel tape. Being thick, it is strong and holds up well. It fits less length on a reel, so it plays for a shorter time than thinner tapes.','Its thicker base trades running time for durability and low print-through, which is why standard-play stock was preferred for masters and archival recordings.','Identifying a reel as standard-play helps a technician expect a robust tape with lower print-through and estimate its running time from reel size and speed.','Tape Format',ARRAY['Long-play tape','Double-play tape','Print-through','Substrate','Base film']::text[],ARRAY['Assuming all reels of one diameter hold the same length, ignoring tape thickness class.','Expecting thin long-play tape to be as strong as standard-play tape.','Confusing playing time with tape speed rather than with tape thickness and length.']::text[],ARRAY['Recognising a short-duration, robust master on standard-play stock.','Estimating running time from reel size, speed, and tape thickness.','Choosing thicker standard-play stock to minimise print-through on a master.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ff457c61-c964-5f4d-ab75-5f485df68e6d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Standard-play tape'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'ff457c61-c964-5f4d-ab75-5f485df68e6d','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ff457c61-c964-5f4d-ab75-5f485df68e6d' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'aa665d6a-5ac5-5147-8057-3c15c188327c','Stepped pack','A wind defect in which groups of tape windings have slipped laterally to different levels, so the flat side of the pack shows distinct steps or tiers rather than a smooth face. It is a form of pack slip caused by uneven tension, loose winding, mechanical shock, or thermal cycling, and it exposes those windings to edge damage on playback.','A well-wound reel has a smooth, flat side. In a stepped pack, blocks of layers have shifted sideways into steps. The stuck-out layers can rub the reel edge and get damaged when the tape plays.','The steps mark windings that have slipped out of line; spotting them tells the archivist to rewind carefully, since those layers can hit the flange and suffer edge damage.','Seeing tiered steps on a pack, a technician rewinds at low, even tension to smooth the wind before running the tape for transfer.','Wind & Pack Defects',ARRAY['Pack slip','Flange pack','Popped strands','Spoking','Cinching']::text[],ARRAY['Playing a stepped pack without rewinding, so slipped layers strike the flange.','Storing reels flat, which lets loose windings slip into steps.','Blaming the steps on the tape rather than on uneven winding tension.']::text[],ARRAY['Stepped tiers on the face of a loosely wound reel.','Layers slipping into steps after shipment or a temperature swing.','Smoothing a stepped pack by controlled rewinding before transfer.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='aa665d6a-5ac5-5147-8057-3c15c188327c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Stepped pack'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'aa665d6a-5ac5-5147-8057-3c15c188327c','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='aa665d6a-5ac5-5147-8057-3c15c188327c' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e64ff93f-a3c0-51b3-ba82-0e63a0843ba9','Stick-slip motion','A cyclic, jerky tape motion in which high friction makes the tape momentarily stick to the head, tension builds until the tape suddenly releases and slips past at speed, then sticks again, repeating rapidly. Common on tapes with binder deterioration, it produces audible squeal and speed instability during playback.','Stick-slip is a stop-and-go, jerky movement of the tape. The tape grips the playback head, then suddenly slips, then grips again, over and over. It often makes a squealing sound as the tape drags.','It signals that friction at the head is too high, usually from binder breakdown; recognizing it warns the technician to treat the tape before playing rather than risk damage.','Hearing squeal and wow from stick-slip, a technician stops, treats the tape for sticky-shed if present, and cleans the path before attempting a transfer.','Tape Degradation',ARRAY['Sticky-shed syndrome','Binder hydrolysis','Squeal','Wow and flutter','Lubricant']::text[],ARRAY['Repeatedly replaying a squealing, sticking tape and shedding more coating each pass.','Treating stick-slip as a machine fault rather than tape binder failure.','UNSAFE: Baking a tape to stop squeal without confirming its base and type, risking damage to acetate or lacquer media.']::text[],ARRAY['A reel squealing and dragging as sticky-shed raises head friction.','Speed wobble and squeal when playing a degraded older tape.','Stopping playback at the first squeal to avoid stripping oxide.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e64ff93f-a3c0-51b3-ba82-0e63a0843ba9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Stick-slip motion'),'[^a-z0-9]','','g'));
