INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '139a34d9-66c3-5a9f-8944-4d3707e96574','Thermal conditioning','The controlled acclimatisation of magnetic tape to the temperature and humidity of the playback or working environment before it is handled or played, especially after removal from cool or cold archival storage. Letting the tape reach equilibrium prevents moisture condensation on cold media and avoids the mechanical stresses that an abrupt temperature change would introduce into the wound pack.','Tapes are often kept in cold storage to make them last. Before playing one, you let it warm up slowly to room temperature first. This is thermal conditioning. It stops water droplets forming on the cold tape and avoids stress from a sudden temperature change.','It protects tape taken from cold storage: gradual warming avoids condensation and the pack stresses that rapid temperature swings would cause.','Pulling a reel from a cold vault, a technician lets it acclimatise for the recommended time before opening the box and playing it.','Handling practice',ARRAY['Substrate shrinkage','Tape relaxation','Archival storage','Cold storage','Print-through']::text[],ARRAY['Playing a cold tape straight from storage, risking condensation and moisture damage to the heads and tape.','Rushing acclimatisation for thick or tightly wound packs that need longer to equilibrate.','Assuming only temperature matters and ignoring humidity equilibration.']::text[],ARRAY['A reel removed from a 5 C vault is left to reach room temperature before playback.','An archive posts acclimatisation times by pack size near its cold store.','A tape is conditioned to the working-room humidity before a transfer session.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='139a34d9-66c3-5a9f-8944-4d3707e96574' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Thermal conditioning'),'[^a-z0-9]','','g'));
