INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c20b56ee-0b62-53b4-885e-b7b588bc1a78','Tissue wiping','A manual cleaning method in which a tape is drawn under light, even pressure through a folded lint-free tissue or cloth (or a pad on a cleaning machine) to lift loose oxide, shed and surface debris as it is slowly wound. It is a gentle, non-abrasive alternative to blade-based tape polishing and is often used after treatment for sticky-shed.','Tissue wiping cleans a tape by gently pulling it through a folded lint-free cloth or tissue as it winds. The cloth catches loose dust and shed bits from the surface. It is soft and does not scrape the recording layer. Archives use it to clean tapes, often after treating sticky ones.','It removes loose surface contamination that would otherwise clog heads and cause dropouts, without abrading the magnetic coating.','After baking a shed-prone master, an engineer wipes it through a lint-free cloth on a slow wind to remove residue before transferring it.','Cleaning method',ARRAY['Tape polishing','Sticky-shed syndrome','Tape baking','Dropout','Oxide shedding']::text[],ARRAY['Using ordinary paper or facial tissue that sheds lint and can scratch the tape; only lint-free material is suitable.','Wiping with heavy pressure, which can strip loose oxide from an already fragile tape.','Cleaning a squealing sticky tape by wiping alone; hydrolysis needs treatment such as baking, not just surface cleaning.']::text[],ARRAY['A freshly baked master is wiped through lint-free cloth to clear binder residue before transfer.','A dusty reel is cleaned on a slow wind through a cleaning pad.','An archivist removes loose shed from a tape to prevent head clogs during digitisation.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c20b56ee-0b62-53b4-885e-b7b588bc1a78' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Tissue wiping'),'[^a-z0-9]','','g'));
