INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b586b269-dbcb-524c-87d0-46b6b2cda632','Torque ripple','A periodic variation in the output torque of a rotating motor over each revolution, arising from cogging (magnetic interaction between the rotor and the stator teeth), commutation, and harmonics in the winding current and back-EMF. In a tape transport, torque ripple in the reel or capstan motors modulates tape tension and speed and so contributes to periodic speed instability such as flutter.','Torque ripple is a small, repeating change in the twisting force a motor makes as it spins. In a tape machine this uneven push makes the tape speed up and slow down a little. That adds wobble to the sound.','The term names a mechanical source of speed instability so engineers can identify, measure, and design it out of transport motors, keeping tape motion smooth. Recognising it helps separate motor-caused flutter from other transport faults.','When a transfer engineer hears periodic flutter that tracks the motor''s rotation, they check for a worn or failing reel or capstan motor whose torque ripple is modulating tension, and service or replace it before transfer.','Tape transport',ARRAY['Wow','Flutter spectrum','Capstan','Scrape flutter','Back tension','Wow-and-flutter profile']::text[],ARRAY['Assuming all flutter comes from the capstan or pinch roller and overlooking reel-motor torque ripple as a source.','Confusing torque ripple, a repeating force variation within each motor revolution, with a steady speed offset.','Believing a quiet, smooth-running motor has no torque ripple; every motor has some cogging and commutation ripple.']::text[],ARRAY['Diagnosing periodic pitch wobble on an archival reel machine that tracks the reel-motor rotation rate.','Evaluating a direct-drive capstan motor whose cogging adds low-level flutter during a preservation transfer.','Servicing a transport whose failing motor''s rising torque ripple has degraded speed stability.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b586b269-dbcb-524c-87d0-46b6b2cda632' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Torque ripple'),'[^a-z0-9]','','g'));
