INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '468e0b70-4e09-5641-a59c-8bbef52b3864','Track-placement error','A misalignment in which the recorded tracks do not lie at the height and spacing across the tape width that the reproduce head expects, so the head gaps do not sit squarely over the recorded tracks. It arises from head-height or track-position differences between the recording and replaying machines, non-standard formats, or head wear, and it lowers replay level and signal-to-noise ratio and can increase crosstalk between channels.','Every recording sits in a stripe, called a track, across the tape. Track-placement error means the play head does not line up with that stripe. When the head misses the stripe, the sound gets quieter and noisier.','Naming this fault lets an archivist recognise when weak or noisy replay comes from track misalignment rather than tape damage, and correct it by adjusting head height or choosing a machine that matches the recording''s format.','Facing low level or high noise, a technician checks track alignment, sometimes by making the tracks visible with fine magnetic powder over a protective overlay, then adjusts head height or selects a matching head block and format.','Head alignment',ARRAY['Azimuth error','Zenith error','Track-width mismatch','Track pitch','Guard track','Head height']::text[],ARRAY['Blaming low replay level on a worn or degraded tape when the head is actually sitting off the recorded track.','Playing a recording on a machine of a different track format without checking that the head lines up with the recorded tracks.','Applying magnetic visualising powder or filings directly to the tape without a protective overlay, leaving particles that can score the heads and tape.']::text[],ARRAY['Transferring an amateur reel recorded on a mis-set consumer deck whose tracks sit off the standard position.','Diagnosing weak, hissy playback that improves when head height is trimmed to match the recorded track.','Deciding which replay machine and head block to use for an unusual multitrack format.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='468e0b70-4e09-5641-a59c-8bbef52b3864' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Track-placement error'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '468e0b70-4e09-5641-a59c-8bbef52b3864','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='468e0b70-4e09-5641-a59c-8bbef52b3864' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '97b7c376-aec1-536f-8b0b-739391418931','Track-width mismatch','A condition in which the width of the reproduce head''s track differs from the width of the track originally recorded, for example replaying a full-track recording on a two-track head or a wide recorded track on a narrower head. The mismatch changes replay level and signal-to-noise ratio and, depending on which is wider, can pick up guard-band noise, adjacent-track crosstalk, or only part of the recorded signal.','Recordings are laid down in stripes of a set width. If the play head''s stripe is a different width from the recorded one, the two do not match. That can make the sound quieter or add noise from beside the track.','The term helps technicians pick a replay head whose track width matches the recording, so the full recorded signal is read at the right level without extra noise or crosstalk.','Before transferring, a technician identifies the tape''s track format and chooses a head block of matching width, for instance a full-track head for a full-track mono tape, rather than defaulting to a two-track head.','Head alignment',ARRAY['Track-placement error','Full-track mono','Half-track stereo','Guard track','Track pitch','Crosstalk']::text[],ARRAY['Replaying a full-track mono recording on a half-track or two-track head, which adds guard-band noise and lowers effective level.','Assuming any stereo head will correctly play any stereo tape, ignoring differences in track width and spacing between formats.','Overlooking that head wear can narrow the effective gap and create a width mismatch even on the correct machine.']::text[],ARRAY['Choosing a full-track replay head to transfer a full-track mono broadcast tape.','Transferring a two-track tape on a quarter-track machine and hearing extra hiss from the unplayed guard areas.','Comparing head blocks to match an unusual instrumentation or multitrack width.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='97b7c376-aec1-536f-8b0b-739391418931' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Track-width mismatch'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '97b7c376-aec1-536f-8b0b-739391418931','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='97b7c376-aec1-536f-8b0b-739391418931' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '67e18541-1893-5396-98a5-0b6d4bbce989','Transverse curl','A deformation in which the tape curves across its width, the transverse or cross-web direction, so that in cross-section it is cupped rather than flat. It results from uneven stresses or dimensional change between the base film and the coating layers, and it lifts parts of the tape away from the head, causing poor head-to-tape contact, level loss, and dropouts.','Transverse curl means the tape curves from edge to edge, like a shallow gutter, instead of lying flat. The curved tape cannot press evenly on the play head. That causes weak spots and dropouts in the sound.','Identifying transverse curl explains a class of contact-related replay faults and points to remedies such as gentle reconditioning, controlled tension, and stable storage that keep the tape flat against the head.','When replay shows unstable level and dropouts, a technician inspects the tape for cupping across its width and may lower tape tension or recondition and respool the tape to improve head contact.','Carrier degradation',ARRAY['Wind-induced edge curl','Cupping','Substrate deformation','Dropout','Physical tape memory','Back tension']::text[],ARRAY['Mistaking dropouts caused by cupping for magnetic-coating loss, and cleaning or re-transferring without fixing head contact.','Forcing higher tension to flatten a cupped tape, which can stretch or crease the base film.','UNSAFE: Trying to flatten curled or brittle tape with heat or solvents without expert guidance, which can deform or contaminate the tape.']::text[],ARRAY['Replaying a poorly stored reel that has cupped across its width and no longer contacts the head evenly.','Diagnosing intermittent high-frequency dropouts traced to cross-width curl rather than oxide loss.','Assessing a tape''s playability before transfer by checking for flatness across its width.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='67e18541-1893-5396-98a5-0b6d4bbce989' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Transverse curl'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '67e18541-1893-5396-98a5-0b6d4bbce989','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='67e18541-1893-5396-98a5-0b6d4bbce989' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b95f47af-0863-5fb7-8bc6-d9b1f781e868','Transverse vibration','Oscillation of the moving tape in a direction perpendicular to its line of travel, either laterally across the width or out of the plane of the tape, typically excited in the unsupported span between guides or heads. It can modulate head-to-tape contact and tracking, contributing to flutter, added noise, and level modulation.','As tape runs through the machine, the free length between guides can shake sideways or in and out. This is transverse vibration, shaking across the direction of travel. It can unsettle contact with the head and add wobble or noise.','The term names a mechanical cause of flutter and tracking noise so engineers can damp it, by supporting the tape span, adding or adjusting guides, and controlling tension.','A technician chasing flutter or a rushing noise checks for a long unsupported tape span or a resonating guide and adjusts guiding and tension to damp the transverse motion.','Speed stability',ARRAY['Scrape flutter','Flutter spectrum','Wow','Tape guide','Back tension','Tape-path resonance']::text[],ARRAY['Confusing transverse vibration, motion across the direction of travel, with scrape flutter, which is stick-slip along the direction of travel.','Ignoring long unsupported tape spans, which are free to vibrate and add flutter and noise.','Assuming vibration is always inside the machine and overlooking building or airborne vibration reaching the transport.']::text[],ARRAY['Tracing a rushing or fluttery artefact to a resonating tape span on a transfer deck.','Adding or adjusting guides to damp lateral tape motion before an archival transfer.','Isolating a transport from floor vibration in a busy transfer studio.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b95f47af-0863-5fb7-8bc6-d9b1f781e868' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Transverse vibration'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b95f47af-0863-5fb7-8bc6-d9b1f781e868','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b95f47af-0863-5fb7-8bc6-d9b1f781e868' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1623dc07-7901-5988-a52c-e4019ca6ede1','Triple-play tape','Magnetic tape made on an extra-thin base film so that roughly three times the standard length fits on a given reel or cassette hub, giving about three times the playing time. The reduced base and total thickness make triple-play tape more prone to print-through, stretching, curling, and mechanical damage than standard-play tape.','Triple-play tape is much thinner than normal tape. Because it is thin, about three times as much fits on the same reel. The trade-off is that thin tape stretches, prints faint echoes, and tears more easily.','Extra-thin tape was made to extend recording time without larger reels; for preservation the term flags a fragile carrier that needs gentle handling and low tension and is more likely to show print-through.','On meeting a long-playing thin tape, a transfer technician uses low tape tension and careful handling, expects possible print-through and stretch, and rewinds several times to reduce print before transfer.','Tape stock',ARRAY['Print-through ratio','Long-play tape','Substrate deformation','Base film','Wind-induced edge curl','Back tension']::text[],ARRAY['Treating thin triple-play tape like standard tape and running it at high tension, which can stretch or crease it.','Not expecting print-through on thin long-play tapes, whose closely spaced thin layers print more readily.','Assuming a full-feeling reel holds a short recording; thin tape can hold a very long programme.']::text[],ARRAY['Handling a consumer long-play reel recorded on extra-thin base for a family-archive transfer.','Diagnosing pronounced pre- and post-echo on a thin long-play tape.','Choosing low-tension replay settings for a fragile triple-play cassette.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1623dc07-7901-5988-a52c-e4019ca6ede1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Triple-play tape'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '1623dc07-7901-5988-a52c-e4019ca6ede1','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1623dc07-7901-5988-a52c-e4019ca6ede1' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c33eccab-a6e3-5ba8-a677-9863ecfc6221','Vacuum cleaning','A cleaning method in which loose surface dust, debris, and mould spores are removed from tape and equipment using gentle suction, usually a low-power, HEPA-filtered vacuum combined with a soft brush, before the tape is spooled or transferred. It removes contaminants that would otherwise abrade the tape, clog heads, or cause dropouts, without solvents or scraping of the coating.','Vacuum cleaning uses gentle suction, often with a soft brush. It lifts loose dust and mould off tape before you play it. It clears grit that would scratch the tape or clog the heads. It does not use liquids or scrape the surface.','Gentle vacuuming removes abrasive dust and biohazardous mould spores so the tape can be played and transferred safely, protecting both the recording and the replay heads from contamination.','Before spooling a dusty or mould-affected reel, a technician brushes and vacuums loose debris with a HEPA-filtered vacuum, wearing protection for mouldy items, then, if needed, runs the tape on a cleaning machine.','Conservation treatment',ARRAY['Tape cleaning machine','Mould remediation','Dropout','Sticky-shed syndrome','Head cleaning','Dust and debris']::text[],ARRAY['Using a strong household vacuum, whose high suction can pull at loose tape or edges, instead of a low-suction HEPA-filtered unit.','UNSAFE: Vacuuming or handling mould-contaminated tape without a HEPA-filtered vacuum, gloves, and respiratory protection in a contained, ventilated area; mould spores are a health hazard.','UNSAFE: Blowing dust off mouldy tape by mouth or with compressed air, which spreads biohazardous spores into the air and onto other tapes.','Relying on vacuuming to fix squeal or shedding, which are chemical binder problems, not loose dust.']::text[],ARRAY['Removing loose surface mould from a stored reel before assessing and transferring it.','Clearing dust from an open-reel tape and its box before spooling on a cleaning machine.','Preparing dusty cassettes for transfer without carrying grit onto the heads.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c33eccab-a6e3-5ba8-a677-9863ecfc6221' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vacuum cleaning'),'[^a-z0-9]','','g'));
