WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c33eccab-a6e3-5ba8-a677-9863ecfc6221' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9eaee0ca-b042-5565-90b9-7b3f7c5bb826','Vinegar syndrome','The degradation of cellulose-acetate tape and film base, in which the acetate reacts with moisture to release acetic acid, producing a vinegar-like odour. The reaction is autocatalytic, since released acid speeds further breakdown, and it makes the base brittle and causes it to shrink and deform, hindering head contact and eventually threatening the recording.','Older tapes made from acetate can break down over time. As they do, they give off acetic acid, which smells like vinegar. The tape then gets brittle, shrinks, and warps, which makes it hard to play.','Recognising the vinegar smell and brittleness lets an archivist spot acetate-base decay early, isolate affected tapes, store them cold and dry to slow the reaction, and prioritise them for transfer before they become unplayable.','An archivist who smells vinegar or finds brittle, cupped acetate tape segregates it from healthy items, stores it cold and dry, and moves it up the transfer queue, replaying it gently on a low-tension machine.','Carrier degradation',ARRAY['Acetate base','Cellulose acetate','Sticky-shed syndrome','Substrate deformation','Cold storage','Print-through ratio']::text[],ARRAY['Storing vinegar-syndrome acetate tapes among healthy tapes; the acetic acid they give off can speed decay in neighbours.','Confusing vinegar syndrome, an acetate base breaking down with a vinegar smell, with sticky-shed syndrome, a polyester binder taking up water.','UNSAFE: Attempting home chemical re-plastification or solvent treatments on brittle acetate tape, which can destroy the tape and contaminate replay equipment and other tapes.','UNSAFE: Handling large quantities of strongly off-gassing acetate tape without ventilation; concentrated acetic-acid vapour irritates the eyes and airways.']::text[],ARRAY['Surveying a collection and finding boxes of old acetate reels giving off a vinegar smell.','Deciding to cold-store and fast-track transfer of acetate tapes showing early acetic decay.','Gently transferring a brittle acetate tape on a low-tension machine, splicing breaks rather than stretching it.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9eaee0ca-b042-5565-90b9-7b3f7c5bb826' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vinegar syndrome'),'[^a-z0-9]','','g'));
