SELECT '9eaee0ca-b042-5565-90b9-7b3f7c5bb826','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9eaee0ca-b042-5565-90b9-7b3f7c5bb826' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '70750fb6-5563-5efb-9a6f-5212ee497ad9','Wind-induced edge curl','Curl or waviness at the edge of the tape produced by the stresses of winding, such as uneven or excessive pack tension, poor wind quality, or dimensional change while wound, so that the edges deform rather than lying flat. The curled edge makes uneven head contact, can foul guides and reel flanges, and threatens edge tracks and outer channels.','How a tape is wound puts stress on its edges. Too much or uneven winding can make the edges curl or ripple instead of staying flat. Curled edges rub on guides and lift off the head, hurting the sound near the edge.','The term links a common edge deformation to its cause, winding stress, pointing to remedies such as rewinding at correct, even tension with good pack quality, and stable storage.','Seeing rippled or curled edges on a reel, a technician rewinds the tape at a controlled, even tension to improve the pack and reduce edge deformation, then checks edge-track playback before transfer.','Carrier degradation',ARRAY['Transverse curl','Pack slip','Popped strand','Cinching','Edge damage','Back tension']::text[],ARRAY['Fast-winding a tape unevenly, which builds edge stress and can leave the edges curled or wavy.','Ignoring curled edges and blaming edge-track dropouts on the recording rather than on head contact.','Storing tapes wound at poor or uneven tension, letting edge deformation set in over time.']::text[],ARRAY['Finding wavy, curled edges on a reel that was stored after a fast, uneven wind.','Losing level on an edge track because the curled edge lifts off the head.','Retensioning a badly wound reel to improve pack quality before archival transfer.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='70750fb6-5563-5efb-9a6f-5212ee497ad9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Wind-induced edge curl'),'[^a-z0-9]','','g'));
