SELECT '70750fb6-5563-5efb-9a6f-5212ee497ad9','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='70750fb6-5563-5efb-9a6f-5212ee497ad9' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ffce6568-b172-52d2-b1bc-d1009e6f8352','Wow','Slow, periodic variation in the reproduced pitch of a recording caused by low-rate fluctuations in tape or disc speed, conventionally the speed-variation components below roughly a few hertz. It is the low-frequency part of the speed-instability continuum whose faster components are called flutter, and it is heard as a slow wavering of pitch.','Wow is a slow rise and fall in pitch when a tape or record plays. It happens when the speed drifts up and down slowly, a few times a second or less. You hear it most on long, steady notes, which seem to waver.','Naming and measuring wow lets engineers judge and correct slow speed instability, which is kept separate from faster flutter because the ear responds differently to slow and fast pitch changes.','Hearing slow pitch waver, a transfer engineer checks the capstan, pinch roller, bearings, and tape pack and measures wow against a steady reference tone to confirm the transport is within specification.','Speed stability',ARRAY['Flutter','Wow-and-flutter profile','Flutter spectrum','Weighted wow and flutter','Capstan','Speed error']::text[],ARRAY['Confusing wow, a slow pitch waver, with flutter, a faster roughness or gargle; they occupy different rate ranges.','Assuming audible wow always means a faulty tape, when a worn capstan, pinch roller, or dirty transport is often the cause.','Judging wow only by ear instead of measuring the speed variation of a standard reference tone.']::text[],ARRAY['Hearing a piano note slowly waver in pitch during an archival reel transfer.','Checking a machine''s wow figure against specification during routine alignment.','Tracing slow pitch instability to a slipping or eccentric pinch roller.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ffce6568-b172-52d2-b1bc-d1009e6f8352' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Wow'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'ffce6568-b172-52d2-b1bc-d1009e6f8352','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ffce6568-b172-52d2-b1bc-d1009e6f8352' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b167610f-1f4c-5c20-aaa9-b7df3082140c','Wow-and-flutter profile','A characterisation of a transport''s or tape''s speed instability that shows how wow and flutter vary, rather than a single figure: typically the time history of the speed deviation and its distribution across modulation rates, or spectrum. The profile reveals patterns such as flutter rising toward the reel hub, periodic components tied to specific rotating parts, or changes during warm-up.','Instead of one number, a wow-and-flutter profile shows how the speed wobble changes over time or by rate. It can reveal, for example, that the wobble grows near the reel centre. That helps point to the cause.','A profile turns a single wow-and-flutter figure into a diagnostic picture, letting engineers match speed-variation patterns to their mechanical sources and judge stability across a whole reel or session.','An engineer logs speed variation across a full reel, or views its spectrum, to see whether flutter peaks tie to the capstan or reel rate or worsen toward the hub, which guides what to service.','Measurement & metrology',ARRAY['Wow','Flutter spectrum','Weighted wow and flutter','Speed error','Capstan-rate component','Reel-rate component']::text[],ARRAY['Judging a machine by a single peak wow-and-flutter number and missing patterns that a profile would reveal.','Ignoring how flutter can change across a reel, often rising near the hub, when assessing a transport.','Confusing the flutter spectrum, variation by rate, with the time history, variation over time; a full profile can include both.']::text[],ARRAY['Plotting speed variation across an entire reel to see flutter increase toward the hub.','Using a flutter spectrum to tie a periodic component to the capstan or a specific idler.','Comparing before-and-after profiles to confirm a transport service reduced flutter.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b167610f-1f4c-5c20-aaa9-b7df3082140c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Wow-and-flutter profile'),'[^a-z0-9]','','g'));
