SELECT 'b167610f-1f4c-5c20-aaa9-b7df3082140c','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b167610f-1f4c-5c20-aaa9-b7df3082140c' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '231367d1-c5b0-53e6-a397-2b535a04f13c','Zenith error','A tape-head alignment fault in which the head is tilted forward or backward relative to the tape, its face not standing perpendicular to the tape in the plane of tape travel, so that the top or bottom edge of the head presses harder than the other. This uneven fore-and-aft tilt, the head''s zenith, disturbs even head-to-tape contact across the head''s height, degrading level and consistency and interacting with azimuth and tracking.','A play head should stand straight up and down against the tape. Zenith error means the head leans forward or backward. Then the top or bottom of the head presses too hard, so contact is uneven and the sound suffers.','Correct zenith keeps the head face square to the tape so contact pressure is even across its height; naming zenith error lets a technician tell this tilt apart from azimuth or height faults during alignment.','During head alignment a technician sets zenith so the head stands perpendicular to the tape, often with alignment gauges or by checking for even contact, before fine-tuning azimuth and height for best output.','Head alignment',ARRAY['Azimuth error','Track-placement error','Head wrap','Tangency','Head height','Head-to-tape contact']::text[],ARRAY['Adjusting azimuth to chase a problem that is really zenith, an unsquare fore-and-aft head tilt.','Assuming only azimuth matters and skipping zenith and tangency when aligning a head.','Forcing a head hard against the tape to improve contact, which changes zenith and wears the head unevenly.']::text[],ARRAY['Aligning a reel machine''s head block and finding uneven contact traced to head tilt.','Setting up a cassette deck whose poor, uneven output improves after correcting zenith.','Servicing a worn head whose uneven face points to a long-standing zenith error.']::text[],'be9c2311-f9c7-4657-b34e-a2eee81eaf9e'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='231367d1-c5b0-53e6-a397-2b535a04f13c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Zenith error'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '231367d1-c5b0-53e6-a397-2b535a04f13c','be9c2311-f9c7-4657-b34e-a2eee81eaf9e',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='231367d1-c5b0-53e6-a397-2b535a04f13c' AND gt.achievement_id='be9c2311-f9c7-4657-b34e-a2eee81eaf9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e48c69c9-8da5-57df-9abf-64bc203e7785','Anticipatory ducking','A ducking process in which a look-ahead delay lets the level-reducing action begin just before the triggering signal actually arrives, so the gain reduction is already in place when the trigger, such as a voice-over, starts. The detector reads the side-chain a few milliseconds ahead of the delayed main path, giving smooth, click-free attenuation of the ducked material.','Ducking makes background music drop when someone talks. Anticipatory ducking looks a tiny bit ahead in time. So the music dips just before the voice starts, not late. This keeps the change smooth.','It exists to make automatic level dips sound natural and timely, avoiding the audible late catch of a duck that only reacts after the trigger has begun. Look-ahead removes the lag built into simple reactive detection.','A broadcast or podcast engineer sets a look-ahead time on a ducker so music or ambience gently gives way to narration exactly as the presenter speaks, with no clipped first word.','Ducking',ARRAY['Ducking','Side-chain','Look-ahead','Attack time','Release time','Gain reduction']::text[],ARRAY['Setting the look-ahead too long, so the music dips noticeably before the presenter actually speaks.','Confusing ducking, which lowers a second signal, with compression that acts on the signal''s own level.','Forgetting that look-ahead adds latency to the main path, which must be compensated elsewhere in the chain.']::text[],ARRAY['Lowering music under a radio or podcast host''s voice so speech stays intelligible.','Dipping game or ambience beds beneath announcements or dialogue in post-production.','Automatically pulling a music bed down as a voice-over enters in an advert.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e48c69c9-8da5-57df-9abf-64bc203e7785' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Anticipatory ducking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e48c69c9-8da5-57df-9abf-64bc203e7785','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e48c69c9-8da5-57df-9abf-64bc203e7785' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '87c9cc49-fefd-51fd-b5d0-4b31a60c33b6','Automatic-release compression','Compression in which the release time is not a fixed user setting but is varied automatically by the compressor in response to the program material, typically shortening for brief transients and lengthening for sustained level changes. Also called program-dependent or auto release, it aims to combine fast recovery on transients with slow, unobtrusive recovery on steady passages.','A compressor turns loud sounds down, then lets go, called release. Automatic release means the compressor picks the let-go speed for you. It reacts fast to short spikes and slow to long loud parts. This helps it sound smooth on many sounds.','It exists to reduce audible pumping and setup effort by adapting recovery time to the signal, so one setting behaves well across varied dynamics. This makes compressors more forgiving on unpredictable sources.','An engineer selects the auto or program-dependent release mode on a bus or vocal compressor when the material''s dynamics vary too much for a single fixed release to track cleanly.','Compression',ARRAY['Release time','Attack time','Program-dependent','Compression ratio','Pumping','Bus compression']::text[],ARRAY['Assuming auto release always sounds best and never trying a well-chosen fixed release for rhythmic control.','Expecting identical results across compressors, since each brand''s auto-release algorithm behaves differently.','Blaming pumping on a fixed release without switching to the automatic mode to test the difference.']::text[],ARRAY['Compressing a lead vocal whose loudness jumps between quiet verses and belted choruses.','Gluing a mix bus where varied program material defeats a single fixed release time.','Taming a dynamic bass part that a fixed release either strangles or lets pump.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='87c9cc49-fefd-51fd-b5d0-4b31a60c33b6' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Automatic-release compression'),'[^a-z0-9]','','g'));
