WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6bb4e5d4-30b7-560a-8937-bb9c99500c6e' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8a5b14f0-7d3e-552d-a938-557bc1b3556c','Bite','An informal, subjective descriptor for an aggressive, cutting quality in a sound, associated with strong attack and energy in the upper-midrange presence region, which makes an instrument or voice sound forward, edgy, and articulate. Engineers speak of adding bite when they want a source to cut through a mix with more attack and definition.','Bite describes a sharp, aggressive edge in a sound. A guitar or snare with bite feels punchy and cuts through the mix. It comes from strong attack and upper-middle frequencies. Think of the snap of a hard-hit drum.','The term gives engineers a shared word for a forward, attacking tonal quality they may add or reduce with equalization, saturation, or dynamics. Naming it helps communicate a mix goal quickly.','To make a guitar or snare cut through, an engineer boosts the upper-mid presence region or adds mild saturation to give the source more bite.','Tonal description',ARRAY['Presence','Attack','Character equalization','Transient','Saturation','Edge']::text[],ARRAY['Adding so much upper-mid bite that the source becomes harsh and fatiguing.','Treating bite as one fixed frequency rather than a broad, source-dependent quality.','Chasing bite while soloed and ignoring how the source already cuts within the full mix.']::text[],ARRAY['Making a rhythm guitar cut through a dense rock mix.','Adding attack and edge to a snare so it reads on small speakers.','Giving a lead vocal more forward presence so it sits on top.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8a5b14f0-7d3e-552d-a938-557bc1b3556c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bite'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '8a5b14f0-7d3e-552d-a938-557bc1b3556c','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8a5b14f0-7d3e-552d-a938-557bc1b3556c' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '329a21d3-f314-57e8-ac10-fdcd152a7195','Boost-and-sweep method','An equalization technique for locating a specific frequency, in which the engineer sets a band to a narrow bandwidth and a large boost, then sweeps its centre frequency across the spectrum until the target feature, usually a resonance or problem tone, is strongly exaggerated and easy to hear, before applying the intended cut or boost at that frequency. It is also known as sweep and destroy or search and destroy.','This is a way to find an exact problem frequency. You make a narrow equalizer band, boost it a lot, then slide it up and down. The problem tone jumps out loudly when you land on it. Then you cut that spot.','It exists to help an engineer reliably find an offending or resonant frequency by ear, rather than guessing, so corrective equalization can be aimed precisely. The exaggeration makes subtle problems obvious.','To remove a ringing resonance on a tom or a boxy tone on a guitar, an engineer boost-sweeps to pinpoint the frequency, then cuts it with a suitable bandwidth.','Equalization',ARRAY['Equalization','Q (bandwidth)','Resonance','Parametric EQ','Notch filter','Complementary equalization']::text[],ARRAY['Leaving the large boost in place instead of returning it to a cut once the frequency is found.','UNSAFE: sweeping a high-gain narrow boost while monitoring loudly can create sudden painful peaks and risk hearing damage; keep monitoring levels moderate.','Using too wide a bandwidth, so several frequencies rise together and the exact target is unclear.']::text[],ARRAY['Finding and notching a ringing resonance on a drum shell.','Locating a boxy or honky frequency on an acoustic guitar.','Identifying feedback-prone frequencies on a live vocal channel.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='329a21d3-f314-57e8-ac10-fdcd152a7195' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Boost-and-sweep method'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '329a21d3-f314-57e8-ac10-fdcd152a7195','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='329a21d3-f314-57e8-ac10-fdcd152a7195' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8241fbfa-b0e4-5480-972b-1fc39f93f7ad','Broad-stroke equalization','Equalization applied with wide bandwidth (low Q) and gentle gain over broad frequency regions to shape the overall tonal balance, as opposed to narrow, surgical moves aimed at single frequencies. Broad-stroke EQ addresses general tendencies such as overall warmth, brightness, or fullness rather than specific problem tones.','Broad-stroke equalization shapes the general tone of a sound. It uses wide, gentle boosts or cuts, not sharp ones. You use it to make something warmer or brighter overall. It is like adjusting the big picture, not tiny details.','It exists to set the general tonal character of a source or mix in a musical way, since wide gentle curves tend to sound smoother than narrow ones. It complements surgical equalization used for specific fixes.','An engineer uses a wide, low-Q shelf or bell to add overall air or warmth to a mix, reserving narrow bands for pinpoint problem-solving.','Equalization',ARRAY['Equalization','Q (bandwidth)','Shelving filter','Surgical equalization','Character equalization','Tonal balance','Contour equalization (near-synonym; both are wide, gentle, low-Q tonal shaping, but contour EQ additionally covers fixed loudness/contour curves)']::text[],ARRAY['Using a narrow, surgical band where a wide, gentle curve would sound more natural.','Applying large broad boosts that raise overall level and mislead the ear into hearing improvement.','Confusing broad tonal shaping with corrective equalization aimed at removing a single problem frequency.']::text[],ARRAY['Adding general warmth to a whole mix with a wide low shelf.','Brightening a dull vocal with a broad high boost.','Shaping the overall tone of a mix bus before detailed equalizer moves.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8241fbfa-b0e4-5480-972b-1fc39f93f7ad' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Broad-stroke equalization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '8241fbfa-b0e4-5480-972b-1fc39f93f7ad','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8241fbfa-b0e4-5480-972b-1fc39f93f7ad' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0afa098a-3ece-56f1-b8c7-61c81be6ffb1','Cascaded compression','A technique in which two or more compressors are placed in series so the total gain reduction is shared between them, each applying a modest amount, rather than one compressor doing all the work. Also called serial compression — distinct from ''Compression staging'', which distributes compression across channel, group and bus stages — it can sound more transparent and can combine complementary behaviours, such as a slow compressor for level-riding followed by a fast one for peak control.','Cascaded compression uses two or more compressors in a row. Each one turns the sound down just a little. Together they do the job more gently than one working hard. This can sound smoother and more controlled.','It exists to spread dynamic control across stages so no single compressor is pushed into obvious artefacts, and to blend the characters of different compressors. The result is often smoother, more natural control.','On a vocal, an engineer may run a slow opto-style compressor for gentle level-riding into a faster compressor for catching peaks, each taking only a few decibels.','Compression',ARRAY['Compression','Serial processing','Gain reduction','Attack time','Release time','Bus compression']::text[],ARRAY['Setting each stage for heavy reduction, so the stacked effect over-compresses and sounds squashed.','Using two identical compressors and settings, which gains little over one and just doubles any artefacts.','Losing track of total gain reduction across stages and crushing the dynamics unintentionally.']::text[],ARRAY['Combining a slow leveller and a fast peak compressor on a lead vocal.','Sharing gain reduction across two bus compressors for transparent glue.','Stacking compressors to blend two distinct tonal characters on a bass.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0afa098a-3ece-56f1-b8c7-61c81be6ffb1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cascaded compression'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '0afa098a-3ece-56f1-b8c7-61c81be6ffb1','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0afa098a-3ece-56f1-b8c7-61c81be6ffb1' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '281501c4-02b8-51e8-8077-0e9e45a3852e','Character equalization','Equalization applied to impart a desired tonal colour or character to a sound rather than to correct a specific problem, often using equalizers whose circuits or curves add pleasing colouration. It shapes the aesthetic identity of a source, for example adding vintage warmth or sheen, as distinct from corrective EQ that removes faults.','Character equalization shapes the mood or colour of a sound. It is used to make something warmer, richer, or brighter on purpose. This is different from fixing a problem. Special coloured equalizers are often chosen for this.','It exists to give a source a deliberate tonal personality that suits the music, adding vibe rather than solving a fault. It is a creative, taste-driven use of equalization.','An engineer patches a vintage-style equalizer across a vocal or drum bus to add warmth or air, choosing it for its sound rather than to fix a specific frequency.','Equalization',ARRAY['Equalization','Corrective equalization','Broad-stroke equalization','Saturation','Tonal balance','Bite']::text[],ARRAY['Confusing character equalization, used for colour, with corrective equalization used to remove specific problems.','Adding so much colour that several tracks clash tonally in the full mix.','Assuming an expensive coloured equalizer improves a source that actually needs a corrective cut.']::text[],ARRAY['Adding vintage warmth to a vocal with a coloured equalizer.','Giving a drum bus extra sheen and weight for a genre''s sound.','Shaping the tonal identity of a synth to fit a track''s aesthetic.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='281501c4-02b8-51e8-8077-0e9e45a3852e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Character equalization'),'[^a-z0-9]','','g'));
