SELECT '281501c4-02b8-51e8-8077-0e9e45a3852e','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='281501c4-02b8-51e8-8077-0e9e45a3852e' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7ebea9b3-2b5b-5656-afad-540925a4dddc','Character-before-control processing','A signal-chain ordering approach in which colour- or character-adding processes, such as saturation or a coloured compressor or equalizer used for tone, are placed before the clean, controlling dynamics stage, so the final controller tames any peaks or level changes the character stage introduces. The idea is to commit to the desired tone first, then keep it under level control.','This is about the order of your effects. You put the tone-shaping, colourful effects first. Then you put a clean compressor or limiter last. That final stage controls any loud peaks the colour added. So you get the sound you want, kept under control.','It exists to ensure the last stage in the chain reliably manages level and peaks, rather than a colouring stage undoing that control by adding energy afterwards. Order decides what each stage actually hears.','An engineer places saturation and a character compressor before a transparent peak limiter, so the limiter catches the extra peaks the coloured stages create.','Signal chain',ARRAY['Signal chain','Saturation','Cascaded compression','Limiter','Character equalization','Gain staging','Control-before-character processing (reverse ordering — control/dynamics first, then tone/character)']::text[],ARRAY['Placing a colouring or saturating stage after the final limiter, which can push levels back over the ceiling.','Ignoring how each stage changes the signal the next stage receives.','Assuming effect order does not matter, when it strongly shapes the result.']::text[],ARRAY['Ordering saturation before a peak limiter on a mix bus.','Placing a coloured vocal compressor ahead of a clean leveller.','Building a mastering chain where tone tools precede the final control stage.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7ebea9b3-2b5b-5656-afad-540925a4dddc' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Character-before-control processing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '7ebea9b3-2b5b-5656-afad-540925a4dddc','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7ebea9b3-2b5b-5656-afad-540925a4dddc' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '72357fe2-f73c-5c95-a349-f4635a751f5c','Clip-to-limit chain','A peak-control and loudness technique in which a clipper is placed ahead of a limiter, so the clipper shaves the sharpest, briefest transient peaks and the following limiter handles the remaining level, sharing the work between them. Because the limiter then has less peak energy to catch, it can act more gently, allowing higher loudness with fewer pumping artefacts than limiting alone.','This chain uses a clipper first, then a limiter. The clipper trims the sharpest, quickest peaks. The limiter then has less work to do and reacts more gently. Together they let a track get louder with fewer side effects.','It exists to raise loudness while keeping peaks in check, by handing the hardest, shortest transients to a clipper and the rest to a limiter, reducing the audible distortion or pumping either would cause alone. It is a common modern mastering strategy.','A mastering engineer sends a mix through a gentle clipper to tame transient spikes, then into a limiter for the final ceiling, balancing loudness against distortion.','Loudness processing',ARRAY['Clipping','Limiter','True-peak','Loudness','Cascaded compression','Gain reduction']::text[],ARRAY['Clipping too hard before the limiter, adding obvious distortion in pursuit of loudness.','Ignoring inter-sample (true-peak) overs that can appear after the limiter on conversion.','UNSAFE: judging loudness by turning monitors up to damaging levels for long periods risks permanent hearing loss; keep monitoring levels moderate and follow occupational noise-exposure limits.']::text[],ARRAY['Maximising loudness on a master while controlling transient spikes.','Taming sharp drum transients before final limiting.','Meeting a loudness target for streaming without heavy limiter pumping.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='72357fe2-f73c-5c95-a349-f4635a751f5c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Clip-to-limit chain'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '72357fe2-f73c-5c95-a349-f4635a751f5c','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='72357fe2-f73c-5c95-a349-f4635a751f5c' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '54b4373e-769a-5325-8c74-8504164556dc','Collision-frequency control','The practice of identifying and managing frequency regions where two or more sources overlap and mask one another, their collision frequencies, and reducing that clash so each source stays clear. It is achieved with complementary EQ, dynamic EQ, or frequency-selective side-chaining that lowers one source''s energy in the shared region when needed.','Different instruments can fight over the same frequencies. That overlap makes the mix muddy and unclear. Collision-frequency control finds those clashing spots. Then you gently lower one source there so both stay clear.','It exists to reduce masking, where one sound hides another in a shared frequency range, so each element keeps its place and clarity in a crowded mix. Managing these overlaps is central to a clean balance.','When a kick and bass clash in the low end, an engineer carves a small dip in one where they collide, or uses dynamic EQ or side-chaining to open space for the other.','Frequency management',ARRAY['Frequency masking','Complementary equalization','Dynamic equalization','Side-chain','Boost-and-sweep method','Tonal balance']::text[],ARRAY['Boosting both clashing sources to make each louder, which worsens the collision and the mud.','Cutting too widely and thinning a source instead of making a small, targeted dip.','Fixing collisions only in solo, ignoring how the sources actually mask each other together.']::text[],ARRAY['Separating kick and bass that clash in the low frequencies.','Making room for a vocal against a guitar sharing the same midrange.','Clearing overlap between two synths occupying the same band.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='54b4373e-769a-5325-8c74-8504164556dc' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Collision-frequency control'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '54b4373e-769a-5325-8c74-8504164556dc','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='54b4373e-769a-5325-8c74-8504164556dc' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'fda689c4-b618-5546-a85a-d74aa14e57a2','Complementary equalization','A mixing technique in which the same frequency region is boosted on one source and cut on another, so the two curves complement each other and the sources interlock without masking. Also called mirror or complementary-cut EQ, it is a key tool for carving space between competing elements.','Complementary equalization shapes two sounds so they fit together. You boost a range on one source and cut the same range on the other. Where one is loud, the other steps back. This lets both be heard clearly.','It exists to reduce masking between sources that share frequencies, by making room in one where the other is emphasised, so each keeps its own space in the mix. It creates separation without simply raising level.','To seat a vocal over a guitar, an engineer boosts the vocal''s key presence range and cuts the same range on the guitar so the two lock together.','Equalization',ARRAY['Equalization','Frequency masking','Collision-frequency control','Boost-and-sweep method','Broad-stroke equalization','Tonal balance','Complementary pre/post equalization (different technique — boost before and cut after one processor, not matched boost/cut across two sources)']::text[],ARRAY['Making large opposing boosts and cuts that leave both sources sounding unnatural.','Applying complementary equalization in solo, so the interlocking benefit cannot be judged.','Cutting a source so hard for space that it loses its own tonal identity.']::text[],ARRAY['Fitting a lead vocal and rhythm guitar into the same midrange.','Separating kick and bass by mirroring a boost and a cut in the lows.','Carving room for two synths that share a frequency range.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='fda689c4-b618-5546-a85a-d74aa14e57a2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Complementary equalization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'fda689c4-b618-5546-a85a-d74aa14e57a2','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='fda689c4-b618-5546-a85a-d74aa14e57a2' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '607cf6aa-3870-560e-a430-d41d5782aaf7','Complementary pre/post equalization','An equalization strategy in which a frequency region is deliberately boosted (or cut) before a processor and the reciprocal cut (or boost) is applied after it, so the two curves are inverses of each other. The pre-equalizer changes what the intervening level-dependent or nonlinear processor acts on, while the post-equalizer restores the overall tonal balance, leaving the response nominally flat but altering how the processor responded.','You boost a frequency before a processor, then cut the same amount after it. The overall tone ends up about the same. But the processor reacts more strongly to that boosted range.','It lets an engineer bias a compressor''s detector, a saturator, or a tape emulation toward or away from chosen frequencies without permanently changing the tone, because the post-equalizer undoes the tilt. It separates how a processor is driven from how the final result sounds.','An engineer boosts the vocal presence range into a compressor''s detector, then cuts the same range after it, so the compressor reacts more there while the final balance stays natural.','Equalization technique',ARRAY['Compression-into-EQ','Corrective equalization','Side-chain equalization','De-essing','Contour equalization','Makeup gain','Complementary equalization (different technique — matched boost/cut across two sources, not boost-before/cut-after one processor)']::text[],ARRAY['Making the post-equalizer curve not the exact inverse of the pre-equalizer, so the tone is left permanently tilted instead of neutral.','Assuming the technique changes the final tone; its point is to change how the processor reacts, not the overall balance.','Boosting so hard before the processor that the added gain overloads the processor''s input or the next stage.']::text[],ARRAY['Driving a compressor''s detector harder in the vocal presence range, then cutting that range back to keep the tone natural.','Pushing selected frequencies into a saturator for harmonics, then restoring a flat response afterward.','Setting up frequency-selective compression on a mix bus without changing the mix''s tonal balance.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='607cf6aa-3870-560e-a430-d41d5782aaf7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Complementary pre/post equalization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '607cf6aa-3870-560e-a430-d41d5782aaf7','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='607cf6aa-3870-560e-a430-d41d5782aaf7' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '87de25c2-a81e-554e-893e-e4fe42678336','Compression handoff','In serial (cascaded) compression, the transfer of gain-reduction duty from one compressor to another along the chain, so that each stage acts over a different portion of the dynamic range or responds to different events. A gentler, slower compressor may control broad level changes while a following faster unit catches remaining peaks, the two handing off control as the signal changes.','Sometimes you run a signal through two compressors in a row. One handles the slow, big volume changes. The next one grabs the quick, loud peaks. Control passes, or hands off, from one to the other.','It spreads gain reduction across stages so no single compressor has to do a large, audible amount, which usually sounds more natural than one heavy compressor. Each stage can be tuned for the job it does best.','On a lead vocal, an engineer sets a slow leveling compressor for a few decibels of gentle reduction, then a faster compressor after it to catch peaks, letting control hand off between them.','Compression technique',ARRAY['Serial compression','Compression staging','Attack time','Release time','Peak limiting','Opto compressor']::text[],ARRAY['Setting both compressors to react to the same events, so they pile on gain reduction instead of handing off.','Using heavy ratios on every stage, which stacks the reduction and squashes the signal instead of sharing the work.','Ignoring attack and release differences, so the two units fight rather than covering different parts of the dynamics.']::text[],ARRAY['Cascading a slow leveler and a fast peak compressor on a lead vocal for smooth, transparent control.','Running a broad bus compressor into a faster channel compressor so each catches different dynamic events.','Splitting heavy gain reduction across two mild stages to avoid the pumping of one aggressive compressor.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='87de25c2-a81e-554e-893e-e4fe42678336' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Compression handoff'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '87de25c2-a81e-554e-893e-e4fe42678336','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='87de25c2-a81e-554e-893e-e4fe42678336' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '98096938-aa4d-5c0f-ba58-bda80b89e946','Compression riding','The practice of manually adjusting a signal''s level, by riding the fader or writing gain automation, before or alongside a compressor, so the compressor is presented with a more even signal and has less automatic gain reduction to do. It combines human, context-aware level control with the compressor''s fast automatic control.','Riding means moving the volume fader by hand as a part plays. You smooth out the big level changes yourself first. Then the compressor only has to handle the small, fast ones.','Pre-riding removes slow, large level swings that a compressor handles poorly or audibly, letting the compressor work gently on fast peaks for a more natural result. It puts musical decisions in human hands and mechanical ones in the compressor.','An engineer writes clip or fader gain automation to lift quiet vocal words and tame loud ones, then lets a light compressor catch what remains, avoiding heavy pumping.','Compression technique',ARRAY['Gain automation','Fader automation','Clip gain','Makeup gain','Serial compression','Gain staging']::text[],ARRAY['Relying on the compressor alone for large level swings, which forces heavy, audible gain reduction that manual riding would prevent.','Riding after the compressor instead of before it, so the compressor still reacts to the unevenness you meant to remove.','Writing automation so aggressively that it flattens natural dynamics the compressor was never straining against.']::text[],ARRAY['Evening out a vocal''s phrase-to-phrase level with clip gain before a gentle compressor.','Riding a bass performance''s loud and quiet notes by hand so the compressor works transparently.','Automating a dialogue track''s level in post before compression to keep speech consistent.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='98096938-aa4d-5c0f-ba58-bda80b89e946' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Compression riding'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '98096938-aa4d-5c0f-ba58-bda80b89e946','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='98096938-aa4d-5c0f-ba58-bda80b89e946' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '120a9520-79b9-5b31-9d06-1b9057ba6a7e','Compression staging','The deliberate arrangement of compression across multiple points in a signal path, such as channel, group or bus, and mix bus, so that each stage contributes a modest amount of gain reduction toward the overall dynamic control and the level feeding each compressor sits in its optimal operating range. It applies gain-staging discipline to how and where compression is distributed.','Instead of one compressor doing all the work, you spread the job over several. A little on the track, a little on the group, a little on the mix. Each one only does a small amount.','Spreading gain reduction over stages keeps any single compressor from working hard enough to sound obvious, and it ensures each compressor receives a level it handles well. The result is tighter overall control with fewer artifacts.','An engineer applies light compression on individual vocals, a touch more on the vocal group bus, and a small amount on the mix bus, so the total control is shared and transparent.','Compression technique',ARRAY['Gain staging','Compression handoff','Serial compression','Bus compression','Mix bus','Makeup gain']::text[],ARRAY['Putting all the gain reduction on one stage, which sounds heavy, instead of sharing it across the chain.','Ignoring gain levels between stages, so a compressor is fed too hot or too quiet to work in its sweet spot.','Stacking heavy compression at every stage, so the reductions add up and over-squash the signal.']::text[],ARRAY['Distributing light compression across channel, group, and mix bus on a vocal-heavy production.','Setting input levels so each compressor in the chain operates correctly around its threshold.','Planning where compression happens in a large session so the master bus does not do all the work.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='120a9520-79b9-5b31-9d06-1b9057ba6a7e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Compression staging'),'[^a-z0-9]','','g'));
