INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b56c4046-bc01-5829-8ae4-1de94228f2d7','Compression-into-EQ','A signal-chain order in which a compressor is placed before an equalizer, so the dynamics are controlled first and the equalizer then shapes the tone of the already-compressed signal. Because the equalizer sits after the compressor''s detector, its boosts and cuts do not change how the compressor reacts.','This means you put the compressor first and the equalizer second. The compressor evens out the volume. Then the equalizer shapes the tone, without changing how the compressor behaved.','Placing equalization after compression lets you shape tone on a signal whose level is already stable, and prevents your tonal boosts from re-triggering the compressor. It separates dynamic control from final tone shaping.','An engineer compresses a bass first to steady its level, then equalizes the compressed signal to add definition, knowing the boost will not make the compressor clamp harder.','Signal chain order',ARRAY['EQ-into-compression','Corrective-before-character processing','Complementary pre/post equalization','Signal flow','Makeup gain','Side-chain equalization']::text[],ARRAY['Assuming the order does not matter; compressing before or after equalization gives clearly different results.','Boosting a frequency with equalization after compression and expecting the compressor to react to it, which it will not, because it is upstream.','Forgetting that heavy post-compression boosts can push the signal into the next stage''s headroom limit.']::text[],ARRAY['Steadying a bass with compression, then adding equalized definition without retriggering the compressor.','Choosing compress-then-equalize so tonal changes do not alter the gain reduction.','Comparing compression-into-EQ against EQ-into-compression to hear which suits a vocal.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b56c4046-bc01-5829-8ae4-1de94228f2d7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Compression-into-EQ'),'[^a-z0-9]','','g'));
