WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b56c4046-bc01-5829-8ae4-1de94228f2d7' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'daff8825-ed0b-5384-ae56-d377c59ddb50','Contour equalization','Broad, gently shaped equalization applied to the overall spectral contour of a source, raising or lowering wide frequency regions to reshape its tonal envelope, rather than making narrow surgical corrections. The term is also used for fixed contour or loudness controls that apply a preset musical curve, historically related to the ear''s equal-loudness behavior.','Contour equalization shapes the broad tone of a sound with wide, smooth moves. Instead of fixing one narrow problem, you tilt whole regions up or down. It sculpts the overall character.','It shapes the general tonal balance and character of a source using broad strokes, which usually sounds more natural and musical than sharp narrow filtering. It exists to sculpt tone rather than to remove specific faults.','An engineer uses wide, low-Q shelves and bells to warm or brighten a source''s overall character, shaping its contour to sit in the mix without surgical cuts.','Equalization technique',ARRAY['Corrective equalization','Complementary pre/post equalization','Shelving filter','Q factor','Equal-loudness contour','Tone shaping','Broad-stroke equalization (near-synonym; both are wide, gentle, low-Q tonal shaping, but broad-stroke lacks the fixed loudness/contour-curve sense)']::text[],ARRAY['Using high-Q, narrow bands for broad tone shaping, which sounds unnatural; contour equalization is meant to be wide and gentle.','Confusing contour equalization (broad tone shaping) with corrective equalization (removing a specific problem frequency).','Boosting large regions heavily and then clipping the next stage, because broad boosts add a lot of level.']::text[],ARRAY['Warming a thin acoustic guitar with a wide low-mid lift to reshape its overall tone.','Applying a gentle high shelf to brighten a whole mix''s contour.','Using a console''s fixed contour or loudness curve to add character quickly.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='daff8825-ed0b-5384-ae56-d377c59ddb50' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Contour equalization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'daff8825-ed0b-5384-ae56-d377c59ddb50','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='daff8825-ed0b-5384-ae56-d377c59ddb50' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '39010959-3f05-55ec-804f-f9d04efd7a75','Control-before-character processing','A signal-chain philosophy in which processing that establishes control, meaning level and dynamics management such as compression, gain riding, or corrective gain, precedes processing that adds character or color such as saturation, tone shaping, or vibe emulations. The controlled, stable signal is then fed into the character stage for consistent coloration.','First you get the sound under control, steady and even in level. Then you add flavor, like warmth or saturation. Doing control first makes the flavor stage behave consistently.','Controlling dynamics before adding character means the color stage receives a steady input and colors it evenly, instead of reacting wildly to peaks. It orders the chain so each stage does its job on a predictable signal.','An engineer compresses a vocal to steady its level, then drives it into a saturator, so the saturation stays even instead of flaring on loud words.','Signal chain order',ARRAY['Corrective-before-character processing','Compression-into-EQ','Saturation','Bus compression','Signal flow','Makeup gain','Character-before-control processing (opposite ordering — tone/character first, then control/dynamics)']::text[],ARRAY['Adding heavy character or saturation before controlling dynamics, so peaks distort unevenly and unpredictably.','Treating the two roles as the same; control and character stages have different jobs and belong in order.','Over-controlling first, leaving the character stage a lifeless signal with no dynamics to react to.']::text[],ARRAY['Compressing a vocal for consistency before feeding it into a tape or tube saturator.','Leveling a bass, then adding harmonic drive so the color is even across notes.','Ordering a mastering chain so dynamics are managed before coloration.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='39010959-3f05-55ec-804f-f9d04efd7a75' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Control-before-character processing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '39010959-3f05-55ec-804f-f9d04efd7a75','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='39010959-3f05-55ec-804f-f9d04efd7a75' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2a0a3cc3-26b2-5177-acc0-dcd66c396091','Corrective equalization','Equalization used to remove or fix specific spectral problems in a source, such as resonances, room modes, low-frequency rumble, harshness, proximity buildup, or masking frequencies, typically with cuts and often narrow bandwidths. It aims to make a source accurate and clean rather than to add tonal character.','Corrective equalization fixes problems in a sound. You find a bad frequency, like a boomy note or a harsh ring, and cut it. The goal is to clean up, not to add flavor.','It exists to fix faults, such as resonances, rumble, harshness, or frequencies that clash with other tracks, so a source sits cleanly in the mix. It restores accuracy rather than adding color.','A technician sweeps a narrow boost to find a ringing resonance on a snare or a boxy tone on a guitar, then cuts that frequency to clean the sound.','Equalization technique',ARRAY['Contour equalization','Complementary pre/post equalization','Q factor','High-pass filter','Notch filter','Resonance']::text[],ARRAY['Boosting to fix a problem when a cut is cleaner; corrective equalization usually removes rather than adds.','Using too wide a bandwidth to remove a narrow resonance, taking out good frequencies with the bad.','Leaving a sweep boost in place after finding a resonance instead of turning it into a cut.']::text[],ARRAY['Cutting a ringing resonance found by sweeping a narrow band on a tom.','Removing low-frequency rumble from a vocal with a high-pass filter.','Notching a feedback frequency on a live vocal channel.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2a0a3cc3-26b2-5177-acc0-dcd66c396091' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Corrective equalization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '2a0a3cc3-26b2-5177-acc0-dcd66c396091','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='2a0a3cc3-26b2-5177-acc0-dcd66c396091' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3be8aa31-f8f5-5baf-a119-454df333650f','Corrective-before-character processing','A signal-chain philosophy in which corrective processing, fixing problems such as removing resonances, controlling dynamics, or cleaning noise, comes before character processing that adds color or musical shaping. The cleaned, corrected signal is then colored, so faults are not amplified or emphasized by the character stage.','First you fix the problems in a sound, like harsh or boomy notes. Then you add character, like warmth or drive. Fixing first stops the flavor stage from making the faults worse.','Correcting faults before adding character prevents the color stage from emphasizing problems you would then have to fix again downstream. It keeps the workflow logical: clean first, flavor second.','An engineer notches a guitar''s harsh resonance and high-passes rumble first, then adds a tube saturator, so the saturation colors a clean signal rather than a harsh one.','Signal chain order',ARRAY['Control-before-character processing','Corrective equalization','Compression-into-EQ','Saturation','Notch filter','Signal flow']::text[],ARRAY['Adding saturation or character first, which emphasizes a resonance or noise you then struggle to remove.','Confusing corrective processing (fixing faults) with character processing (adding color); they have opposite goals and belong in order.','Skipping correction entirely and hoping character processing will hide the problems, when it usually amplifies them.']::text[],ARRAY['Cleaning a guitar''s harshness and rumble before feeding it to a tube saturator.','De-noising and de-essing a vocal before adding analog-style color.','Ordering a mastering chain so problem-fixing precedes tonal coloration.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3be8aa31-f8f5-5baf-a119-454df333650f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Corrective-before-character processing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '3be8aa31-f8f5-5baf-a119-454df333650f','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='3be8aa31-f8f5-5baf-a119-454df333650f' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'cdf017ef-ab9f-5587-bb96-a2d75a41a326','Crest-factor reduction','A reduction in a signal''s crest factor, the ratio of its peak amplitude to its RMS (average) level, usually expressed in decibels, achieved by dynamics processing such as compression or limiting that lowers peaks relative to the average level. Reducing crest factor lets the average level, and after makeup gain the perceived loudness, rise without exceeding a peak ceiling.','Crest factor is the gap between a signal''s loudest peaks and its average level. Compressors and limiters shrink that gap by pulling the peaks down. This lets you raise the overall volume without the peaks going too high.','It packs more average energy under a fixed peak ceiling, which is how limiting and compression make tracks louder and steadier. Reducing crest factor is the core mechanism behind loudness maximization.','A mastering engineer uses a limiter to reduce the crest factor of a mix, then applies makeup gain so the track is louder while its peaks still stay below full scale.','Dynamics control',ARRAY['Peak limiting','RMS level','Makeup gain','Loudness','True peak','Compression ratio']::text[],ARRAY['Reducing crest factor so aggressively that transients are flattened and the audio sounds dull and lifeless.','Confusing peak level with crest factor; crest factor is the difference between peak and average, not the peak alone.','Assuming lower crest factor always means louder, when over-limiting can trigger distortion and inter-sample peaks.']::text[],ARRAY['Limiting a master to raise average loudness while holding peaks below full scale.','Compressing a snare to reduce its high crest factor so it sits steadier in a bus.','Comparing the crest factor of a mix before and after mastering to judge how hard it was processed.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='cdf017ef-ab9f-5587-bb96-a2d75a41a326' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Crest-factor reduction'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'cdf017ef-ab9f-5587-bb96-a2d75a41a326','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='cdf017ef-ab9f-5587-bb96-a2d75a41a326' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e9cdf62d-dd9c-5fcc-bb37-b4718a004495','Cross-source compression','Compression that acts across more than one source at once, so their dynamics become linked, typically by routing several sources through a shared compressor (bus or glue compression) so they rise and fall together, or by using one source to key the gain reduction of another through a side-chain. The shared control couples the sources'' levels rather than treating each in isolation.','This is compression that links more than one sound source together. You might send several tracks through one compressor so they move as a group. Or you let one sound control the volume of another.','Linking sources through shared compression makes them feel glued together and move as one, or lets one part make room for another. It exists to control the relationship between sources, not just each source alone.','An engineer buses drums through one compressor so the kit breathes together, or side-chains a bass to the kick so the bass ducks each time the kick hits.','Compression technique',ARRAY['Bus compression','Side-chain compression','Glue compression','Ducking','Parallel compression','Stereo linking']::text[],ARRAY['Expecting a shared compressor to treat each source independently; it reacts to the combined signal, so the loudest source drives the gain reduction.','Setting the compressor too fast or too hard on a bus, so one loud source pumps all the others.','Forgetting to link or key from the intended source, so the wrong element controls the compression.']::text[],ARRAY['Gluing a drum kit together by bussing it through a single compressor.','Side-chaining a bass to the kick so it ducks and leaves room for the low end.','Compressing a backing-vocal group as one so the stack moves cohesively.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e9cdf62d-dd9c-5fcc-bb37-b4718a004495' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cross-source compression'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e9cdf62d-dd9c-5fcc-bb37-b4718a004495','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e9cdf62d-dd9c-5fcc-bb37-b4718a004495' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'effefe5c-f4a6-570d-9ea7-b2085ff4f844','Crossover modulation artifact','An audible coloration or modulation introduced near a crossover frequency in multiband dynamics processing (and, in an analogous way, in loudspeaker or amplifier crossovers), arising because adjacent frequency bands are processed with different, time-varying gains while the crossover filters overlap and shift phase around that frequency. As the band gains change, the way the bands recombine at the crossover shifts, modulating the level and phase of frequencies near the split.','A multiband processor splits sound into low, mid, and high bands. It treats each band on its own. The bands overlap where they meet. If their levels change at different times, that overlap wobbles. This adds a faint, shifting color to the sound.','Naming this artifact helps engineers recognize why aggressive multiband processing can add a swirling or hollow quality around band edges, so they can choose crossover points and settings that avoid it. It flags a real limitation of splitting a signal into bands.','When heavy multiband compression makes a mix sound phasey around a crossover frequency, an engineer moves the crossover point or eases that band''s ratio to reduce the modulation.','Processing artifact',ARRAY['Multiband compression','Crossover filter','Phase shift','Group delay','Pumping','Band splitting']::text[],ARRAY['Placing a crossover right on an important tonal region, so the modulation artifact colors the most audible part of the source.','Blaming the compressor''s ratio alone for phasey artifacts when the crossover filters'' phase behavior is the cause.','Assuming more bands always sound cleaner; each added crossover introduces another point where modulation can occur.']::text[],ARRAY['Hearing a hollow, phasey quality around a crossover point during heavy multiband mastering.','Adjusting crossover frequencies to move an artifact away from a vocal''s key range.','Comparing linear-phase and minimum-phase multiband modes to reduce crossover coloration.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='effefe5c-f4a6-570d-9ea7-b2085ff4f844' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Crossover modulation artifact'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'effefe5c-f4a6-570d-9ea7-b2085ff4f844','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='effefe5c-f4a6-570d-9ea7-b2085ff4f844' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a8fd68dd-02e1-5b90-8fdd-f917d79c63c4','Crush bus','An auxiliary bus set up with heavy, aggressive compression, and often saturation, into which selected sources are sent and then blended underneath the uncompressed signal in parallel. The crushed bus adds density, sustain, and aggression while the dry signal preserves the transients and natural dynamics.','A crush bus is a copy of a sound that you compress very hard, almost crushing it. You mix that squashed copy quietly under the normal sound. It adds punch and thickness without losing the natural attack.','It provides parallel heavy compression: the crushed copy raises low-level detail and density while the untouched main signal keeps the punch, giving weight and loudness without squashing the dynamics. It exists to add aggression while keeping transients.','An engineer sends drums to a crush bus, compresses it hard with fast settings, maybe adds distortion, then blends it low under the dry kit for extra body and attack.','Compression technique',ARRAY['Parallel compression','New York compression','Bus compression','Saturation','Aux send','Makeup gain']::text[],ARRAY['Blending the crush bus so loud that it overtakes the dry signal, destroying the transients you meant to keep.','Forgetting that latency and phase differences on the parallel path can thin the sound if the buses are not aligned or in phase.','Thinking the crushed bus alone is the sound; its value comes from mixing it under the clean signal.']::text[],ARRAY['Adding weight and aggression to a drum bus by blending in a hard-crushed parallel copy.','Thickening a rock vocal with a distorted, heavily compressed parallel bus.','Bringing up the sustain of a room mic with parallel crush compression.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a8fd68dd-02e1-5b90-8fdd-f917d79c63c4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Crush bus'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a8fd68dd-02e1-5b90-8fdd-f917d79c63c4','d42dcf1d-a730-488c-9633-28e1218563a4',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a8fd68dd-02e1-5b90-8fdd-f917d79c63c4' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6a08428d-dd3a-575b-b7be-483664e88876','De-emphasized distortion','Harmonic distortion whose audibility is deliberately reduced, or de-emphasized, after it is generated. In the classic technical sense a de-emphasis (high-frequency cut) filter follows a stage whose input was pre-emphasized, so distortion products created in the boosted high band are attenuated on output; more broadly in mixing it refers to added saturation or distortion that is tucked back with equalization or parallel level blending so it adds harmonic density without an overt distorted quality.','This is distortion that is added on purpose, then quieted down so you barely notice it. You might cut its harsh highs, or mix it in low under the clean sound. It adds warmth and richness without sounding obviously distorted.','De-emphasizing distortion keeps the useful part, the added harmonics, density, and character, while reducing the harsh or obvious side of it, so a source gains richness without sounding broken. In pre- and de-emphasis systems it also lowers noise and distortion in the high band.','An engineer drives a saturator for harmonics, then rolls off the harsh top or blends the distorted signal low under the dry, so the track is thicker without audible grit.','Saturation artifact',ARRAY['Saturation','Pre-emphasis','Harmonic distortion','Parallel compression','Crush bus','High-shelf filter']::text[],ARRAY['Adding distortion and cutting only the highs, assuming that removes all harshness, when some intermodulation and lower harmonics remain.','Blending the distorted signal too loud, so it stops being subtle and the grit becomes obvious.','Confusing de-emphasis (reducing the distortion''s prominence afterward) with simply using less distortion at the source.']::text[],ARRAY['Saturating a bass for harmonics, then rolling off the harsh top so it stays warm, not fizzy.','Blending a heavily distorted parallel copy low under a clean vocal for density.','Using pre-emphasis before a noisy stage and de-emphasis after to lower high-band noise and distortion.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6a08428d-dd3a-575b-b7be-483664e88876' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('De-emphasized distortion'),'[^a-z0-9]','','g'));
