INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '06fc9d80-0d34-530e-8b23-d27d63c1abdf','Descriptor-based equalization','An equalization approach in which the user selects a perceptual or semantic descriptor of the desired timbre (such as "warm," "bright," or "harsh") and the system translates that word into a corresponding frequency-response curve, rather than the user setting frequencies, gains, and bandwidths directly. The descriptor-to-filter mapping is typically derived from listener studies or machine-learning models that associate timbral adjectives with spectral shapes.','With most tone controls you pick exact frequencies to boost or cut. Descriptor-based EQ lets you pick a word instead, like "warm" or "bright." The tool then reshapes the tone to match that word. It turns the adjective into a curve for you.','It exists to make tone shaping faster and more intuitive, letting users describe the sound they want in plain words while the technical filter controls stay hidden behind familiar timbral terms.','An engineer using a semantic or "smart" equalizer selects a word such as "bright" or "boomy," auditions the suggested curve, then fine-tunes it by ear, speeding up rough tonal decisions.','Equalization',ARRAY['Parametric equalizer','Dynamic equalization','Timbre','Frequency response','Spectral balance']::text[],ARRAY['Treating the suggested descriptor curve as a finished result instead of a starting point to fine-tune by ear.','Assuming a word like "warm" maps to the same curve on every source; the mapping is generalized and source-dependent.','Expecting descriptor-based EQ to fix problems that need surgical or dynamic EQ, such as a single resonant note.']::text[],ARRAY['A beginner shaping a vocal quickly by choosing "bright" and adjusting from the suggested curve.','Using a semantic EQ preset to get a warmer guitar tone before manual tweaking.','Comparing how two smart-EQ plugins interpret the descriptor "harsh."']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='06fc9d80-0d34-530e-8b23-d27d63c1abdf' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Descriptor-based equalization'),'[^a-z0-9]','','g'));
