INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6e887059-d63b-5be1-8f58-6c53b70a8455','Detector ripple','The residual alternating-current fluctuation left on a dynamics processor''s detected level (control) signal after the audio is rectified and smoothed, occurring at the input frequency and its harmonics. When the detector''s averaging or smoothing time is short relative to the signal period, especially on low-frequency material, this ripple modulates the gain within each cycle and produces harmonic distortion and audible pumping.','A compressor measures loudness by turning the signal into a smooth level. Detector ripple is a small wobble left on that level. If the wobble is large, the gain shakes with each sound wave. That adds distortion, mostly on low bass sounds.','Naming detector ripple explains the trade-off between fast level tracking and clean gain control, and why very short time constants on bass material cause distortion.','When a compressor sounds gritty or distorted on bass or kick, a technician lengthens the attack and release, or chooses an averaging (RMS) detector, to reduce ripple-induced distortion.','Detector behaviour',ARRAY['Detector signal','RMS detection','Peak detection','Release time','Sidechain','Harmonic distortion']::text[],ARRAY['Setting a very fast release on bass-heavy material and mistaking the resulting ripple distortion for a fault in the source.','Assuming a peak detector is always cleaner than an RMS detector; short peak time constants raise ripple and distortion.','Confusing detector ripple, a control-signal artefact, with clipping in the audio path.']::text[],ARRAY['Compressing a bass guitar with a fast release and hearing added harmonic grit from ripple.','Choosing an averaging detector to keep a sustained low note clean under heavy compression.','Diagnosing low-frequency distortion that appears only when the compressor is active.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6e887059-d63b-5be1-8f58-6c53b70a8455' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Detector ripple'),'[^a-z0-9]','','g'));
