WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6e887059-d63b-5be1-8f58-6c53b70a8455' AND gt.achievement_id='d42dcf1d-a730-488c-9633-28e1218563a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b8f85adc-c3ee-5679-8a0c-3e01715d4f0f','Detector signal','The signal fed to a dynamics processor''s level detector — the control- or side-chain signal it measures to decide how much gain change to apply — as distinct from the main audio that passes through the gain element. It may be an internal copy of the input, an external key input, or a filtered version, and its level, spectrum, and dynamics govern how and when the processor reacts.','A compressor watches one signal to decide when to lower the volume. That watched signal is the detector signal. It is usually a copy of the input. Change it, such as filtering out the bass, and you change when the compressor acts.','Separating the detector signal from the audio path lets a processor be triggered by a shaped version of, or something other than, the sound it affects — the basis of side-chain filtering, de-essing, and ducking.','An engineer filters the detector signal, for example rolling off lows, so a bus compressor stops reacting to kick and bass, or routes an external track into it to trigger ducking.','Sidechain & detection',ARRAY['Sidechain','External-sidechain compression','Detector ripple','Envelope follower','De-essing','Key input']::text[],ARRAY['Thinking the detector signal is what you hear; it only controls gain and is usually absent from the output.','Forgetting that side-chain EQ changes the detector signal, not the processed audio''s tone directly.','Assuming every compressor lets you access or filter the detector signal; many have it fixed internally.']::text[],ARRAY['High-pass filtering the detector signal on a mix-bus compressor to reduce bass-driven pumping.','Setting up de-essing by emphasising sibilant frequencies in the detector signal.','Feeding a kick drum into a bass compressor''s key input as its detector signal.']::text[],'d42dcf1d-a730-488c-9633-28e1218563a4'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b8f85adc-c3ee-5679-8a0c-3e01715d4f0f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Detector signal'),'[^a-z0-9]','','g'));
COMMIT;
